window.HB_TR["acts"]["ur"]=["1. اے تھیوفیلس، میں نے پہلا رسالہ بنایا ہے جو یسوع نے کرنے اور سکھانے کے لیے شروع کیا،\n2۔ اس دن تک جب اسے اٹھایا گیا، اس کے بعد اس نے روح القدس کے ذریعے ان رسولوں کو احکام دیے جنہیں اس نے منتخب کیا تھا:\n3۔ جس کے سامنے اس نے اپنی مصیبت کے بعد کئی ناقابل خطا ثبوتوں کے ذریعے زندہ دکھایا، چالیس دن تک ان میں سے دیکھا گیا، اور خدا کی بادشاہی سے متعلق باتوں کے بارے میں بات کی:\n4۔ اور جب وہ {ان} کے ساتھ جمع ہوئے، تو انہیں حکم دیا کہ وہ یروشلم سے نہ نکلیں، بلکہ باپ کے وعدے کا انتظار کریں، جو {وہ کہتا ہے} کہ آپ نے میرے بارے میں سنا ہے۔ {ہونا...: یا، ساتھ کھانا}\n5۔ کیونکہ یوحنا نے واقعی پانی سے بپتسمہ دیا؛ لیکن تم بہت کم دن بعد روح القدس کے ساتھ بپتسمہ لو گے۔\n6۔ جب وہ دونوں اکٹھے ہوئے، تو انہوں نے اس سے پوچھا، کہا، اے خداوند، کیا تو اس وقت بادشاہی کو اسرائیل کو واپس دے گا؟\n7۔ اور اس نے ان سے کہا، یہ آپ کے لیے نہیں کہ آپ ان اوقات یا موسموں کو جانیں جو باپ نے اپنی طاقت میں رکھے ہیں۔\n8۔ لیکن تم طاقت حاصل کرو گے، جب روح القدس تم پر آ جائے گا: اور تم میرے گواہ بنو گے، یروشلم میں، پورے یہودیہ میں، سامریہ میں، اور زمین کے کونے کونے تک۔ {طاقت...: یا، روح القدس کی طاقت تم پر آ رہی ہے}\n9۔ اور جب اس نے یہ باتیں کہیں، جب وہ دیکھ رہے تھے، اسے اٹھایا گیا؛ اور ایک بادل نے اسے ان کی نظروں سے اوجھل کر لیا۔\n10۔ اور جب وہ آسمان کی طرف مضبوطی سے دیکھ رہے تھے جب وہ اوپر گیا، دیکھو، دو آدمی سفید لباس میں ان کے ساتھ کھڑے تھے؛\n11۔ جس میں یہ بھی کہا گیا، اے گلیل کے لوگو، تم آسمان کی طرف کیوں کھڑے ہو؟ یہی یسوع، جو تم سے آسمان میں اٹھایا گیا ہے، اسی طرح آئے گا جیسے تم نے اسے جنت جاتے دیکھا ہے۔\n12۔ پھر وہ اولیویٹ نامی پہاڑ سے یروشلم واپس آئے، جو یروشلم سے سبت کے دن کا سفر ہے۔\n13۔ اور جب وہ اندر آئے، تو وہ اوپر والے کمرے میں چلے گئے، جہاں پطرس، یعقوب، یوحنا، اور اینڈریو، فلپ، اور تھامس، برتھولمیو، اور متی، یعقوب {بیٹا} الفائیس، اور شمعون زیلوٹس، اور یعقوب کا بھائی یھودا (بھائی) دونوں تھے۔\n14۔ یہ سب دعا اور دعا میں ایک ساتھ جاری رہے، عورتوں، مریم یسوع کی ماں کے ساتھ، اور اس کے بھائیوں کے ساتھ۔\n15۔ اور ان دنوں پیٹر شاگردوں کے درمیان کھڑا ہوا اور کہا، (ناموں کی تعداد تقریبا ایک سو بیس تھی،)\n16۔ انسانو {اور} بھائیو، یہ آیت ضرور پوری ہو چکی ہے، جو روح القدس نے داؤد کے منہ سے پہلے یہودا کے بارے میں کہی تھی، جو ان لوگوں کے لیے رہنمائی تھی جنہوں نے یسوع کو لیا۔\n17۔ کیونکہ وہ ہمارے ساتھ نمبر میں تھا، اور اس وزارت کا کچھ حصہ حاصل کر چکا تھا۔\n18۔ اب اس آدمی نے بدکاری کے بدلے ایک کھیت خریدا؛ اور سر کے بل گرتے ہوئے، وہ بیچ میں پھٹ گیا، اور اس کے تمام آنتیں باہر نکل آئیں۔\n19۔ اور یہ یروشلم کے تمام باشندوں کو معلوم تھا؛ جہاں تک اس میدان کو ان کی اصل زبان میں Aceldama کہا جاتا ہے، یعنی خون کا میدان۔\n20۔ کیونکہ زبور کی کتاب میں لکھا ہے، اس کی رہائش ویران ہو، اور کوئی وہاں نہ رہے: اور اس کا بشپ کوئی اور لے لے۔ {بشپ رک: یا، دفتر، یا، چارج}\n21۔ ان لوگوں میں سے جو ہمیشہ ہمارے ساتھ رہے جب خداوند یسوع ہمارے درمیان آتا جاتا رہا،\n22۔ یوحنا کے بپتسمہ سے لے کر اسی دن تک جب وہ ہم سے لیا گیا، انسان کو اس کی قیامت کا گواہ بننے کے لیے مقرر کیا جانا چاہیے۔\n23۔ اور انہوں نے دو کو مقرر کیا، یوسف جسے بارساباس کہا جاتا تھا، جس کا نام جسٹس تھا، اور متیاس۔\n24۔ اور انہوں نے دعا کی اور کہا، اے خداوند، جو سب لوگوں کے دلوں کو جانتا ہے، دکھاؤ کہ کیا تم نے ان دونوں میں سے کسی کو چنا ہے،\n25۔ تاکہ وہ اس وزارت اور رسولی میں حصہ لے سکے، جس سے یہودا نے گناہ کی وجہ سے گرا، تاکہ وہ اپنی جگہ جا سکے۔\n26۔ اور انہوں نے اپنی قسمت تقسیم کی؛ اور سب کچھ میتھیاس پر آ گیا؛ اور انہیں گیارہ رسولوں کے ساتھ نمبر دیا گیا۔","1۔ اور جب پنٹیکوسٹ کا دن مکمل طور پر آیا، تو وہ سب ایک جگہ ایک ہی اتفاق کے ساتھ تھے۔\n2۔ اور اچانک آسمان سے ایک تیز ہوا کی آواز آئی، اور اس نے پورے گھر کو بھر دیا جہاں وہ بیٹھے تھے۔\n3۔ اور ان کے سامنے آگ کی طرح پھٹی ہوئی زبانیں نمودار ہوئیں، اور وہ ہر ایک پر بیٹھ گئیں۔\n4۔ اور وہ سب روح القدس سے بھر گئے، اور دوسری زبانوں سے بولنے لگے، جیسا کہ روح نے انہیں بیان دیا۔\n5۔ اور یروشلم میں یہودی آباد تھے، پرہیزگار لوگ، آسمان کے نیچے ہر قوم سے۔\n6۔ جب یہ بات بیرون ملک سنائی دی، تو ہجوم اکٹھا ہوا اور حیران رہ گیا، کیونکہ ہر شخص نے انہیں اپنی زبان میں بولتے سنا۔ {تھا...: Gr. کی آواز الجھن میں آ گئی: یا، ذہن میں پریشان}\n7۔ اور وہ سب حیران اور حیران رہ گئے، ایک دوسرے سے کہا، دیکھو، کیا یہ سب گلیلیائی بولنے والے نہیں ہیں؟\n8۔ اور ہم ہر انسان کو اپنی زبان میں کیسے سنتے ہیں، جہاں ہم پیدا ہوئے؟\n9۔ پارتھی، میڈی، ایلامی، اور میسوپوٹیمیا کے باشندے، یہودیہ، کیپاڈوکیا، پونٹس اور ایشیا کے باشندے،\n10۔ فریجیا، اور پامفیلیا، مصر میں، اور لیبیا کے کچھ حصوں میں، جو سائرین اور روم کے اجنبیوں کے بارے میں ہیں، یہودی اور مبدل کے بارے میں،\n11۔ کریٹس اور عرب، ہم انہیں اپنی زبانوں میں خدا کے شاندار اعمال سنتے ہیں۔\n12۔ اور وہ سب حیران رہ گئے، اور شک میں مبتلا ہو گئے، ایک دوسرے سے پوچھنے لگے، یہ کیا مطلب ہے؟\n13۔ دوسروں نے مذاق اڑاتے ہوئے کہا، یہ لوگ نئی شراب سے بھرے ہوئے ہیں۔\n14۔ لیکن پطرس گیارہ کے ساتھ کھڑا ہو کر اپنی آواز بلند کی اور ان سے کہا، اے یہودیہ کے لوگو، اور یروشلم میں رہنے والے سب لوگ، یہ بات تمہیں معلوم ہو اور میری بات سنو:\n15۔ کیونکہ یہ نشے میں نہیں ہیں، جیسا کہ آپ سمجھتے ہیں، کیونکہ یہ دن کا تیسرا گھنٹہ ہے۔\n16۔ لیکن یہ وہ بات ہے جو نبی یوئیل نے کہی تھی؛\n17. اور یہ آخری دنوں میں پورا ہو جائے گا، خدا فرماتا ہے، میں اپنی روح سے سب پر برساؤں گا: اور تمہارے بیٹے اور بیٹیاں نبوت کریں گے، اور تمہارے جوان خواب دیکھیں گے، اور تمہارے بوڑھے خواب دیکھیں گے:\n18۔ اور اپنے خادموں اور خادماؤں پر میں اپنی روح کے ان دنوں میں بہاؤں گا؛ اور وہ نبوت کریں گے:\n19۔ اور میں آسمان پر عجائبات دکھاؤں گا، اور زمین کے نیچے نشانیاں دکھاؤں گا؛ خون، آگ، اور دھوئیں کی بھاپ:\n20۔ سورج اندھیرے میں بدل جائے گا، اور چاند خون میں، اس عظیم اور قابل ذکر دن کے آنے سے پہلے:\n21. اور یہ ہو جائے گا، {کہ} جو بھی خداوند کے نام کو پکارے گا، وہ نجات پائے گا۔\n22۔ اے اسرائیلی حضرات، یہ الفاظ سنو؛ ناصرت کے یسوع، ایک شخص جس نے آپ میں خدا کو معجزات، عجائبات اور نشانات کے ذریعے منظور کیا، جو خدا نے آپ کے درمیان کیا، جیسا کہ آپ خود بھی جانتے ہیں:\n23. خدا کی پختہ نصیحت اور علم سے نجات پانے کے بعد، تم نے اسے لیا اور برے ہاتھوں سے مصلوب کیا اور قتل کیا:\n24۔ جسے خدا نے زندہ کیا، موت کے درد کو آزاد کر کے: کیونکہ یہ ممکن نہیں تھا کہ وہ موت کے درد سے آزاد ہو جائے۔\n25۔ کیونکہ داؤد اس کے بارے میں بات کرتا ہے، میں نے خدا کو ہمیشہ میرے سامنے دیکھا، کیونکہ وہ میرے دائیں ہاتھ پر ہے، تاکہ میں نہ ہلوں:\n26۔ اس لیے میرا دل خوش ہوا، اور میری زبان خوش ہوئی؛ مزید برآں، میرا جسم امید میں آرام کرے گا:\n27۔ کیونکہ تم میری روح کو جہنم میں نہیں چھوڑو گے، نہ ہی اپنے مقدس وجود کو فساد دیکھنے دو گے۔\n28۔ تو نے مجھے زندگی کے طریقے متعارف کروا دیے ہیں؛ تم اپنی شکل سے مجھے خوشی سے بھر دو گے۔\n29۔ انسانو {اور} بھائیو، میں آپ سے باپ داؤد کے بارے میں کھل کر بات کرتا ہوں، کہ وہ مر چکا ہے اور دفن بھی ہے، اور اس کی قبر آج تک ہمارے ساتھ ہے۔ {مجھے کرنے دو: یا، میں کر سکتا ہوں}\n30۔ لہٰذا، نبی ہونے کے ناطے، اور یہ جانتے ہوئے کہ خدا نے اس سے قسم کھائی ہے کہ اس کے جسم کے مطابق اس کے پھل کا ہوگا، وہ مسیح کو اس کے تخت پر بیٹھنے کے لیے اٹھا دے گا؛\n31۔ اس نے یہ دیکھ کر مسیح کی قیامت کی بات کی، کہ اس کی روح جہنم میں نہیں چھوڑی گئی، نہ ہی اس کا جسم فساد دیکھتا ہے۔\n32۔ یہ یسوع خدا کو زندہ کر رہا ہے، جس کے گواہ ہم سب ہیں۔\n33۔ لہٰذا، خدا کے دائیں ہاتھ سے بلند ہو کر، اور باپ سے روح القدس کا وعدہ وصول کرنے کے بعد، اس نے یہ وعدہ چھوڑ دیا جو آپ اب دیکھ اور سن رہے ہیں۔\n34۔ کیونکہ داؤد آسمانوں پر نہیں چڑھا، بلکہ وہ خود کہتا ہے، خداوند نے میرے رب سے کہا، تو میرے دائیں ہاتھ پر بیٹھو،\n35۔ جب تک میں تمہارے دشمنوں کو تمہارا پاؤں کا اسٹول نہ بنا دوں۔\n36. لہٰذا تمام اسرائیل کے گھر کو یقین سے معلوم ہو کہ خدا نے وہی یسوع بنایا ہے جسے تم نے مصلوب کیا ہے، خداوند اور مسیح دونوں۔\n37۔ جب انہوں نے یہ سنا، تو ان کے دل میں چبھ گیا، اور انہوں نے پطرس اور باقی رسولوں، انسانو اور بھائیو، سے کہا، ہم کیا کریں؟\n38۔ پھر پطرس نے ان سے کہا، توبہ کرو، اور سب کو یسوع مسیح کے نام پر گناہوں کی معافی کے لیے بپتسمہ دو، اور تم روح القدس کا تحفہ حاصل کرو گے۔\n39۔ کیونکہ وعدہ آپ کو، آپ کے بچوں کو، اور دور دراز سب کو ہے، {حتیٰ کہ} جتنے لوگ ہمارے خدا کو بلائے۔\n40۔ اور اس نے کئی اور الفاظ میں گواہی دی اور نصیحت کی، کہا، اس ناپسندیدہ نسل سے اپنے آپ کو بچاؤ۔\n41۔ پھر جنہوں نے اس کا کلام خوش دلی سے قبول کیا، انہیں بپتسمہ دیا گیا: اور اسی دن ان میں تقریبا تین ہزار جانیں شامل کی گئیں۔\n42۔ اور وہ رسولوں کی تعلیمات اور رفاقت، روٹی توڑنے، اور دعاؤں میں ثابت قدمی سے جاری رہے۔\n43۔ اور ہر جان پر خوف طاری ہوا: اور رسولوں نے بہت سے عجائبات اور نشانات دکھائے۔\n44۔ اور جو سب ایمان لیتے تھے وہ سب مل کر تھے، اور ان کی سب چیزیں مشترک تھیں؛\n45۔ اور ان کی جائیداد اور مال بیچ دیا، اور سب کو تقسیم کر دیا، جیسا کہ ہر انسان کو ضرورت تھی۔\n46۔ اور وہ، روزانہ ایک ساتھ مندر میں چلتے رہتے، اور گھر گھر روٹی توڑتے، خوشی اور دل کے ساتھ گوشت کھاتے، {یا، گھر سے}\n47۔ خدا کی تعریف کرنا، اور سب لوگوں کی رضا مندی حاصل کرنا۔ اور خداوند روزانہ کلیسیا میں وہ چیزیں شامل کرتا ہے جنہیں نجات ملنی چاہیے۔","1۔ اب پطرس اور یوحنا دعا کے وقت ایک ساتھ مندر میں گئے، جو نویں {گھنٹہ} تھا۔\n2۔ اور ایک لنگڑا آدمی اپنی ماں کے پیٹ سے اٹھایا گیا، جسے وہ روزانہ مندر کے دروازے پر لٹا دیتے تھے جسے خوبصورت کہا جاتا ہے، تاکہ وہ ان لوگوں سے صدقہ طلب کرے جو مندر میں داخل ہوتے؛\n3۔ جس نے دیکھا کہ پیٹر اور یوحنا مندر میں جانے والے ہیں، اس نے خیرات مانگی۔\n4۔ اور پطرس، اپنی نظریں یوحنا کے ساتھ اس پر جما کر کہا، \"ہم پر دیکھو۔\n5۔ اور اس نے ان کی بات سننے کی کوشش کی، اس امید میں کہ انہیں کچھ ملے گا۔\n6۔ پھر پطرس نے کہا، چاندی اور سونا میرے پاس نہیں؛ لیکن جو میں نے تمہیں دیا ہے: یسوع مسیح ناصری کے نام پر اٹھو اور چلو۔\n7۔ اور اس نے اسے دائیں ہاتھ سے پکڑ کر اٹھایا، اور فورا اس کے پاؤں اور ٹخنے کی ہڈیاں مضبوط ہو گئیں۔\n8۔ اور وہ چھلانگ لگا کر کھڑا ہوا، چلتا رہا، اور ان کے ساتھ مندر میں داخل ہوا، چلتا ہوا، چھلانگ لگاتے ہوئے، اور خدا کی تعریف کرتا رہا۔\n9۔ اور سب نے اسے چلتے اور خدا کی تعریف کرتے دیکھا:\n10۔ اور وہ جانتے تھے کہ وہی مندر کے خوبصورت دروازے پر خیرات کے لیے بیٹھا تھا: اور وہ اس واقعے پر حیرت اور تعجب سے بھر گئے جو اس کے ساتھ ہوا۔\n11۔ اور جب وہ لنگڑا آدمی جو شفا پایا تھا، پیٹر اور یوحنا کو تھامے ہوئے تھا، تو سب لوگ سلیمان کے برآمدے میں ان کی طرف دوڑے، بہت حیران ہوئے۔\n12۔ اور جب پطرس نے یہ دیکھا، تو اس نے لوگوں کو جواب دیا، اے اسرائیلی لوگو، تم اس پر حیران کیوں ہو؟ یا پھر تم ہمیں اتنی سنجیدگی سے کیوں دیکھتے ہو، جیسے اپنی طاقت یا پاکیزگی سے ہم نے اس آدمی کو چلنے پر مجبور کیا ہو؟\n13۔ ابراہیم، اسحاق کے خدا، اور یعقوب کے خدا، جو ہمارے آباؤ اجداد کا خدا ہے، نے اپنے بیٹے یسوع کو جلال بخشا؛ جسے تم نے چھوڑ دیا، اور پیلاطس کی موجودگی میں انکار کر دیا، جب وہ اسے جانے دینے کا ارادہ رکھتا تھا۔\n14۔ لیکن تم نے مقدس اور عادل کو انکار کیا، اور چاہا کہ تمہیں قاتل دیا جائے؛\n15۔ اور زندگی کے شہزادے کو مار ڈالا، جسے خدا نے مردوں میں سے زندہ کیا؛ جس کے ہم گواہ ہیں۔ {شہزادہ: یا، مصنف}\n16۔ اور اس کا نام ایمان کے ذریعے اس شخص کو مضبوط بناتا ہے، جسے آپ دیکھتے اور جانتے ہیں: ہاں، اس کے ذریعے جو ایمان ہے اس نے اسے آپ سب کی موجودگی میں یہ کامل صحت عطا کی ہے۔\n17. اور اب، بھائیو، میں نے جانا کہ تم نے جہالت سے یہ کیا، جیسا کہ تمہارے حکمرانوں نے بھی کیا۔\n18۔ لیکن وہ چیزیں جو خدا نے پہلے اپنے تمام نبیوں کے منہ سے دکھائی تھیں، کہ مسیح کو تکلیف ہو، اس نے اس طرح پوری کی ہیں۔\n19۔ لہٰذا توبہ کرو، اور تبدیل ہو جاؤ، تاکہ تمہارے گناہ مٹ جائیں، جب خدا کی موجودگی سے تازگی کا وقت آئے؛\n20۔ اور وہ یسوع مسیح کو بھیجے گا، جو پہلے تمہیں بتایا گیا تھا:\n21۔ جسے آسمان کو تمام چیزوں کی واپسی کے وقت تک وصول کرنا ہوگا، جو خدا نے دنیا کے آغاز سے اپنے تمام مقدس نبیوں کے منہ سے کہا ہے۔\n22۔ کیونکہ موسیٰ نے واقعی باپ اجداد سے کہا تھا، ایک نبی تمہارے خدا کو تمہارے بھائیوں میں سے تمہارے لیے اٹھائے، جیسا کہ میں کرتا ہوں؛ تم اسے ہر بات میں سنو گے جو وہ تم سے کہے گا۔\n23۔ اور یہ ہو جائے گا کہ ہر وہ جان، جو اس نبی کو نہ سنے، لوگوں میں سے ختم ہو جائے گا۔\n24۔ جی ہاں، اور سموئیل کے تمام نبی اور بعد کے انبیاء، جتنے بھی بولے، نے بھی ان دنوں کی پیش گوئی کی ہے۔\n25۔ تم انبیاء کی اولاد ہو، اور اس عہد کے ہو جو خدا نے ہمارے باپ اجداد کے ساتھ کیا تھا، اور ابراہیم سے کہا، اور تیری نسل میں زمین کے تمام رشتہ دار بابرکت ہوں گے۔\n26۔ سب سے پہلے خدا نے اپنے بیٹے یسوع کو زندہ کیا، اسے آپ کو برکت دینے کے لیے بھیجا، تاکہ آپ میں سے ہر ایک کو اپنی گناہوں سے دور رکھے۔","1۔ اور جب وہ لوگوں سے بات کر رہے تھے، کاہنوں، مندر کے کپتان، اور صدوقیوں پر آئے، {کپتان: یا، حکمران}\n2۔ اس بات پر افسوس ہوا کہ انہوں نے لوگوں کو تعلیم دی اور یسوع کے ذریعے مردوں سے قیامت کی تبلیغ کی۔\n3۔ اور انہوں نے ان پر ہاتھ رکھا اور انہیں اگلے دن تک روک دیا: کیونکہ اب شام ہو چکی تھی۔\n4۔ اگرچہ ان میں سے بہت سے جنہوں نے یہ لفظ سنا، ایمان لاتے تھے؛ اور مردوں کی تعداد تقریبا پانچ ہزار تھی۔\n5۔ اور کل ایسا ہوا کہ ان کے حکمران، بزرگ، اور کاتب،\n6۔ اور ایناس اعلیٰ کاہن، اور قیافہ، اور یوحنا، اور سکندر، اور جتنے بھی سردار کاهن کے رشتہ دار تھے، یروشلم میں جمع ہوئے۔\n7۔ اور جب انہوں نے انہیں بیچ میں رکھا تو پوچھا، کس طاقت یا نام سے تم نے یہ کیا؟\n8۔ پھر پطرس، جو روح القدس سے بھر گیا تھا، نے ان سے کہا، اے قوم کے حکمرانوں اور اسرائیل کے بزرگو،\n9۔ اگر آج ہم نااہل انسان کے ساتھ کیے گئے نیک عمل کا جائزہ لیں، تو وہ کس طریقے سے مکمل ہوتا ہے؛\n10۔ تم سب اور اسرائیل کی تمام قوم کو معلوم ہو کہ یسوع مسیح ناصرت کے نام پر، جسے تم نے مصلوب کیا، جسے خدا نے مردوں میں سے زندہ کیا، {حتیٰ کہ} اس کے ذریعے یہ آدمی تمہارے سامنے مکمل طور پر کھڑا ہے۔\n11۔ یہ وہ پتھر ہے جو تم معماروں میں سے کسی کو نہیں رکھا گیا، جو اب کونے کا سرہ بن گیا۔\n12۔ کسی اور میں بھی نجات نہیں: کیونکہ آسمان کے نیچے انسانوں میں کوئی اور نام نہیں دیا گیا جس سے ہمیں نجات ملنی چاہیے۔\n13۔ جب انہوں نے پیٹر اور یوحنا کی جرات دیکھی اور انہیں نادان اور نادان لوگ سمجھا، تو وہ حیران رہ گئے؛ اور انہوں نے ان کا علم حاصل کیا، کہ وہ یسوع کے ساتھ تھے۔\n14۔ اور جب انہوں نے اس آدمی کو دیکھا جو شفا پایا اور ان کے ساتھ کھڑا تھا، تو وہ اس کے خلاف کچھ نہ کہہ سکے۔\n15۔ لیکن جب انہوں نے انہیں کونسل سے باہر جانے کا حکم دیا، تو انہوں نے آپس میں مشاورت کی،\n16۔ کہتے ہوئے، ہم ان مردوں کے ساتھ کیا کریں؟ کیونکہ واقعی ان کے ہاتھوں ایک قابل ذکر معجزہ ہوا ہے جو یروشلم میں رہنے والوں کے لیے ظاہر ہوتا ہے؛ اور ہم اس سے انکار نہیں کر سکتے۔\n17۔ لیکن اگر یہ لوگوں میں مزید نہ پھیلے، تو آئیے انہیں سختی سے دھمکی دیں کہ وہ اب سے اس نام پر کسی سے بات نہ کریں۔\n18۔ اور انہوں نے انہیں بلایا اور حکم دیا کہ وہ بالکل نہ بولیں اور نہ ہی یسوع کے نام پر تعلیم دیں۔\n19۔ لیکن پطرس اور یوحنا نے جواب دیا اور ان سے کہا، کیا خدا کی نظر میں یہ درست ہے کہ وہ آپ کی بات خدا سے زیادہ سنے، تو آپ فیصلہ کریں۔\n20۔ کیونکہ ہم وہ باتیں بولے بغیر نہیں رہ سکتے جو ہم نے دیکھی اور سنی ہیں۔\n21۔ تو جب انہوں نے انہیں مزید دھمکی دی، تو انہوں نے انہیں چھوڑ دیا، اور انہیں سزا دینے کا کوئی طریقہ نہ ملا، کیونکہ لوگوں نے خدا کی جلال کی جو کچھ کیا گیا۔\n22۔ کیونکہ وہ آدمی چالیس سال سے زیادہ عمر کا تھا، جس پر یہ شفا کا معجزہ دکھایا گیا تھا۔\n23۔ اور چھوڑ دیے جانے کے بعد، وہ اپنی جماعت میں گئے، اور سردار کاہنوں اور بزرگوں کی باتیں سنائیں۔\n24۔ اور جب انہوں نے یہ سنا، تو انہوں نے ایک آواز خدا کی طرف بلند کی اور کہا، اے خداوند، تو وہ خدا ہے جس نے آسمان، زمین، سمندر اور ان میں موجود سب کچھ بنایا ہے:\n25۔ کس نے اپنے خادم داؤد کے منہ سے کہا، کافر کیوں غصے میں آئے، اور لوگ فضول باتیں کیوں سوچتے ہیں؟\n26۔ زمین کے بادشاہ کھڑے ہوئے، اور حکمران خداوند اور اس کے مسیح کے خلاف جمع ہو گئے۔\n27۔ کیونکہ تمہارے مقدس بچے یسوع کے خلاف سچائی کے لیے، جسے تم نے مسح کیا ہے، ہیرودیس اور پونٹیئس پیلاطس، غیر یہویوں کے ساتھ، اور بنی اسرائیل دونوں اکٹھے ہوئے تھے،\n28۔ کیونکہ جو کچھ بھی تمہارے ہاتھ اور تمہاری نصیحت نے پہلے طے کیا ہے، وہ کرو۔\n29۔ اور اب، اے خداوند، ان کی دھمکیوں کو دیکھو: اور اپنے بندوں کو عطا فرما، تاکہ وہ پوری جرات کے ساتھ تیرا کلام کہہ سکیں،\n30۔ اپنا ہاتھ شفا دینے کے لیے بڑھا کر؛ اور تاکہ تمہارے مقدس بچے یسوع کے نام سے نشانیاں اور عجائبات ہوں۔\n31۔ اور جب انہوں نے دعا کی، تو وہ جگہ ہل گئی جہاں وہ اکٹھے تھے؛ اور وہ سب روح القدس سے بھرے ہوئے تھے، اور انہوں نے خدا کا کلام جرات مندی سے بیان کیا۔\n32۔ اور جو لوگ ایمان رکھتے تھے وہ ایک دل اور ایک روح کے تھے: نہ ہی ان میں سے کوئی ایسا کہتا تھا جو اس کی ملکیت میں سے اس کی اپنی ہو؛ لیکن ان میں سب کچھ مشترک تھا۔\n33۔ اور بڑی طاقت سے رسولوں کو خداوند یسوع کی قیامت کی گواہی دی: اور ان سب پر عظیم فضل تھا۔\n34۔ ان میں سے کوئی بھی کمی نہیں رکھتا تھا: کیونکہ جتنے زمین یا مکانات کے مالک تھے وہ انہیں بیچتے اور جو چیزیں بیچی جاتی تھیں ان کی قیمت لاتے تھے،\n35۔ اور انہیں رسولوں کے قدموں میں لٹا دیا: اور ہر انسان کو ضرورت کے مطابق تقسیم کی گئی۔\n36۔ اور یوسیٰ، جسے رسولوں نے برنابا کا لقب دیا، (جو کہ تعبیر میں تسلی کا بیٹا ہے)، ایک لاوی، {اور} قبرص کے ملک سے،\n37۔ زمین لے کر، اسے بیچ دیا، پیسہ لایا اور رسولوں کے قدموں میں رکھ دیا۔","1۔ لیکن ایک شخص جس کا نام عنانیاس تھا، اپنی بیوی سفیرا کے ساتھ ایک جائیداد بیچ گیا،\n2۔ اور قیمت کا {حصہ} پیچھے رکھ دیا، اس کی بیوی بھی اس سے واقف تھی، اور ایک خاص حصہ لے کر رسولوں کے قدموں میں رکھ دیا۔\n3۔ لیکن پطرس نے کہا، حنانیا، شیطان نے تمہارے دل میں روح القدس سے جھوٹ کیوں بولا، اور زمین کی قیمت کا کچھ حصہ روکنے کے لیے؟ {جھوٹ بولنے: یا، دھوکہ دینے کے لیے}\n4۔ جب تک یہ باقی رہا، کیا یہ تمہارا اپنا نہیں تھا؟ اور جب یہ بیچ دیا گیا، کیا یہ تمہاری اپنی طاقت میں نہیں تھا؟ تم نے یہ چیز اپنے دل میں کیوں پیدا کی؟ تم نے انسانوں سے جھوٹ نہیں بولا، بلکہ خدا سے جھوٹ بولا۔\n5۔ اور حنانیا یہ الفاظ سن کر گر پڑا، اور بھوت کو چھوڑ دیا: اور ان سب پر شدید خوف طاری ہو گیا جنہوں نے یہ باتیں سنیں۔\n6۔ اور نوجوان اٹھے، اسے لپیٹ کر باہر لے گئے اور دفن کر دیا۔\n7۔ اور تقریبا تین گھنٹے بعد، اس کی بیوی، جو نہیں جانتی تھی کہ کیا ہوا، اندر آئی۔\n8۔ اور پطرس نے اس سے جواب دیا، بتاؤ کیا تم نے زمین اتنی قیمت پر بیچی؟ اور اس نے کہا، ہاں، بہت کچھ کے لیے۔\n9۔ پھر پطرس نے اس سے کہا، کیسے تم دونوں نے مل کر خداوند کی روح کو آزمانے کا فیصلہ کیا؟ دیکھو، ان کے پاؤں جنہوں نے تمہارے شوہر کو دفن کیا ہے، وہ دروازے پر ہیں، اور تمہیں باہر لے جائیں گے۔\n10۔ پھر وہ سیدھا اس کے قدموں میں گر گئی، اور بھوت کو حوالے کر دیا: اور نوجوان اندر آئے، اور اسے مردہ پایا، اور اسے اپنے شوہر کے ہاتھوں دفن کر دیا۔\n11۔ اور پوری کلیسیا پر شدید خوف طاری ہو گیا، اور جتنے لوگوں نے یہ باتیں سنیں۔\n12۔ اور رسولوں کے ہاتھوں لوگوں میں کئی نشانیاں اور عجائبات پیدا ہوئے؛ (اور وہ سب ایک ساتھ سلیمان کے برآمدے میں تھے۔\n13۔ اور باقی میں سے کوئی بھی ان کے ساتھ شامل ہونے کی ہمت نہ کر سکا: بلکہ لوگوں نے انہیں بڑھا دیا۔\n14۔ اور ایمان والے خداوند کے ساتھ زیادہ شامل ہوئے، مرد اور عورتیں دونوں کی کثرت تھی۔)\n15۔ یہاں تک کہ انہوں نے بیماروں کو سڑکوں پر نکالا، اور انہیں بستر اور صوفوں پر لٹا دیا، تاکہ کم از کم پطرس کا سایہ جو گزرتا تھا، ان میں سے کچھ پر غالب آ جائے۔ {میں...: یا، ہر گلی میں}\n16۔ اردگرد کے کئی شہر بھی یروشلم کی طرف آئے، بیمار لوگوں اور وہ لوگ جو ناپاک روحوں سے پریشان تھے، اور سب کو شفا ملی۔\n17۔ پھر اعلیٰ کاہن اٹھ کھڑے ہوئے، اور اس کے ساتھ موجود سب (جو صدوقیوں کا فرقہ ہے)، اور غصے سے بھر گئے، {غصہ: یا، حسد}\n18۔ اور رسولوں پر ہاتھ اٹھا کر انہیں عام قید خانے میں ڈال دیا۔\n19۔ لیکن خداوند کے فرشتے نے رات کو قید کے دروازے کھولے اور انہیں باہر نکالا اور کہا،\n20۔ جاؤ، کھڑے ہو کر مندر میں لوگوں سے اس زندگی کے تمام الفاظ سناؤ۔\n21۔ اور جب انہوں نے یہ سنا، تو وہ صبح سویرے مندر میں داخل ہوئے اور تعلیم دی۔ لیکن اعلیٰ کاہن آیا، اور جو اس کے ساتھ تھے، انہوں نے کونسل اور بنی اسرائیل کی تمام سینیٹ کو بلایا اور انہیں قید خانے بھیجا تاکہ انہیں لایا جا سکے۔\n22۔ لیکن جب افسران آئے اور انہیں قید میں نہیں پایا، تو وہ واپس آئے اور کہا،\n23۔ کہتے ہوئے، قید خانے نے واقعی ہمیں مکمل حفاظت کے ساتھ بند پایا، اور محافظ دروازوں کے سامنے کھڑے تھے: لیکن جب ہم نے دروازہ کھولا تو اندر کوئی آدمی نہیں ملا۔\n24۔ جب اعلیٰ کاہن، مندر کے سردار اور سردار کاہنوں نے یہ باتیں سنیں، تو انہیں شک ہوا کہ یہ کہاں تک پہنچے گا۔\n25۔ پھر ایک آیا اور انہیں بتایا، کہ، دیکھو، وہ لوگ جنہیں تم نے قید میں رکھا ہے، مندر میں کھڑے ہیں اور لوگوں کو تعلیم دے رہے ہیں۔\n26۔ پھر کپتان افسران کے ساتھ گیا، اور انہیں بغیر کسی تشدد کے لے آیا: کیونکہ وہ لوگوں سے ڈرتے تھے کہ کہیں انہیں پتھر نہ مار دیا جائے۔\n27۔ اور جب وہ انہیں لے کر آئے تو انہوں نے انہیں کونسل کے سامنے پیش کیا: اور اعلیٰ کاہن نے ان سے پوچھا،\n28۔ کہتے ہوئے، کیا ہم نے تمہیں سختی سے حکم نہیں دیا تھا کہ تم اس نام پر تعلیم نہ دو؟ اور دیکھو، تم نے یروشلم کو اپنی تعلیمات سے بھر دیا ہے، اور اس آدمی کا خون ہم پر ڈالنے کا ارادہ رکھتے ہو۔\n29۔ پھر پطرس اور {دیگر} رسولوں نے جواب دیا اور کہا، ہمیں انسانوں کی بجائے خدا کی اطاعت کرنی چاہیے۔\n30۔ ہمارے باپ اجداد کے خدا نے یسوع کو زندہ کیا، جسے تم نے قتل کیا اور درخت پر لٹکایا۔\n31. خدا نے اپنے دائیں ہاتھ سے شہزادہ اور نجات دہندہ بننے کی تعریف کی ہے، تاکہ وہ اسرائیل کو توبہ دے اور گناہوں کی معافی دے۔\n32۔ اور ہم ان باتوں کے گواہ ہیں؛ اور {اسی طرح} روح القدس بھی، جسے خدا نے ان لوگوں کو دیا ہے جو اس کی اطاعت کرتے ہیں۔\n33۔ جب انہوں نے سنا {یہ} تو ان کے دل میں کٹ لگا دیا گیا، اور انہوں نے انہیں قتل کرنے کی نصیحت کی۔\n34۔ پھر وہاں ایک کونسل میں کھڑا تھا، ایک فریسی، جس کا نام گمالیئل تھا، جو قانون کا ڈاکٹر تھا، سب لوگوں میں شہرت رکھتا تھا، اور اس نے حکم دیا کہ رسولوں کو تھوڑا سا فاصلہ مقرر کیا جائے؛\n35۔ اور میں نے ان سے کہا، اے اسرائیلی لوگو، خبردار رہو کہ ان لوگوں کو چھونے کے لیے کیا کرنا چاہتے ہو۔\n36۔ کیونکہ ان دنوں سے پہلے تھیوداس اٹھ کھڑا تھا، خود کو کسی خاص ہونے کا دعویٰ کرتے ہوئے؛ جن کے ساتھ تقریبا چار سو افراد شامل ہوئے: جو مارے گئے؛ اور سب، جتنے اس کی اطاعت کرتے، بکھر گئے اور ختم ہو گئے۔ {فرمانبرداری: یا، یقین کیا}\n37۔ جب اس شخص نے گلیل کے یھودا کو ٹیکس کے دنوں میں اٹھایا اور بہت سے لوگوں کو اس کے پیچھے نکالا: وہ بھی ہلاک ہو گیا؛ اور سب، {حتیٰ کہ} جتنے اس کی اطاعت کرتے تھے، منتشر ہو گئے۔ {فرمانبرداری: یا، یقین کیا}\n38۔ اور اب میں تم سے کہتا ہوں، ان لوگوں سے دور رہو، اور انہیں چھوڑ دو، کیونکہ اگر یہ مشورہ یا کام انسانوں کا ہو تو یہ بے سود ہوگا:\n39۔ لیکن اگر یہ خدا کی طرف سے ہو، تو تم اسے ختم نہیں کر سکتے؛ تاکہ تم خدا کے خلاف لڑنے کے لیے بھی نہ پاؤ جاؤ۔\n40۔ اور انہوں نے اس سے اتفاق کیا: اور جب انہوں نے رسولوں کو بلایا اور انہیں مارا تو حکم دیا کہ وہ یسوع کے نام پر بات نہ کریں، اور انہیں جانے دیں۔\n41۔ اور وہ کونسل کی موجودگی سے رخصت ہو گئے، خوش ہو کر کہ انہیں اس کے نام کی وجہ سے شرمندگی کا مستحق سمجھا گیا۔\n42. اور روزانہ ہیکل میں، اور ہر گھر میں، وہ یسوع مسیح کی تعلیم اور تبلیغ کرنا چھوڑ دیتے تھے۔","1۔ اور ان دنوں جب شاگردوں کی تعداد بڑھ گئی، یونانیوں کی طرف سے عبرانیوں کے خلاف سرگوشیاں شروع ہوئیں، کیونکہ ان کی بیواؤں کو روزمرہ کی خدمت میں نظر انداز کیا جاتا تھا۔\n2۔ پھر بارہ نے شاگردوں کی کثرت کو بلایا اور کہا، یہ دلیل نہیں کہ ہم خدا کے کلام کو چھوڑ کر دسترخوان پیش کریں۔\n3۔ لہٰذا، بھائیو، اپنے سات ایماندار افراد میں سے دیکھو، جو روح القدس اور حکمت سے بھرے ہوئے ہیں، جنہیں ہم اس کام کے لیے مقرر کر سکتے ہیں۔\n4۔ لیکن ہم خود کو مسلسل دعا اور کلام کی خدمت کے لیے وقف کریں گے۔\n5۔ اور یہ کہاوت پوری قوم کو پسند آئی: اور انہوں نے اسٹیفن کو، جو ایمان اور روح القدس سے بھرا ہوا تھا، اور فلپ، پروکورس، نیکانور، تیمون، پارمیناس، اور نکولس کو انطاکیہ کا مبدل منتخب کیا:\n6۔ جنہیں انہوں نے رسولوں کے سامنے رکھا: اور جب انہوں نے دعا کی تو ان پر ہاتھ رکھ دیے۔\n7۔ اور خدا کا کلام بڑھ گیا؛ اور یروشلم میں شاگردوں کی تعداد بہت بڑھ گئی؛ اور پادریوں کی بڑی تعداد ایمان کے تابع تھی۔\n8۔ اور اسٹیفن، ایمان اور طاقت سے بھرپور، لوگوں میں عظیم عجائبات اور معجزات کر رہا تھا۔\n9۔ پھر اس عبادت گاہ کے کچھ لوگ سامنے آئے، جسے لبرٹینز، سیرینیوں، اسکندریوں اور ان میں سے سیلیشیا اور ایشیا کے کنیسہ کہا جاتا ہے، جنہوں نے اسٹیفن سے اختلاف کیا۔\n10۔ اور وہ اس حکمت اور روح کے سامنے مزاحمت نہ کر سکے جس سے وہ بول رہا تھا۔\n11۔ پھر انہوں نے لوگوں کو اکسایا، جنہوں نے کہا، ہم نے اسے موسیٰ کے خلاف اور خدا کے خلاف کفر آمیز الفاظ کہتے سنا ہے۔\n12۔ اور انہوں نے لوگوں، بزرگوں، اور کاتبوں کو متحرک کیا، اور اس کے پاس آئے، اسے پکڑ لیا، اور اسے کونسل میں لے آئے۔\n13۔ اور جھوٹے گواہ قائم کرو، جو کہتے، یہ آدمی اس مقدس جگہ اور قانون کے خلاف توہین آمیز الفاظ نہیں بولتا:\n14۔ کیونکہ ہم نے اسے کہتے سنا ہے کہ ناصری کا یہ یسوع اس جگہ کو تباہ کر دے گا، اور وہ رسم و رواج بدل دے گا جو موسیٰ نے ہمیں دی تھیں۔ {رسم و رواج: یا، رسومات}\n15۔ اور جو بھی کونسل میں بیٹھا تھا، اس پر مضبوطی سے دیکھ رہا تھا، اس کا چہرہ ایسے دیکھ رہا تھا جیسے وہ کسی فرشتے کا چہرہ ہو۔","1۔ پھر اعلیٰ پادری نے کہا، کیا یہ چیزیں ہیں؟\n2۔ اور اس نے کہا، مردو، بھائیو، اور باپ، سنو؛ جلال کا خدا ہمارے والد ابراہیم پر ظاہر ہوا، جب وہ میسوپوٹیمیا میں تھا، اس سے پہلے کہ وہ چاران میں بسے،\n3۔ اور اس سے کہا، اپنے ملک اور اپنے رشتہ داروں سے نکل جاؤ اور اس زمین میں آ جاؤ جو میں تمہیں دکھاؤں گا۔\n4۔ پھر وہ کلدیوں کی سرزمین سے نکلا اور چاران میں بسنے لگا: اور وہاں سے، جب اس کا باپ فوت ہوا، اس نے اسے اس سرزمین میں منتقل کیا، جہاں تم اب رہتے ہو۔\n5۔ اور اس نے اسے اس میں کوئی وراثت نہیں دی، نہیں، نہ ہی اس پر قدم رکھنے کے لیے، پھر بھی اس نے وعدہ کیا کہ وہ اسے ملکیت کے طور پر دے گا، اور اس کے بعد اس کی نسل کو، جب {ابھی} اس کا کوئی بچہ نہیں تھا۔\n6۔ اور خدا نے اس حکمت سے فرمایا، کہ اس کی نسل کسی اجنبی زمین میں قیام کرے؛ اور کہ انہیں غلامی میں لے آنا چاہیے، اور چار سو سال برائی کی درخواست کرنی چاہیے۔\n7۔ اور جس قوم کے لیے وہ غلام ہوں گے، میں فیصلہ کروں گا، خدا نے فرمایا: اور اس کے بعد وہ باہر آئیں گے اور اس جگہ میری خدمت کریں گے۔\n8۔ اور اس نے اسے ختنہ کا عہد دیا: یوں ابراہیم نے اسحاق کو جنم دیا، اور آٹھویں دن اسے ختنہ کر دیا؛ اور اسحاق نے یعقوب کو پیدا کیا؛ اور یعقوب نے بارہ بزرگوں کو جنم دیا۔\n9۔ اور حسد میں آ کر باپ نے یوسف کو مصر میں بیچ دیا: لیکن خدا اس کے ساتھ تھا،\n10۔ اور اسے اس کی تمام مصیبتوں سے نجات دلائی اور مصر کے بادشاہ فرعون کی نظر میں اسے فضل اور حکمت دی؛ اور اس نے اسے مصر اور اس کے پورے خاندان کا گورنر بنایا۔\n11۔ اب مصر اور حنان کی زمین پر کمی آ گئی، اور بڑی مصیبتیں آئیں: اور ہمارے آباؤ اجداد کو کوئی خوراک نہ ملی۔\n12۔ لیکن جب یعقوب نے سنا کہ مصر میں اناج ہے، تو اس نے پہلے ہمارے آباؤ اجداد کو بھیجا۔\n13۔ اور دوسری {بار} یوسف اپنے بھائیوں کو معلوم ہوا؛ اور یوسف کے رشتہ دار فرعون کو معلوم ہو گئے۔\n14۔ پھر یوسف کو بھیجا، اور اپنے والد یعقوب کو اپنے پاس بلایا، اور اس کے تمام رشتہ داروں، تیساٹھ پندرہ جانوں کو۔\n15. تو یعقوب مصر میں اتر گیا، اور مر گیا، وہ اور ہمارے باپ دادا،\n16۔ اور انہیں سیکیم میں لے جایا گیا، اور اس قبر میں دفن کیا گیا جو ابراہیم نے ایمور [جو سیکیم کے والد} کے بیٹوں کی رقم میں خریدا تھا۔\n17. لیکن جب وعدے کا وقت قریب آیا، جس کی خدا نے ابراہیم سے قسم کھائی تھی، تو لوگ مصر میں بڑھے اور بڑھنے لگے،\n18۔ یہاں تک کہ ایک اور بادشاہ نمودار ہوا، جو یوسف کو نہیں جانتا تھا۔\n19. یہی بات ہمارے رشتہ داروں کے ساتھ بھی باریکی سے پیش آئی، اور ہمارے باپ و دادوں نے برائی کی درخواست کی کہ وہ اپنے چھوٹے بچوں کو نکال دیں، تاکہ وہ زندہ نہ رہیں۔\n20۔ اسی دوران موسیٰ پیدا ہوا، اور وہ انتہائی خوبصورت تھا، اور اپنے والد کے گھر میں تین ماہ تک رہا: {انتہائی خوبصورت: یا خدا کے لیے خوبصورت}\n21۔ اور جب اسے نکال دیا گیا، فرعون کی بیٹی نے اسے اٹھایا اور اپنے بیٹے کے لیے اس کی پرورش کی۔\n22۔ اور موسیٰ مصریوں کی تمام حکمت میں ماہر تھا، اور الفاظ و عمل میں طاقتور تھا۔\n23۔ اور جب وہ چالیس سال کے مکمل ہوئے، تو ان کے دل میں یہ خیال آیا کہ وہ اپنے بھائیوں، بنی اسرائیل سے ملنے جائیں۔\n24۔ اور جب اس نے دیکھا کہ ان میں سے ایک ظلم کر رہا ہے، اس نے اس کا دفاع کیا، مظلوم کا بدلہ لیا، اور مصری کو مارا:\n25۔ کیونکہ اس نے سوچا کہ اس کے بھائی سمجھ گئے ہوں گے کہ خدا اپنے ہاتھ سے انہیں کیسے نجات دے گا: لیکن وہ نہیں سمجھ سکے۔ {کیونکہ: یا، اب}\n26۔ اور اگلے دن اس نے خود کو ان کے سامنے دکھایا جیسا کہ وہ کوشش کر رہے تھے، اور انہیں دوبارہ ایک کر کے کہتا تھا، جنابوں، آپ بھائی ہیں؛ تم ایک دوسرے کے ساتھ ظلم کیوں کرتے ہو؟\n27۔ لیکن جس نے اپنے پڑوسی کے ساتھ زیادتی کی، اس نے اسے دور کر دیا، کہہ دیا، کس نے تمہیں ہمارے اوپر حکمران اور منصف بنایا؟\n28۔ کیا تم مجھے مارو گے، جیسے تم نے کل مصری کو مارا؟\n29۔ پھر موسیٰ اس بات پر بھاگ گیا، اور مادیان کی سرزمین میں اجنبی ہو گیا، جہاں اس کے دو بیٹے ہوئے۔\n30۔ اور جب چالیس سال گزر گئے، تو اسے جبل سینا کے صحرا میں خداوند کا ایک فرشتہ آگ کی آگ میں جھاڑی میں ظاہر ہوا۔\n31۔ جب موسیٰ نے یہ منظر دیکھا، تو وہ اس منظر پر حیران ہوا: اور جب وہ قریب پہنچا اور اسے دیکھنے لگا، تو خداوند کی آواز اس کے پاس آئی،\n32. {کہا}، میں {ہوں} تمہارے باپ و اجداد کا خدا، ابراہیم کا خدا، اسحاق کا خدا، اور یعقوب کا خدا ہوں۔ پھر موسیٰ کانپ گیا، اور دیکھنے کی ہمت نہ کر سکا۔\n33۔ پھر خداوند نے اس سے کہا، اپنے جوتے اپنے قدموں سے اتار دو، کیونکہ جہاں تم کھڑے ہو وہ مقدس زمین ہے۔\n34۔ میں نے دیکھا ہے، میں نے اپنے لوگوں کی مصیبت دیکھی ہے جو مصر میں ہے، اور میں نے ان کی کراہت سنی ہے، اور میں انہیں بچانے کے لیے نیچے آیا ہوں۔ اور اب آؤ، میں تمہیں مصر بھیجوں گا۔\n35۔ یہ موسیٰ ہے جسے انہوں نے انکار کیا اور کہا، کس نے تمہیں حکمران اور قاضی بنایا؟ اسی طرح خدا نے بھی اس فرشتے کے ہاتھ سے حکمران اور نجات دہندہ بننے کے لیے بھیجا جو جھاڑیوں میں اس کے سامنے ظاہر ہوا۔\n36۔ اس نے انہیں باہر نکالا، اس کے بعد اس نے مصر کی زمین، بحیرہ احمر میں، اور چالیس سال تک بیابان میں عجائبات اور نشانیاں دکھائیں۔\n37۔ یہی وہ موسیٰ ہے جس نے بنی اسرائیل سے کہا، خداوند تمہارے خدا کو تمہارے بھائیوں میں سے ایک نبی تمہارے لیے اٹھائے گا، جیسے میرے لیے؛ تم اسے سنو گے۔ {جیسے...: یا، اپنے طور پر}\n38۔ یہ وہی ہے، جو ویرانے میں چرچ میں اس فرشتے کے ساتھ تھا جس نے اس سے کوہ سینا میں بات کی، اور {ہمارے آباؤ اجداد} کے ساتھ: جس نے زندہ دل پیش گوئیاں وصول کیں تاکہ ہمیں دے سکے:\n39۔ جس کی ہمارے باپ اجداد نے اطاعت نہیں کی، بلکہ اسے ان سے نکال دیا، اور اپنے دلوں میں دوبارہ مصر کی طرف لوٹ گئے،\n40۔ ہارون سے کہا، ہمیں خدا بنا دو جو ہمارے سامنے چلیں: کیونکہ اس موسیٰ کے بارے میں، جس نے ہمیں مصر کی سرزمین سے نکالا، ہم نہیں جانتے تھے کہ اس کا کیا ہوا۔\n41۔ اور ان دنوں انہوں نے بچھڑا بنایا، بت کے لیے قربانی دی، اور اپنے ہاتھوں کے کاموں میں خوش ہوئے۔\n42۔ پھر خدا نے پلٹ کر انہیں آسمان کی فوج کی عبادت کے لیے چھوڑ دیا؛ جیسا کہ انبیاء کی کتاب میں لکھا ہے، اے بنی اسرائیل، کیا تم نے مجھے چالیس سال کے عرصے سے جنگل میں مارے گئے جانور اور قربانیاں پیش کیں؟\n43. ہاں، تم نے مولوخ کا خیمہ اور اپنے خدا رمفان کا ستارہ اٹھایا، وہ مجسمے جو تم نے ان کی عبادت کے لیے بنائے تھے: اور میں تمہیں بابل سے باہر لے جاؤں گا۔\n44۔ ہمارے آباؤ اجداد نے ویرانے میں گواہی کا خیمہ رکھا تھا، جیسا کہ انہوں نے موسیٰ سے بات کرتے ہوئے مقرر کیا تھا کہ وہ اسے اسی انداز کے مطابق بنائے جو اس نے دیکھا تھا۔ {بولتے ہوئے: یا، کس نے بات کی}\n45۔ جسے ہمارے بعد آنے والے باپ اجداد نے یسوع کے ساتھ غیر یہودیوں کے قبضے میں لے آئے، جنہیں خدا نے ہمارے آباؤ اجداد کے سامنے نکال دیا، داؤد کے زمانے تک؛ {وہ...: یا، موصول ہونے کے بعد}\n46۔ جس نے خدا کے حضور فضل پایا اور یعقوب کے خدا کے لیے ایک خیمہ تلاش کرنا چاہا۔\n47۔ لیکن سلیمان نے اس کے لیے ایک گھر بنایا۔\n48۔ تاہم سب سے بلند ہاتھ سے بنے ہوئے مندروں میں نہیں رہتا؛ جیسا کہ نبی فرماتا ہے،\n49۔ آسمان {ہے} میرا تخت ہے، اور زمین {ہے} میرا سہارا ہے: تم مجھے کون سا گھر بناؤ گے؟ خداوند فرماتا ہے: یا میری آرام کی جگہ کیا ہے؟\n50۔ کیا یہ سب میرے ہاتھ نے نہیں بنایا؟\n51۔ دل و کانوں میں ضدی اور غیر ختنہ شدہ لوگ، تم ہمیشہ روح القدس کی مزاحمت کرتے ہو: جیسے تمہارے آباؤ اجداد نے کیا، ویسے ہی تم بھی۔\n52۔ آپ کے باپ اجداد نے کس نبی کو ستایا نہیں؟ اور انہوں نے ان لوگوں کو مار ڈالا ہے جنہوں نے پہلے عادل کے آنے کی خبر دی تھی؛ جن میں سے تم اب غدار اور قاتل ہو:\n53۔ جنہوں نے فرشتوں کی مرضی سے قانون حاصل کیا اور اس پر عمل نہیں کیا۔\n54۔ جب انہوں نے یہ باتیں سنیں، تو ان کے دل میں کاٹ دیا گیا، اور انہوں نے [اپنے} دانتوں سے اسے چبائیں۔\n55۔ لیکن وہ، جو روح القدس سے بھرا ہوا تھا، مضبوطی سے آسمان کی طرف دیکھا، اور خدا کی جلال اور یسوع کو خدا کے دائیں ہاتھ پر کھڑا دیکھا،\n56۔ اور کہا، دیکھو، میں آسمان کو کھلتا ہوا دیکھتا ہوں، اور انسان کا بیٹا خدا کے دائیں ہاتھ پر کھڑا ہے۔\n57۔ پھر انہوں نے زور سے پکارا، کان بند کر دیے، اور ایک ساتھ اس پر دوڑے،\n58۔ اور اسے شہر سے نکال دیا اور سنگسار کر دیا: اور گواہوں نے اپنے کپڑے ایک نوجوان کے قدموں میں رکھ دیے، جس کا نام ساؤل تھا۔\n59۔ اور انہوں نے اسٹیفن کو سنگسار کیا، {خدا} کو پکارا، اور کہا، اے خداوند یسوع، میری روح قبول کرو۔\n60۔ اور وہ گھٹنے ٹیک کر زور سے پکارا، اے خداوند، یہ گناہ ان کے سپرد نہ کرے۔ اور جب اس نے یہ کہا، تو وہ سو گیا۔","1۔ اور ساؤل اس کی موت کی رضا مندی دے رہا تھا۔ اور اس وقت یروشلم میں موجود کلیسیا کے خلاف شدید ظلم و ستم تھا؛ اور وہ سب یہودیہ اور سامریہ کے علاقوں میں بکھرے ہوئے تھے، سوائے رسولوں کے۔\n2۔ اور دیندار لوگ اسٹیفن کو {اس کی تدفین کے لیے} لے گئے، اور اس پر بہت افسوس کیا۔\n3۔ جہاں تک ساؤل کا تعلق ہے، اس نے کلیسیا کو تباہ کیا، ہر گھر میں داخل ہو کر مردوں اور عورتوں کو قید میں ڈال دیا۔\n4۔ اسی لیے جو لوگ باہر بکھرے ہوئے تھے، وہ ہر جگہ جا کر کلام کی تبلیغ کرتے تھے۔\n5۔ پھر فلپ سامریہ کے شہر گیا اور ان کے سامنے مسیح کی تبلیغ کی۔\n6۔ اور لوگوں نے ایک ساتھ ان باتوں کو سننا شروع کیا جو فلپ نے کہے، وہ معجزات سن کر اور دیکھتے ہوئے جو اس نے کیے۔\n7۔ کیونکہ ناپاک روحیں، جو زور سے زور سے روتی تھیں، ان میں سے نکلتی تھیں جو جن کے قبضے میں تھے: اور بہت سے جو فالج میں مبتلا تھے اور جو لنگڑے تھے، شفا پائے۔\n8۔ اور اس شہر میں بہت خوشی تھی۔\n9۔ لیکن ایک شخص تھا، جس کا نام شمعون تھا، جو پہلے اسی شہر میں جادو کرتا تھا، اور سامریہ کے لوگوں کو جادو کرتا تھا، یہ ظاہر کرتے ہوئے کہ وہ خود بھی ایک عظیم انسان ہے:\n10۔ جسے سب نے سب نے سنا، چھوٹے سے لے کر سب سے بڑے تک، کہا، یہ انسان خدا کی عظیم طاقت ہے۔\n11۔ اور اس کے لیے وہ احترام رکھتے تھے، کیونکہ طویل عرصے سے اس نے انہیں جادو سے مسحور کیا تھا۔\n12۔ لیکن جب انہوں نے فلپ کو خدا کی بادشاہی اور یسوع مسیح کے نام کے بارے میں تبلیغ کرنے پر ایمان لایا، تو وہ مرد اور عورت دونوں بپتسمہ لے گئے۔\n13۔ تب شمعون خود بھی ایمان لایا: اور جب اس نے بپتسمہ لیا، تو وہ فلپ کے ساتھ گیا، اور حیرت سے معجزات اور نشانات کو دیکھتا رہا۔ {معجزات...: Gr. Signs and Great Miracles}\n14۔ جب یروشلم میں موجود رسولوں نے سنا کہ سامریا نے خدا کا کلام وصول کر لیا ہے، تو انہوں نے ان کے پاس پطرس اور یوحنا بھیجے:\n15۔ جنہوں نے جب وہ نیچے آئے تو ان کے لیے دعا کی کہ وہ روح القدس کو قبول کر سکیں:\n16۔ (کیونکہ ابھی تک وہ ان میں سے کسی پر نہیں گرا تھا: صرف وہی خداوند یسوع کے نام پر بپتسمہ لیے گئے تھے۔)\n17۔ پھر انہوں نے [اپنے] ہاتھ ان پر رکھے، اور انہوں نے روح القدس قبول کیا۔\n18۔ اور جب شمعون نے دیکھا کہ رسولوں کے ہاتھ رکھ کر روح القدس دیا گیا ہے، تو اس نے انہیں پیسے دیے،\n19۔ کہتا ہے، مجھے یہ طاقت بھی دو، تاکہ جس پر میں ہاتھ رکھوں، وہ روح القدس کو قبول کرے۔\n20۔ لیکن پطرس نے اس سے کہا، تمہارا پیسہ تمہارے ساتھ ختم ہو جائے گا، کیونکہ تم نے سوچا تھا کہ خدا کا تحفہ پیسے سے خریدا جا سکتا ہے۔\n21۔ اس معاملے میں نہ تمہارا حصہ ہے نہ قسمت: کیونکہ تمہارا دل خدا کی نظر میں درست نہیں۔\n22۔ اس لیے اپنی برائی سے توبہ کرو، اور خدا سے دعا کرو، اگر تمہارے دل کا خیال تمہیں معاف کر دے۔\n23۔ کیونکہ میں محسوس کرتا ہوں کہ تم تلخی کے جال میں ہو، اور گناہ کے بندھن میں ہو۔\n24۔ پھر شمعون نے جواب دیا اور کہا، \"خداوند سے دعا کرو کہ تم نے جو باتیں کہیں ہیں وہ مجھ پر نہ آئیں۔\n25۔ اور جب انہوں نے گواہی دی اور خداوند کا کلام تبلیغ کیا، تو یروشلم واپس آئے اور سامریوں کے کئی دیہاتوں میں انجیل کی تبلیغ کی۔\n26۔ اور خداوند کے فرشتے نے فلپ سے کہا، اٹھو اور جنوب کی طرف اس راستے پر جاؤ جو یروشلم سے غزہ تک جاتا ہے، جو صحرا ہے۔\n27۔ اور وہ اٹھا اور چلا گیا: اور دیکھو، ایتھوپیا کا ایک آدمی، جو کینڈیس کی ملکہ کے تحت ایک عظیم حکمران خواجہ سرا تھا، جس کے پاس اس کے تمام خزانے کی ذمہ داری تھی، اور وہ یروشلم آیا تھا عبادت کے لیے،\n28۔ واپس آ رہا تھا، اور اپنی رتھ میں بیٹھا اشعیا نبی پڑھ رہا تھا۔\n29۔ پھر روح القدس نے فلپ سے کہا، قریب آؤ، اور اس رتھ میں شامل ہو جاؤ۔\n30۔ اور فلپ وہاں دوڑا اور اس کے پاس گیا، اور اسے نبی عیسیٰ کو پڑھتے سنا، اور کہا، کیا تم وہ سمجھتے ہو جو تم پڑھتے ہو؟\n31۔ اور اس نے کہا، میں کیسے کر سکتا ہوں، سوائے اس کے کہ کوئی مرد مجھے رہنمائی دے؟ اور وہ چاہتا تھا کہ فلپ اوپر آئے اور اس کے ساتھ بیٹھے۔\n32۔ اس کتاب مقدس کی جگہ جو اس نے پڑھی وہ یہ تھی: اسے بھیڑ کی طرح ذبح کے لیے لے جایا گیا؛ اور جیسے ایک بھیڑ اپنے کاٹنے والے کے سامنے گونگا ہو گیا ہو، اس نے منہ نہ کھولا:\n33۔ اس کی ذلت میں اس کا فیصلہ چھین لیا گیا: اور اس کی نسل کا اعلان کون کرے گا؟ کیونکہ اس کی جان زمین سے چھین لی گئی ہے۔\n34۔ اور ایونک نے فلپ کو جواب دیا اور کہا، میں تم سے دعا کرتا ہوں، جس کے بارے میں نبی یہ بات کرتا ہے؟ اپنے آپ سے، یا کسی اور آدمی کا؟\n35۔ پھر فلپ نے منہ کھولا، اور اسی آیت سے شروع کیا، اور اسے یسوع کی تبلیغ کی۔\n36۔ اور جب وہ اپنی راہ پر چل رہے تھے، تو ایک خاص پانی تک پہنچے: اور خواجہ سرا نے کہا، دیکھو، {یہاں ہے} پانی؛ کیا چیز مجھے بپتسمہ لینے سے روکتی ہے؟\n37۔ اور فلپ نے کہا، اگر تم پورے دل سے ایمان رکھتے ہو تو کر سکتے ہو۔ اور اس نے جواب دیا اور کہا، میں ایمان رکھتا ہوں کہ یسوع مسیح خدا کا بیٹا ہے۔\n38۔ اور اس نے رتھ کو رکنے کا حکم دیا: اور وہ دونوں پانی میں گر گئے، فلپ اور خواجہ سرا دونوں؛ اور اس نے اسے بپتسمہ دیا۔\n39۔ اور جب وہ پانی سے باہر آئے، تو خداوند کی روح نے فلپ کو پکڑ لیا، کہ خواجہ سرا نے اسے دوبارہ نہیں دیکھا، اور وہ خوشی سے روانہ ہو گیا۔\n40۔ لیکن فلپ آزوٹس میں پایا گیا: اور وہاں سے گزرتے ہوئے وہ تمام شہروں میں تبلیغ کرتا رہا، یہاں تک کہ قیصریہ پہنچا۔","1۔ اور ساؤل، جو خدا کے شاگردوں کے خلاف دھمکیاں اور قتل عام کر رہا تھا، سردار کاہن کے پاس گیا،\n2۔ اور اس سے دعا کی کہ وہ دمشق کو عبادت گاہوں کو خطوط بھیجے، کہ اگر اسے اس راستے میں سے کوئی مل جائے، چاہے وہ مرد ہوں یا عورتیں، تو وہ انہیں یروشلم میں باندھ دے۔ {اس راستے: Gr. of the way}\n3۔ اور جب وہ سفر کر رہا تھا، وہ دمشق کے قریب پہنچا: اور اچانک اس کے ارد گرد آسمان سے ایک روشنی چمک اٹھی:\n4۔ اور وہ زمین پر گر گیا، اور اس نے ایک آواز سنی جو اسے کہہ رہی تھی: ساؤل، ساؤل، تم مجھے کیوں ستاتے ہو؟\n5۔ اور اس نے کہا، اے خداوند، تو کون ہو؟ اور خداوند نے فرمایا، میں یسوع ہوں جسے تم ستاتے ہو: تمہارے لیے ان کمینوں کے خلاف لات مارنا مشکل ہے۔\n6۔ اور وہ کانپتے اور حیران ہو کر بولا، اے خداوند، تو مجھ سے کیا کرنے کو کہہ رہے ہو؟ اور خداوند نے اس سے فرمایا، اٹھو اور شہر میں جاؤ، اور تمہیں بتایا جائے گا کہ تمہیں کیا کرنا ہے۔\n7۔ اور جو لوگ اس کے ساتھ سفر کر رہے تھے، وہ بے زبان کھڑے رہے، آواز سن رہے تھے، مگر کسی کو نظر نہیں آ رہے تھے۔\n8۔ اور ساؤل زمین سے اٹھا؛ اور جب اس کی آنکھیں کھلیں تو اس نے کوئی آدمی نہیں دیکھا: لیکن انہوں نے اسے ہاتھ پکڑ کر دمشق لے گئے۔\n9۔ اور وہ تین دن بے بینائی رہا، نہ کھایا نہ پیا۔\n10۔ اور دمشق میں ایک خاص شاگرد تھا، جس کا نام عنانیا تھا؛ اور خداوند نے اس سے ایک خواب میں کہا، حنانیا۔ اور اس نے کہا، دیکھو، میں {یہاں ہوں}، خداوند۔\n11۔ اور خداوند نے اس سے فرمایا، اٹھو، اور اس گلی میں جاؤ جسے سیدھا کہا جاتا ہے، اور یہوداہ کے گھر میں اس سے پوچھو کہ وہ ساؤل، طرسوس کا ہے، کیونکہ دیکھو، وہ دعا کرتا ہے،\n12۔ اور اس نے خواب میں ایک آدمی عنانیا کو دیکھا جو آ رہا ہے، اور اس پر ہاتھ رکھ رہا ہے تاکہ وہ اپنی بینائی حاصل کر سکے۔\n13۔ پھر حنانیا نے جواب دیا، اے خداوند، میں نے اس آدمی میں سے بہت سے لوگوں سے سنا ہے کہ اس نے یروشلم میں تیرے مقدسین کے ساتھ کتنی بری کی ہے:\n14۔ اور یہاں اسے سردار کاهنوں کی طرف سے اختیار حاصل ہے کہ وہ تیرے نام پر پکارنے والوں کو پابند کرے۔\n15۔ لیکن خداوند نے اس سے کہا، اپنا راستہ چلو، کیونکہ وہ میرے لیے ایک منتخب برتن ہے، جو میرا نام غیر یہودیوں، بادشاہوں اور بنی اسرائیل کے سامنے اٹھائے گا:\n16۔ کیونکہ میں اسے دکھاؤں گا کہ میرے نام کے لیے اسے کتنی بڑی مشکلات برداشت کرنی ہوں گی۔\n17۔ اور عنانیاس اس کی طرف گیا، اور گھر میں داخل ہوا؛ اور اس پر ہاتھ رکھ کر کہا، بھائی ساؤل، خداوند، {حتیٰ کہ} یسوع، جو تمہیں اس راستے میں ظاہر ہوا جب تم آئے، مجھے بھیجا ہے تاکہ تم اپنی نظر حاصل کر سکو اور روح القدس سے بھر سکو۔\n18۔ اور فورا اس کی آنکھوں سے وہ چھلکے کی طرح گر گئے: اور وہ فورا نظر آ گیا، اٹھا اور بپتسمہ لیا۔\n19۔ اور جب اسے گوشت ملا، تو وہ مضبوط ہو گیا۔ پھر شاول کچھ دن ایسے تھے جب شاگردوں کے ساتھ دمشق میں تھے۔\n20۔ اور فورا اس نے عبادت گاہوں میں مسیح کی تبلیغ کی کہ وہ خدا کا بیٹا ہے۔\n21۔ لیکن جو بھی اس کی بات سننے والا تھا وہ حیران رہ گیا اور کہا؛ کیا یہی وہ نہیں ہے جس نے یروشلم میں ان لوگوں کو تباہ کیا جنہوں نے اس نام کو پکارا، اور اسی نیت سے یہاں آیا تاکہ انہیں سردار کاہنوں کے پاس باندھ سکے؟\n22۔ لیکن شاول کی طاقت بڑھی، اور دمشق میں بسنے والے یہودیوں کو حیران کر دیا، یہ ثابت کرتے ہوئے کہ یہی مسیح ہے۔\n23۔ اور اس کے بعد کئی دن گزر گئے، یہودیوں نے اسے قتل کرنے کا مشورہ لیا:\n24۔ لیکن ان کا انتظار ساؤل کے بارے میں معلوم تھا۔ اور وہ دن رات دروازوں کی نگرانی کرتے رہے تاکہ اسے مار سکیں۔\n25۔ پھر شاگردوں نے اسے رات کو لے کر دیوار کے پاس ایک ٹوکری میں اتار دیا۔\n26۔ اور جب ساؤل یروشلم آیا، تو اس نے شاگردوں کے ساتھ شامل ہونے کی کوشش کی، لیکن وہ سب اس سے ڈرتے تھے اور یقین نہیں کرتے تھے کہ وہ شاگرد ہے۔\n27۔ لیکن برنابا نے اسے لے لیا، رسولوں کے پاس لے آیا، اور انہیں بتایا کہ اس نے خداوند کو راستے میں دیکھا، اس سے بات کی، اور کیسے اس نے دمشق میں یسوع کے نام پر جرات مندی سے تبلیغ کی۔\n28۔ اور وہ ان کے ساتھ یروشلم میں آتے جاتے تھے۔\n29۔ اور اس نے خداوند یسوع کے نام پر جرات مندی سے بات کی، اور یونانیوں کے خلاف بحث کی: لیکن وہ اسے مارنے کے لیے آگے بڑھے۔\n30۔ {جسے} جب بھائیوں کو معلوم ہوا، تو انہوں نے اسے قیصریہ لے جا کر طرسوس بھیج دیا۔\n31۔ پھر کلیساؤں کو یہودیہ، گلیل اور سامریہ میں آرام دیا گیا اور انہیں تعمیر کیا گیا؛ اور خداوند کے خوف اور روح القدس کے سکون میں چلتے ہوئے، وہ بڑھ گئے۔\n32۔ اور ایسا ہوا، جب پطرس نے ہر جگہ سے گزرا، تو وہ بھی ان مقدسین کے پاس آیا جو لڈا میں رہتے تھے۔\n33۔ اور وہاں اس نے ایک شخص پایا، اینیاس، جو آٹھ سال بستر پر تھا اور فالج سے بیمار تھا۔\n34۔ اور پطرس نے اسے کہا، اینیاس، یسوع مسیح تمہیں مکمل بناتا ہے: اٹھو، اور اپنا بستر بناؤ۔ اور وہ فورا اٹھ کھڑا ہوا۔\n35۔ اور جو لوگ لیدا اور سارون میں رہتے تھے، انہوں نے اسے دیکھا اور خداوند کی طرف رجوع کیا۔\n36۔ یوفا میں ایک شاگرد تھی جس کا نام تابیتھا تھا، جسے تشریح کے مطابق ڈورکاس کہا جاتا ہے: یہ عورت نیک کاموں اور خیرات سے بھرپور تھی جو اس نے کی۔ {ڈورکاس: یا، ڈو، یا، رو}\n37۔ اور ان دنوں ایسا ہوا کہ وہ بیمار ہو گئی اور مر گئی: جب انہوں نے نہلا تو اسے اوپر والے کمرے میں دفن کر دیا۔\n38۔ اور چونکہ لیدا یوفا کے قریب تھا، اور شاگردوں نے سنا تھا کہ پیٹر وہاں ہے، انہوں نے اس کے پاس دو آدمی بھیجے، تاکہ وہ ان کے پاس آنے میں دیر نہ کرے۔ {تاخیر: یا، غمگین ہو جاؤ}\n39۔ پھر پطرس اٹھا اور ان کے ساتھ چلا گیا۔ جب وہ آیا، تو اسے اوپر والے کمرے میں لے گئے: اور تمام بیوائیں اس کے ساتھ روتی ہوئی کھڑی تھیں، اور وہ کوٹ اور کپڑے دکھا رہی تھیں جو ڈورکاس نے بنائے تھے، جب وہ ان کے ساتھ تھی۔\n40۔ لیکن پطرس نے سب کو پیش کیا، گھٹنے ٹیک کر دعا کی؛ اور لاش کی طرف مڑ کر کہا، تابیتھا، اٹھو۔ اور اس نے اپنی آنکھیں کھولیں: اور جب اس نے پیٹر کو دیکھا تو وہ بیٹھ گئی۔\n41۔ اور اس نے اسے اپنا ہاتھ دیا، اسے اٹھایا، اور جب اس نے اولیاء اور بیواؤں کو بلایا، تو اسے زندہ پیش کیا۔\n42۔ اور یہ پورے یوفا میں مشہور تھا؛ اور بہت سے لوگ خداوند پر ایمان رکھتے تھے۔\n43۔ اور ایسا ہوا کہ وہ یوپا میں کئی دن ایک چمڑے والے شمعون کے ساتھ رہے۔","1۔ قیصریہ میں ایک شخص تھا جس کا نام کورنیلیئس تھا، جو اطالوی {بینڈ} نامی گروہ کا سینچورین تھا،\n2۔ {A} دیندار {انسان}، اور جو خدا سے اپنے پورے گھر کے ساتھ ڈرتا تھا، لوگوں کو بہت خیرات دیتا تھا، اور ہمیشہ خدا سے دعا کرتا تھا۔\n3۔ اس نے ایک خواب میں واضح طور پر دن کے نویں گھنٹے کے بارے میں دیکھا کہ خدا کا فرشتہ اس کے پاس آ رہا ہے اور اسے کہہ رہا ہے، کورنیلیئس۔\n4۔ اور جب اس نے اسے دیکھا تو وہ ڈر گیا اور کہا، کیا بات ہے، خداوند؟ اور اس نے اس سے کہا، تیری دعائیں اور تمہاری خیرات خدا کے حضور ایک یادگار کے طور پر تیار کی گئی ہیں۔\n5. اور اب یوفا کے پاس آدمیوں کو بھیجو، اور {ایک} شمعون کو بلاؤ، جس کا خاندانی نام پیٹر ہے:\n6۔ وہ ایک چمڑے والے کے ساتھ رہتا ہے، جس کا گھر سمندر کے کنارے ہے: وہ تمہیں بتائے گا کہ تمہیں کیا کرنا چاہیے۔\n7۔ اور جب وہ فرشتہ جو کورنیلیئس سے بات کر رہا تھا رخصت ہوا، تو اس نے اپنے دو گھریلو خادموں اور ایک مخلص سپاہی کو بلایا جو مسلسل اس کی خدمت کرتا رہا؛\n8۔ اور جب اس نے یہ سب چیزیں ان کے نام کر دیں، تو اسے یوفا کو بھیج دیا۔\n9۔ کل جب وہ اپنے سفر پر نکلے اور شہر کے قریب پہنچے، پیٹر چھٹے گھنٹے کے قریب گھر کی چھت پر دعا کرنے چلا گیا:\n10۔ اور وہ بہت بھوکا ہو گیا، اور کھانا چاہتا تھا: لیکن جب وہ تیار ہو رہے تھے، وہ ایک غنودگی میں چلا گیا،\n11۔ اور آسمان کو کھلتے دیکھا، اور ایک برتن اس کی طرف اترتا ہے، جیسے وہ چاروں کونوں پر ایک بڑا چادر بن کر زمین پر اتر گیا ہو:\n12۔ جس میں زمین کے ہر طرح کے چار پاؤں والے جانور، جنگلی جانور، رینگنے والے جانور، اور ہوا کے پرندے تھے۔\n13۔ اور اس کے پاس ایک آواز آئی، اٹھو، پیٹر؛ مارو، اور کھاؤ۔\n14۔ لیکن پطرس نے کہا، ایسا نہیں ہے، خداوند؛ کیونکہ میں نے کبھی کوئی عام یا ناپاک چیز نہیں کھائی۔\n15. اور وہ آواز {جو دوسری بار کہی} اس سے کہی، جو خدا نے پاک کیا، {جو} عام نہیں کہتا۔\n16۔ یہ تین بار کیا گیا: اور برتن کو دوبارہ آسمان میں لے جایا گیا۔\n17۔ اب جب پطرس اپنے آپ میں شک کر رہا تھا کہ اس نے جو خواب دیکھا تھا اس کا کیا مطلب ہوگا، دیکھو، کورنیلیئس سے بھیجے گئے آدمیوں نے شمعون کے گھر کے بارے میں پوچھ گچھ کی اور دروازے کے سامنے کھڑے ہو گئے،\n18۔ اور اس نے فون کیا اور پوچھا کہ کیا سائمن، جس کا نام پیٹر تھا، وہاں ٹھہرے ہوئے ہیں۔\n19۔ جب پیٹر اس خواب پر غور کر رہا تھا، روح نے اسے کہا، دیکھو، تین لوگ تمہیں تلاش کر رہے ہیں۔\n20۔ لہٰذا اٹھو، نیچے اتر جاؤ، اور ان کے ساتھ جاؤ، شک نہ کرو: کیونکہ میں نے انہیں بھیجا ہے۔\n21۔ پھر پطرس ان مردوں کے پاس گیا جو کورنیلیئس کی طرف سے اس کے پاس بھیجے گئے تھے؛ اور کہا، دیکھو، میں وہی ہوں جسے تم تلاش کرتے ہو: تم کیوں آئے ہو؟\n22۔ اور انہوں نے کہا، کورنیلیئس سینچورین، ایک عادل آدمی، جو خدا سے ڈرتا ہے، اور یہودیوں کی تمام قوم میں اچھا شہرت رکھتا ہے، خدا کی طرف سے ایک مقدس فرشتے نے اسے خبردار کیا کہ وہ تمہیں اپنے گھر میں بلائے، اور تمہاری باتیں سنے۔\n23۔ پھر انہوں نے انہیں بلایا اور انہیں ٹھہرایا رکھا۔ اور کل پیٹر ان کے ساتھ چلا گیا، اور یوفا کے کچھ بھائی اس کے ساتھ آئے۔\n24۔ اور کل جب وہ قیصریہ میں داخل ہوئے۔ اور کورنیلیئس نے ان کا انتظار کیا، اور اپنے رشتہ داروں اور قریبی دوستوں کو اکٹھا کیا۔\n25۔ اور جب پیٹر اندر آ رہا تھا، کورنیلیئس اس سے ملا، اس کے قدموں میں گر گیا اور اس کی عبادت کرنے لگا۔\n26۔ لیکن پطرس نے اسے اٹھایا اور کہا، کھڑے ہو جاؤ؛ میں خود بھی ایک مرد ہوں۔\n27۔ اور جب وہ اس سے بات کر رہا تھا، تو وہ اندر گیا، اور بہت سے لوگ ملے جو ایک ساتھ تھے۔\n28۔ اور اس نے ان سے کہا، تم جانتے ہو کہ یہودی کے لیے کسی اور قوم کے ساتھ رہنا یا آنا حرام ہے؛ لیکن خدا نے مجھے دکھایا ہے کہ میں کسی کو عام یا ناپاک نہ کہوں۔\n29۔ اس لیے میں بغیر کسی انکار کے تمہارے پاس آیا، جیسے ہی مجھے بلایا گیا: تو میں پوچھتا ہوں کہ تم نے میرے لیے کس نیت کے لیے بھیجا ہے؟\n30۔ اور کورنیلیئس نے کہا، چار دن پہلے میں اس وقت تک روزہ رکھ رہا تھا؛ اور نویں گھنٹے میں نے اپنے گھر میں دعا کی، اور دیکھتے ہی ایک آدمی میرے سامنے چمکدار لباس میں کھڑا تھا،\n31۔ اور کہا، کورنیلیئس، تیری دعا سنی گئی، اور تمہاری خیرات خدا کی نظر میں یاد میں دی جاتی ہیں۔\n32۔ لہٰذا یوفا کو بھیجو، اور یہاں شمعون کو بلاؤ، جس کا خاندانی نام پیٹر ہے؛ وہ {ایک} سائمن کے گھر میں ہے، جو سمندر کے کنارے چمڑے کا کام کرتا ہے: جو جب آئے گا تو تم سے بات کرے گا۔\n33۔ اسی لیے میں نے فورا آپ کو بھیجا؛ اور تم نے جو کچھ کیا ہے وہ بہت اچھا کیا ہے۔ اسی لیے اب ہم سب یہاں خدا کے سامنے موجود ہیں، تاکہ وہ سب باتیں سن سکیں جو خدا کی طرف سے تمہیں حکم دی گئی ہیں۔\n34۔ پھر پطرس نے منہ کھولا اور کہا، ایک سچائی کے بارے میں جو میں سمجھتا ہوں کہ خدا لوگوں کا احترام نہیں کرتا:\n35. لیکن ہر قوم میں جو اس سے ڈرتا ہے اور راستبازی کرتا ہے، وہ اس کے ساتھ قبول کیا جاتا ہے۔\n36. وہ کلام جو {خدا} نے بنی اسرائیل کو بھیجا، یسوع مسیح کے ذریعے امن کی تبلیغ کی: (وہ سب کا رب ہے:)\n37۔ وہ لفظ، {میں کہتا ہوں}، آپ جانتے ہیں، جو پورے یہودیہ میں شائع ہوا، اور گلیل سے شروع ہوا، اس بپتسمہ کے بعد جو یوحنا نے تبلیغ کی؛\n38۔ کس طرح خدا نے یسوع ناصرت کو روح القدس اور طاقت سے مسح کیا: جو نیکی کرتا رہا، اور شیطان کے ظلم کرنے والوں کو شفا دیتا؛ کیونکہ خدا اس کے ساتھ تھا۔\n39۔ اور ہم ان تمام کاموں کے گواہ ہیں جو انہوں نے یہودیوں کی سرزمین اور یروشلم میں کیے؛ جسے انہوں نے قتل کر کے درخت پر لٹکا دیا:\n40۔ خدا نے تیسرے دن اسے اٹھایا اور کھل کر دکھایا؛\n41۔ تمام لوگوں کے لیے نہیں، بلکہ خدا کے منتخب کردہ گواہوں کے لیے، {حتیٰ کہ} ہمارے لیے، جو اس کے مردوں میں سے زندہ ہونے کے بعد اس کے ساتھ کھایا اور پیا۔\n42۔ اور اس نے ہمیں حکم دیا کہ ہم لوگوں کو تبلیغ کریں، اور گواہی دیں کہ خدا نے اسے زندہ اور مردوں کا منصف مقرر کیا ہے۔\n43۔ اس کے لیے تمام انبیاء گواہی دیں کہ جو اس کے نام سے ایمان لاتا ہے اسے گناہوں کی معافی ملے گی۔\n44۔ جب پطرس ابھی یہ الفاظ کہہ رہا تھا، روح القدس نے ان سب پر گر پڑا جنہوں نے یہ کلام سنا۔\n45۔ اور وہ لوگ جو ختنہ کے ایمان میں تھے، حیران رہ گئے، جتنے لوگ پطرس کے ساتھ آئے تھے، کیونکہ یہی غیر یہودیوں پر بھی روح القدس کا تحفہ بہایا گیا تھا۔\n46۔ کیونکہ انہوں نے انہیں زبانوں سے بولتے اور خدا کی تعریف کرتے سنا۔ پھر پیٹر نے جواب دیا،\n47۔ کیا کوئی انسان پانی سے منع کر سکتا ہے کہ ان لوگوں کو بپتسمہ نہ دیا جائے، جنہوں نے روح القدس کو ہم کی طرح قبول کیا ہے؟\n48۔ اور اس نے انہیں خداوند کے نام پر بپتسمہ لینے کا حکم دیا۔ پھر انہوں نے دعا کی کہ وہ کچھ دنوں میں دیر کرے۔","1۔ اور یہودیہ میں موجود رسولوں اور بھائیوں نے سنا کہ غیر یہودیوں نے بھی خدا کا کلام وصول کر لیا ہے۔\n2۔ اور جب پطرس یروشلم آیا، تو ختنہ کرنے والوں نے اس سے بحث کی،\n3۔ کہا، تم نے غیر ختنہ شدہ لوگوں میں آ کر ان کے ساتھ کھانا کھایا۔\n4۔ لیکن پطرس نے شروع سے {معاملہ} کی مشق کی، اور حکم کے مطابق انہیں سمجھایا، کہا،\n5۔ میں یوفا کے شہر میں دعا کر رہا تھا: اور ایک غنودگی میں میں نے ایک خواب دیکھا، ایک خاص برتن اترتا ہے، جیسے وہ ایک بڑا چادر ہو، جو آسمان سے چار کونوں سے نیچے اتر رہا ہو؛ اور یہ بات میرے ذہن میں بھی آئی:\n6۔ جس پر جب میں نے اپنی آنکھیں جمائے، تو میں نے زمین کے چار پاؤں والے جانور، جنگلی جانور، رینگنے والے جانور، اور ہوا کے پرندے دیکھے۔\n7۔ اور میں نے ایک آواز سنی جو مجھ سے کہہ رہی تھی، اٹھو، پطرس؛ مارو اور کھاؤ۔\n8۔ لیکن میں نے کہا، ایسا نہیں اے خداوند، کیونکہ میرے منہ میں کبھی کوئی عام یا ناپاک چیز نہیں آئی۔\n9۔ لیکن آواز نے پھر آسمان سے جواب دیا، جو خدا نے پاک کیا ہے، {جو} عام نہیں کہتا۔\n10۔ اور یہ تین بار کیا گیا: اور سب کو دوبارہ آسمان میں کھینچ لیا گیا۔\n11۔ اور دیکھو، فورا ہی تین آدمی اس گھر آ گئے جہاں میں تھا، قیصریہ سے میرے پاس بھیجے گئے تھے۔\n12۔ اور روح القدس نے مجھے ان کے ساتھ جانے کا حکم دیا، بغیر کسی شک کے۔ مزید برآں، یہ چھ بھائی میرے ساتھ تھے، اور ہم اس آدمی کے گھر میں داخل ہوئے:\n13۔ اور اس نے ہمیں دکھایا کہ اس نے اپنے گھر میں ایک فرشتہ دیکھا، جو کھڑا تھا اور اس سے کہہ رہا تھا، آدمیوں کو یوفا بھیجو، اور شمعون کو بلاؤ، جس کا خاندانی نام پیٹر ہے؛\n14. کون تمہیں وہ الفاظ بتائے گا جن سے تم اور تمہارا پورا گھر بچیں گے۔\n15۔ اور جب میں بولنا شروع ہوا، تو روح القدس ان پر نازل ہوا، جیسے ہم پر شروع میں تھا۔\n16۔ پھر میں نے خداوند کے کلام کو یاد کیا، جس نے کہا، واقعی یوحنا نے پانی سے بپتسمہ دیا؛ لیکن تم روح القدس کے ساتھ بپتسمہ لو گے۔\n17۔ چونکہ خدا نے انہیں وہی تحفہ دیا جو اس نے ہمیں دیا، جو خداوند یسوع مسیح پر ایمان رکھتے ہیں؛ میں کیا تھا، جو خدا کا مقابلہ کر سکتا تھا؟\n18۔ جب انہوں نے یہ باتیں سنیں، تو خاموش ہو گئے اور خدا کی جلال میں کہا، \"تو خدا نے بھی غیر یہویوں کو زندگی کی توبہ دی ہے۔\"\n19۔ اب وہ لوگ جو اسٹیفن کے گرد ہونے والے ظلم و ستم کے بعد باہر بکھرے ہوئے تھے، فینیس، قبرص، اور انطاکیہ تک پہنچ گئے، اور صرف یہودیوں کے لیے کلام سنایا۔\n20۔ اور ان میں سے کچھ قبرص اور سائرین کے لوگ تھے، جو جب انطاکیہ آئے تو انہوں نے یونانیوں سے خطاب کیا اور خداوند یسوع کی تبلیغ کی۔\n21۔ اور خداوند کا ہاتھ ان کے ساتھ تھا: اور بہت سے لوگ ایمان لائے اور خداوند کی طرف متوڑ گئے۔\n22۔ پھر ان باتوں کی خبر یروشلم میں موجود کلیسیا کے کانوں تک پہنچی: اور انہوں نے برناباس کو بھیجا کہ وہ انطاکیہ تک جائے۔\n23۔ جب وہ آیا اور خدا کی رحمت دیکھی، تو خوش ہوا اور سب کو نصیحت کی کہ وہ دل کے ارادے کے ساتھ خداوند سے چمٹیں گے۔\n24۔ کیونکہ وہ ایک اچھا انسان تھا، روح القدس اور ایمان سے بھرا ہوا: اور خداوند میں بہت سے لوگ شامل کیے گئے۔\n25۔ پھر برناباس سے تارسس روانہ ہوا، تاکہ ساؤل کو تلاش کرے:\n26۔ اور جب اس نے اسے پایا، تو اسے انطاکیہ لے آیا۔ اور ایسا ہوا کہ پورا سال انہوں نے چرچ کے ساتھ جمع ہو کر بہت سے لوگوں کو تعلیم دی۔ اور انطاکیہ میں شاگردوں کو سب سے پہلے عیسائی کہا جاتا تھا۔ {ساتھ...: یا، چرچ میں}\n27۔ اور ان دنوں میں یروشلم سے انطاکیہ تک نبی آئے۔\n28۔ اور وہاں ان میں سے ایک کھڑا ہوا جس کا نام اگابوس تھا، اور اس نے روح القدس سے ظاہر کیا کہ دنیا بھر میں شدید کمی ہوگی، جو کلاڈیئس سیزر کے زمانے میں ہوا۔\n29۔ پھر شاگردوں نے، ہر شخص اپنی صلاحیت کے مطابق، یہودیہ میں رہنے والے بھائیوں کو امداد بھیجنے کا فیصلہ کیا:\n30۔ جو انہوں نے بھی کیا، اور اسے برناباس اور ساؤل کے ہاتھوں بزرگوں کو بھیجا۔","1۔ اسی وقت ہیرودیس بادشاہ نے کلیسیا کے کچھ لوگوں کو پریشان کرنے کے لیے اپنے ہاتھ آگے بڑھائے۔ {کھینچا...: یا، شروع کیا}\n2۔ اور اس نے جیمز کو تلوار سے مارا۔\n3۔ اور چونکہ اس نے دیکھا کہ یہ یہودیوں کو پسند آیا، اس نے آگے بڑھ کر پیٹر کو بھی لے لیا۔ (تب وہ دن تھے جب بغیر خمیر کے روٹی کا تھا۔)\n4۔ اور جب اس نے اسے گرفتار کیا، تو اس نے {اسے} کو قید میں ڈال دیا، اور {اسے} چار کواٹرنینز کے سپاہیوں کے حوالے کر دیا تاکہ وہ اسے محفوظ رکھیں؛ ایسٹر کے بعد اسے لوگوں کے سامنے لانے کا ارادہ تھا۔ {ایسٹر: گریڈ پاس اوور} {کواٹرنینز: چار سپاہیوں کی ایک فائل}\n5۔ اس لیے پیٹر کو قید میں رکھا گیا: لیکن کلیسا نے اس کے لیے خدا کی طرف دعا کی بغیر رکی۔ {دعا...: یا، فوری اور مخلص دعا کی گئی}\n6۔ اور جب ہیرودیس اسے باہر لانے والا تھا، اسی رات پیٹر دو سپاہیوں کے درمیان سو رہا تھا، جو دو زنجیروں سے بندھے ہوئے تھے: اور دروازے کے سامنے محافظ قید خانے کو سنبھال رہے تھے۔\n7۔ اور دیکھے، خداوند کا فرشتہ اس پر آیا، اور قید میں روشنی چمکی، اور اس نے پطرس کو پہلو پر مارا اور اسے اٹھا کر کہا، جلدی اٹھو۔ اور اس کی زنجیریں {اس کے} ہاتھوں سے گر گئیں۔\n8۔ اور فرشتے نے اسے کہا، خود کو باندھو اور اپنے جوتے باندھو۔ اور اس نے ایسا ہی کیا۔ اور وہ اسے کہتا ہے، اپنا لباس اتارو اور میرے ساتھ آؤ۔\n9۔ اور وہ باہر گیا، اور اس کے پیچھے گیا؛ اور اس بات کا خیال نہ رکھیں کہ یہ سچ تھا جو فرشتے نے کیا؛ لیکن اسے لگا کہ اس نے ایک خواب دیکھا۔\n10۔ جب وہ پہلے اور دوسرے وارڈ سے گزرے، تو وہ لوہے کے دروازے تک پہنچے جو شہر کی طرف جاتا ہے؛ جو اس کی مرضی سے ان کے لیے کھل گیا: اور وہ باہر نکلے، اور ایک گلی سے گزرے؛ اور فورا فرشتہ اس سے جدا ہو گیا۔\n11۔ اور جب پطرس ہوش میں آیا تو اس نے کہا، اب میں ایک یقین سے واقف ہوں کہ خداوند نے اپنا فرشتہ بھیجا ہے، اور مجھے ہیرودیس کے ہاتھوں اور یہودیوں کی تمام امیدوں سے آزاد کر دیا ہے۔\n12۔ اور جب اس نے {اس واقعے} پر غور کیا، تو وہ مریم کے گھر آیا، جو جان کی ماں تھی، جس کا خاندانی نام مارک تھا؛ جہاں بہت سے لوگ دعا کر رہے تھے۔\n13۔ اور جب پیٹر نے دروازے کے دروازے پر دستک دی، تو ایک لڑکی آئی، جس کا نام رودا تھا۔ {سننے کے لیے: یا، پوچھنے کے لیے کہ وہاں کون تھا}\n14۔ اور جب اس نے پطرس کی آواز سنی، تو اس نے خوشی کے لیے دروازہ نہیں کھولا، بلکہ اندر دوڑی اور بتایا کہ پطرس دروازے کے سامنے کھڑا ہے۔\n15۔ اور انہوں نے اس سے کہا، تم پاگل ہو۔ لیکن وہ بار بار اس بات کی تصدیق کرتی رہتی تھی کہ یہ حقیقت ہے۔ پھر انہوں نے کہا، یہ اس کا فرشتہ ہے۔\n16۔ لیکن پطرس دستک دیتا رہا: اور جب انہوں نے دروازہ کھولا اور اسے دیکھا، تو وہ حیران رہ گئے۔\n17۔ لیکن اس نے ہاتھ سے انہیں خاموش رہنے کا اشارہ کیا اور انہیں بتایا کہ خداوند نے اسے قید سے باہر نکالا۔ اور اس نے کہا، یہ باتیں جیمز اور بھائیوں کو دکھاؤ۔ اور وہ روانہ ہو گیا، اور کسی اور جگہ چلا گیا۔\n18۔ جیسے ہی دن آیا، سپاہیوں میں کوئی خاص ہلچل مچ گئی، پیٹر کے ساتھ کیا ہوا۔\n19۔ اور جب ہیرودیس نے اسے تلاش کیا اور نہ ملا، تو اس نے محافظوں کا معائنہ کیا اور حکم دیا کہ {انہیں} کو قتل کر دیا جائے۔ اور وہ یہودیہ سے قیصریہ نیچے گیا، اور {وہاں} ٹھہرایا گیا۔\n20۔ اور ہیرودیس صور اور صیدا کے ان سے سخت ناخوش تھا: لیکن وہ ایک ہی اتفاق کے ساتھ اس کے پاس آئے، اور جب انہوں نے بلاستس کو بادشاہ کا چیمبرلین بنا دیا تو امن کی خواہش ظاہر کی؛ کیونکہ ان کا ملک بادشاہ کے ملک سے پروان چڑھتا تھا۔ {انتہائی زیادہ...: یا، دشمن ذہن کے طور پر، جنگ کا ارادہ رکھتے ہوئے} {بادشاہ کا چیمبرلین: گری۔ وہ بادشاہ کے کمرے کے اوپر تھا}\n21۔ اور ایک مقررہ دن ہیرودس، شاہی لباس میں ملبوس، اپنے تخت پر بیٹھا اور ان سے خطاب کیا۔\n22۔ اور لوگوں نے چیخ ماری، {کہا، یہ خدا کی آواز ہے، انسان کی نہیں۔\n23۔ اور فورا خداوند کے فرشتے نے اسے مارا، کیونکہ اس نے خدا کو جلال نہیں دیا: اور وہ کیڑے کھا گیا، اور بھوت کو چھوڑ دیا۔\n24۔ لیکن خدا کا کلام بڑھتا اور بڑھتا گیا۔\n25۔ اور برنابا اور ساؤل یروشلم سے واپس آئے، جب انہوں نے اپنی خدمت مکمل کر لی تھی، اور اپنے ساتھ یوحنا کو لے گئے، جس کا خاندانی نام مارک تھا۔ {وزارت: یا، چارج}","1۔ انطاکیہ کی کلیسیا میں کچھ نبی اور اساتذہ تھے؛ جیسے برناباس، اور شمعون جسے نائجر کہا جاتا تھا، اور لوسیئس آف سائرین، اور مانائن، جو ہیرودیس ٹیٹرارک کے ساتھ پالا گیا تھا، اور ساؤل۔ {جو کہ...: یا، ہیرودیس کا گود لیا ہوا بھائی}\n2۔ جب وہ خداوند کی خدمت کر رہے تھے اور روزہ رکھتے تھے، تو روح القدس نے کہا، مجھے برنابا اور ساؤل کو اس کام کے لیے جدا کرو جس کے لیے میں نے انہیں بلایا ہے۔\n3۔ اور جب انہوں نے روزہ رکھا اور دعا کی، اور ان پر ہاتھ رکھے، تو انہوں نے انہیں بھیج دیا۔\n4۔ چنانچہ، روح القدس کی طرف سے بھیجے گئے، وہ سیلوقیہ روانہ ہو گئے؛ اور وہاں سے وہ قبرص روانہ ہوئے۔\n5۔ اور جب وہ سلامیس میں تھے، تو انہوں نے یہودیوں کی عبادت گاہوں میں خدا کا کلام تبلیغ کیا: اور ان کے پاس جان بھی تھا کہ وہ ان کی خدمت کرے۔\n6۔ اور جب وہ جزیرے سے پافوس پہنچے، تو انہوں نے ایک جادوگر، ایک جھوٹا نبی، ایک یہودی پایا، جس کا نام {تھا} باریسوس:\n7۔ جو ملک کے نائب، سرگیئس پاؤلس کے ساتھ تھا، جو ایک محتاط انسان تھا؛ جس نے برناباس اور ساؤل کو بلایا، اور خدا کا کلام سننا چاہا۔\n8۔ لیکن ایلیماس جادوگر (کیونکہ اس کا نام تشریح کے مطابق ایسا ہی ہے) نے ان کا مقابلہ کیا، اور نائب کو ایمان سے دور کرنے کی کوشش کی۔\n9۔ پھر ساؤل، (جسے بھی {پولس} کہا جاتا ہے)، جو روح القدس سے بھرا ہوا تھا، نے اس پر نظر ڈالی،\n10۔ اور کہا، اے تمام چالاکی اور شرارتوں سے بھرپور، {تم} شیطان کے بیٹے، {تو} تمام راستبازی کے دشمن، کیا تم خداوند کے صحیح راستوں کو بھٹکنا بند نہیں کرو گے؟\n11۔ اور اب، دیکھو، خداوند کا ہاتھ تم پر ہے، اور تم اندھے ہو جاؤ گے، ایک وقت کے لیے سورج کو نہیں دیکھو گے۔ اور فورا اس پر دھند اور تاریکی چھا گئی؛ اور وہ ہاتھ پکڑ کر کچھ تلاش کرنے لگا۔\n12۔ پھر نائب نے جب دیکھا کہ کیا ہو رہا ہے، تو ایمان لایا اور خداوند کے عقیدے پر حیران رہ گیا۔\n13۔ جب پولوس اور اس کے ساتھی پافوس سے آزاد ہوئے، تو وہ پامفیلیا میں پرگا پہنچے: اور جان ان سے روانہ ہو کر یروشلم واپس آیا۔\n14۔ لیکن جب وہ پرگا سے روانہ ہوئے، تو وہ پیسیڈیا کے انطاکیہ پہنچے، اور سبت کے دن عبادت گاہ میں گئے اور بیٹھ گئے۔\n15۔ اور شریعت اور انبیاء کی تلاوت کے بعد عبادت گاہ کے حکمرانوں نے ان کے پاس بھیجا، کہا، {یوں} بھائیو، اگر آپ کے پاس لوگوں کے لیے کوئی نصیحت ہے تو کہیں۔\n16۔ پھر پولوس کھڑا ہوا اور اپنے ہاتھ سے اشارہ کرتے ہوئے کہا، \"اسرائیلی لوگو، اور جو خدا سے ڈرتے ہو، ملاقات کرو۔\n17۔ اس قوم اسرائیل کے خدا نے ہمارے آباؤ اجداد کو چنا، اور جب لوگ مصر کی سرزمین میں اجنبی بن کر رہتے، انہیں بلند مقام دیا، اور بلند ہاتھ سے انہیں وہاں سے نکالا۔\n18۔ اور تقریبا چالیس سال کے عرصے میں اس نے ان کے آداب کو بیابان میں برداشت کیا۔ {تکلیف دی...: یا بچے کو جنم دیا، یا انہیں کھلایا جیسے نرس اپنے بچے کو جنم دیتی ہے یا دودھ پلاتی ہے}\n19۔ اور جب اس نے حنان کی سرزمین میں سات قوموں کو تباہ کیا، تو اس نے ان کی زمین قرعہ اندازی کے ذریعے ان پر تقسیم کر دی۔\n20۔ اور اس کے بعد اس نے {انہیں} کو تقریبا چار سو پچاس سال کے عرصے تک ججوں کو دیا، یہاں تک کہ سموئیل نبی تک۔\n21۔ اور بعد میں انہوں نے بادشاہ کی خواہش کی: اور خدا نے انہیں چالیس سال کے اندر ساؤل، سیس کے بیٹے، بنیامین قبیلے کا آدمی دے دیا۔\n22۔ اور جب اس نے اسے ہٹایا تو اس نے ان کے پاس ڈیوڈ کو بادشاہ بنانے کے لیے اٹھایا؛ جس سے اس نے بھی گواہی دی، اور کہا، میں نے داؤد کو یسوع کا {بیٹا} پایا، جو میرے دل کے مطابق آدمی ہے، جو میری تمام مرضی پوری کرے گا۔\n23۔ اس انسان کی نسل سے خدا نے اپنے وعدے کے مطابق اسرائیل کو نجات دہندہ، یسوع کو جنم دیا:\n24۔ جب یوحنا نے اپنی آمد سے پہلے تمام اسرائیل کے لوگوں کے لیے توبہ کی بپتسمہ کی تبلیغ کی تھی۔\n25۔ اور جب جان نے اپنا راستہ مکمل کیا، تو اس نے کہا، تم کون سمجھتے ہو کہ میں کون ہوں؟ میں {وہ} نہیں ہوں۔ لیکن، دیکھو، میرے بعد ایک آ رہا ہے، جس کے {اس} کے پاؤں کے جوتے میں کھونے کے لائق نہیں ہوں۔\n26۔ انسانو {اور} بھائیو، ابراہیم کی اولاد ہو، اور جو بھی تم میں سے خدا سے ڈرتا ہے، اس نجات کا کلام تمہارے لیے بھیجا گیا ہے۔\n27۔ کیونکہ جو یروشلم میں رہتے ہیں، اور ان کے حکمران، کیونکہ وہ اسے نہیں جانتے تھے، اور نہ ہی انبیاء کی آوازیں جو ہر ہفتہ کے دن پڑھی جاتی ہیں، انہوں نے [انبیاء} کی مذمت کر کے پورا کیا ہے۔\n28۔ اور اگرچہ انہوں نے اس میں موت کی کوئی وجہ نہیں دیکھی، پھر بھی انہوں نے پیلاطس سے دعا کی کہ اسے قتل کر دیا جائے۔\n29۔ اور جب انہوں نے اس کے بارے میں جو کچھ لکھا تھا وہ سب پورا کر لیا، تو انہوں نے {اسے} کو درخت سے اتارا، اور {اسے} کو قبر میں دفن کر دیا۔\n30۔ لیکن خدا نے اسے مردوں میں سے زندہ کیا:\n31۔ اور وہ کئی دنوں تک ان کے ساتھ گلیل سے یروشلم تک آئے، جو اس کے لوگوں کے گواہ ہیں۔\n32۔ اور ہم آپ کو خوشخبری دیتے ہیں، کہ وہ وعدہ جو باپوں سے کیا گیا تھا،\n33۔ خدا نے ہمارے لیے ان کے بچوں کو بھی یہی پورا کیا ہے، یعنی اس نے یسوع کو دوبارہ زندہ کیا؛ جیسا کہ دوسرے زبور میں بھی لکھا ہے، تو میرے بیٹے ہو، آج میں نے تمہیں جنم دیا ہے۔\n34۔ اور جہاں تک اس بات کا تعلق ہے کہ اس نے اسے مردوں میں سے زندہ کیا، {اب} اب بگاڑ کی طرف لوٹنے کے لیے نہیں، اس نے اس حکمت سے کہا، میں تمہیں داؤد کی یقینی رحمتیں دوں گا۔ {رحمتیں: یونانی مقدس، یا صرف چیزیں: جو لفظ سیپٹواجنٹ کئی جگہوں پر عبرانی میں موجود رحمتوں کے لیے استعمال کرتا ہے}\n35۔ اسی لیے وہ ایک اور {زبور} میں بھی کہتا ہے، تو اپنے مقدس وجود کو بگاڑ نہ دینا۔\n36۔ کیونکہ داؤد، جب اس نے خدا کی مرضی سے اپنی نسل کی خدمت کی، تو سو گیا، اور اپنے باپ کے حوالے کر دیا گیا، اور فساد دیکھا: {بعد...: یا، جب اس نے اپنی عمر میں خدا کی مرضی کی خدمت کی}\n37۔ لیکن جسے خدا نے دوبارہ زندہ کیا، اس نے کوئی فساد نہیں دیکھا۔\n38۔ لہٰذا، آپ حضرات {اور} بھائیو، جان لیں کہ اس انسان کے ذریعے آپ کو گناہوں کی معافی کی تبلیغ دی جاتی ہے:\n39۔ اور اس کے ذریعے تمام ایمان والے تمام چیزوں سے راستباز ہیں، جن سے تم موسیٰ کے قانون کے مطابق راستباز نہیں ہو سکے۔\n40۔ لہٰذا خبردار رہو، کہیں وہ چیز تم پر نہ آ جائے، جس کا ذکر نبیوں میں کیا گیا ہے؛\n41۔ دیکھو، اے حقیر لوگوں اور حیران ہو جاؤ، اور فنا ہو جاؤ: کیونکہ میں تمہارے زمانے میں ایسا کام کرتا ہوں، ایسا کام جس پر تم کبھی یقین نہیں کرو گے، چاہے کوئی تمہیں بتائے بھی۔\n42۔ اور جب یہودی عبادت گاہ سے نکل گئے، غیر یہودیوں نے درخواست کی کہ یہ الفاظ اگلے سبت کو ان کے سامنے سنایا جائے۔ {اگلا...: Gr. ہفتے کے درمیان، یا سبت کے درمیان}\n43۔ اب جب جماعت کو تقسیم کیا گیا، تو بہت سے یہودی اور مذہبی پیروکار پولس اور برنابا کی پیروی کرنے لگے: جنہوں نے ان سے بات کر کے انہیں خدا کے فضل میں آگے بڑھنے پر آمادہ کیا۔\n44۔ اور اگلے سبت کے دن تقریبا پورا شہر خدا کا کلام سننے کے لیے اکٹھا ہوا۔\n45۔ لیکن جب یہودیوں نے ان ہجوم کو دیکھا تو وہ حسد سے بھر گئے اور ان باتوں کے خلاف بولے جو پولس نے کہے تھے، متضاد اور کفر کرتے ہوئے۔\n46۔ پھر پولوس اور برنابا نے جرات مندی سے کہا، \"ضروری تھا کہ خدا کا کلام پہلے تم سے کہا جاتا، لیکن جب تم اسے اپنے اوپر سے دور کر رہے ہو اور خود کو دائمی زندگی کے لائق نہ سمجھو، تو ہم غیر یہودیوں کی طرف رجوع کرتے ہیں۔\n47۔ کیونکہ خداوند نے ہمیں حکم دیا ہے، {کہ} کہہ کر، میں نے تمہیں غیر یہودیوں کی روشنی بنایا ہے، تاکہ تم زمین کے کناروں تک نجات کے لیے رہو۔\n48۔ اور جب غیر یہودیوں نے یہ سنا، تو وہ خوش ہوئے، اور خداوند کے کلام کو جلال بخشا: اور جتنے لوگ ابدی زندگی کے لیے مقرر ہوئے، ایمان لائے۔\n49۔ اور خداوند کا کلام پورے علاقے میں شائع ہوا۔\n50۔ لیکن یہودیوں نے دیندار اور معزز عورتوں اور شہر کے سرداروں کو بھڑکایا، پولس اور برنابا کے خلاف ظلم و ستم برپا کیا اور انہیں ان کے ساحلوں سے نکال دیا۔\n51۔ لیکن انہوں نے اپنے پیروں کی گرد جھاڑی اور آئیکونیم پہنچے۔\n52۔ اور شاگرد خوشی سے بھر گئے، اور روح القدس سے بھی۔","1۔ اور آئیکونیم میں ایسا ہوا کہ وہ دونوں مل کر یہودیوں کی عبادت گاہ میں گئے، اور یوں بات کی کہ یہودیوں اور یونانیوں کی بڑی تعداد ایمان لاتی تھی۔\n2۔ لیکن کافر یہودیوں نے غیر یہودیوں کو بھڑکایا، اور ان کے ذہنوں کو بھائیوں کے خلاف برا بنا دیا۔\n3۔ اس لیے وہ طویل عرصے تک خداوند میں جرات مندی سے بات کرتے رہے، جس نے اس کے فضل کے کلام کی گواہی دی، اور ان کے ہاتھوں سے کیے گئے نشانات اور عجائبات عطا کیے۔\n4۔ لیکن شہر کی اکثریت تقسیم ہو گئی: اور کچھ یہودیوں کے ساتھ اور کچھ رسولوں کے ساتھ۔\n5۔ اور جب غیر قومیوں اور یہودیوں پر ان کے حکمرانوں پر حملہ ہوا، تو انہیں بے رحمی سے استعمال کرنے اور پتھر مارنے کے لیے،\n6۔ وہ اس سے محتاط ہو گئے، اور لائکاؤنیا کے شہروں لسٹرا اور ڈربے اور اس علاقے کی طرف فرار ہو گئے جو آس پاس واقع ہے:\n7۔ اور وہاں انہوں نے انجیل کی تبلیغ کی۔\n8۔ اور وہاں لسٹرا میں ایک شخص بیٹھا تھا، اپنے قدموں میں بے بس، اپنی ماں کے پیٹ سے معذور تھا، جو کبھی چل نہیں سکا:\n9۔ اسی نے پولس کو بولتے سنا: جو ثابت قدمی سے اسے دیکھ رہا تھا، اور محسوس کیا کہ اس میں شفا پانے کا ایمان ہے،\n10۔ بلند آواز میں کہا، اپنے پیروں پر سیدھے کھڑے ہو جاؤ۔ اور وہ چھلانگ لگا کر چلتا رہا۔\n11۔ اور جب لوگوں نے دیکھا کہ پولس نے کیا کیا ہے، تو انہوں نے اپنی آوازیں بلند کیں اور لیکاونیا کی زبان میں کہا، دیوتا انسانوں کی صورت میں ہمارے پاس آئے ہیں۔\n12۔ اور انہوں نے برنابا کو مشتری کہا؛ اور پال، مرکوریئس، کیونکہ وہ چیف اسپیکر تھے۔\n13۔ پھر مشتری کے پجاری، جو ان کے شہر کے سامنے تھا، نے دروازوں تک بیل اور ہار لے کر آئے، اور لوگوں کے ساتھ قربانی دینے کا ارادہ کیا۔\n14. {جس میں} جب رسولوں، برنابا اور پولس، نے سنا، تو انہوں نے اپنے کپڑے پھاڑ دیے، اور لوگوں کے درمیان دوڑے، پکارنے لگے،\n15۔ اور کہا، جناب، آپ یہ سب کیوں کرتے ہیں؟ ہم بھی آپ کے ساتھ اسی طرح کے جذبات کے حامل ہیں، اور آپ کو تبلیغ کرتے ہیں کہ آپ ان بکواس سے زندہ خدا کی طرف رجوع کریں، جس نے آسمان، زمین، سمندر اور اس میں موجود تمام چیزیں بنائی:\n16۔ جس نے ماضی میں تمام قوموں کو اپنی اپنی راہوں پر چلنے دیا تھا۔\n17۔ پھر بھی اس نے خود کو گواہ کے بغیر نہیں چھوڑا، کیونکہ اس نے نیکی کی، اور ہمیں آسمان سے بارش اور پھلدار موسم دیے، ہمارے دلوں کو خوراک اور خوشی سے بھر دیا۔\n18۔ اور ان باتوں کے ساتھ وہ لوگ بمشکل قابو میں رہے، کہ انہوں نے ان کے لیے قربانی نہیں دی۔\n19۔ اور وہاں انطاکیہ اور آئیکونیم سے کچھ یہودی آئے، جنہوں نے لوگوں کو قائل کیا، اور پولوس کو پتھر مار کر شہر سے نکال لیا، یہ سمجھ کر کہ وہ مر چکا ہے۔\n20۔ تاہم، جب شاگرد اس کے ارد گرد کھڑے تھے، وہ اٹھا اور شہر میں داخل ہوا: اور اگلے دن وہ برناباس کے ساتھ ڈربے روانہ ہوا۔\n21۔ اور جب انہوں نے اس شہر کو انجیل سنائی، اور بہت سے لوگوں کو تعلیم دی، تو وہ دوبارہ لسٹرا، اور {ایکونیم} اور انطاکیہ کے پاس واپس آئے، {بہت سے لوگوں کو سکھایا: یونانی نے بہت سے شاگرد بنائے}\n22۔ شاگردوں کی روحوں کی تصدیق کرنا، {اور} انہیں ایمان میں قائم رہنے کی تلقین کرنا، اور یہ کہ ہمیں بہت سی مشکلات کے باوجود خدا کی بادشاہی میں داخل ہونا چاہیے۔\n23۔ اور جب انہوں نے انہیں ہر کلیسیا میں بزرگ مقرر کیا اور روزے سے دعا کی، تو انہوں نے انہیں خداوند کے سپرد کیا، جس پر وہ ایمان رکھتے تھے۔\n24۔ اور جب وہ پسیدیا سے گزر چکے تھے، تو وہ پامفیلیا پہنچے۔\n25۔ اور جب انہوں نے پرگا میں کلام کی تبلیغ کی، تو وہ اتالیا میں اتر گئے:\n26۔ اور وہاں سے انطاکیہ روانہ ہوئے، جہاں سے انہیں خدا کی رحمت کے لیے اس کام کے لیے سفارش کی گئی تھی جو انہوں نے انجام دیا تھا۔\n27۔ اور جب وہ آئے اور کلیسیا کو اکٹھا کیا، تو انہوں نے وہ سب کچھ دہرایا جو خدا نے ان کے ساتھ کیا، اور کیسے اس نے غیر قومیوں کے لیے ایمان کا دروازہ کھولا۔\n28۔ اور وہاں وہ شاگردوں کے ساتھ طویل عرصہ رہے۔","1۔ اور کچھ لوگ جو یہودیہ سے آئے تھے، انہوں نے بھائیوں کو تعلیم دی، {اور کہا}، جب تک تم موسیٰ کے طریقے سے ختنہ نہ نہ ہو جاؤ، تم نجات نہیں پا سکتے۔\n2۔ اس لیے جب پولوس اور برنابا کے درمیان ان کے درمیان اختلاف اور اختلاف ہوا، تو انہوں نے فیصلہ کیا کہ پولس، برنابا اور ان میں سے کچھ دیگر کو یروشلم جا کر رسولوں اور بزرگوں کے پاس اس معاملے پر جانا چاہیے۔\n3۔ اور جب انہیں کلیسیا کے ذریعے لے جایا گیا، تو وہ فینیس اور سامریہ سے گزرے اور غیر یہودیوں کی تبدیلی کا اعلان کیا: اور انہوں نے تمام بھائیوں کو بڑی خوشی دی۔\n4۔ اور جب وہ یروشلم آئے، تو انہیں کلیسا، رسولوں اور بزرگوں کی طرف سے قبول کیا گیا، اور انہوں نے خدا کے ان کے ساتھ کیے گئے تمام کاموں کا اعلان کیا۔\n5۔ لیکن فریسیوں کے فرقے میں سے کچھ لوگ ابھرے جو ایمان رکھتے تھے، کہتے تھے کہ انہیں ختنہ کرنا ضروری ہے، اور انہیں موسیٰ کے قانون کی پابندی کرنے کا حکم دینا چاہیے۔ {روز...: یا، اٹھ کھڑے ہوئے، انہوں نے کہا، یقین}\n6۔ اور رسول اور بزرگ اس معاملے پر غور کرنے کے لیے اکٹھے ہوئے۔\n7۔ اور جب بہت جھگڑا ہوا، پطرس اٹھا اور ان سے کہا، اے لوگ {اور} بھائیو، تم جانتے ہو کہ کافی عرصہ پہلے خدا نے ہم میں سے انتخاب کیا تھا کہ غیر یہودی میرے منہ سے انجیل کا کلام سنیں اور ایمان لائیں۔\n8۔ اور خدا، جو دلوں کو جانتا ہے، ان کی گواہی دے، انہیں روح القدس دے، جیسے اس نے ہمیں دیا؛\n9۔ اور ہمارے اور ان کے درمیان کوئی فرق نہ رکھو، ایمان سے ان کے دلوں کو پاک کرو۔\n10۔ تو پھر تم خدا کو کیوں آزماتے ہو، کہ شاگردوں کی گردن پر جوا ڈالے، جو نہ ہمارے باپ اجداد اور نہ ہم برداشت کر سکے؟\n11۔ لیکن ہم ایمان رکھتے ہیں کہ خداوند یسوع مسیح کے فضل سے ہم نجات پائیں گے، جیسے وہ لوگ کرتے ہیں۔\n12۔ پھر سب لوگ خاموش ہو گئے، اور برنابا اور پولس سے ملاقات کی، اور اعلان کیا کہ خدا نے غیر یہودیوں میں ان کے ذریعے کیا معجزے اور عجائبات کیے ہیں۔\n13۔ اور جب وہ خاموش ہو گئے، جیمز نے جواب دیا، \"اے لوگ {اور} بھائیو، میری بات سنو:\n14۔ شمعون نے اعلان کیا ہے کہ خدا نے سب سے پہلے غیر یہودیوں سے ملاقات کی، تاکہ ان میں سے ایک قوم کو اپنے نام کے لیے نکال سکے۔\n15۔ اور اس پر انبیاء کے الفاظ متفق ہیں؛ جیسا کہ لکھا گیا ہے،\n16۔ اس کے بعد میں واپس آؤں گا، اور داؤد کا خیمہ دوبارہ تعمیر کروں گا، جو گر چکا ہے؛ اور میں اس کے کھنڈرات کو دوبارہ تعمیر کروں گا، اور اسے ترتیب دوں گا:\n17. تاکہ انسانوں کی باقیات خداوند اور تمام غیر یہودی جن پر میرا نام پکارا گیا ہے، کی تلاش میں رہیں، خداوند فرماتا ہے جو یہ سب کچھ کرتا ہے۔\n18۔ خدا کو اس کے تمام اعمال دنیا کے آغاز سے معلوم ہیں۔\n19۔ اسی لیے میرا حکم یہ ہے کہ ہم ان لوگوں کو پریشان نہ کریں جو غیر یہودیوں میں سے خدا کی طرف رجوع کیے گئے ہیں:\n20۔ بلکہ ہم انہیں لکھتے ہیں کہ وہ بتوں کی آلودگی،، گلا گھونٹنے والی چیزوں اور خون سے پرہیز کریں۔\n21۔ کیونکہ پرانے زمانے کے موسیٰ نے ہر شہر میں وہ لوگ جو اس کی تبلیغ کرتے ہیں، ہر سبت کے دن عبادت گاہوں میں پڑھے جاتے ہیں۔\n22۔ پھر رسولوں اور بزرگوں نے، پوری کلیسیا کے ساتھ، اپنی جماعت کے منتخب افراد کو پولوس اور برنابا کے ساتھ انطاکیہ بھیجا؛ {یعنی}، یہودا، جس کا خاندانی نام بارساباس ہے، اور سیلاس، بھائیوں میں سب سے اہم شخص:\n23۔ اور انہوں نے اس طرح ان کے ذریعے {خطوط} لکھے؛ رسول، بزرگ اور بھائی انطاکیہ، شام اور کلیشیا کے غیر یہودیوں کے بھائیوں کو سلام پیش کرتے ہیں:\n24۔ جتنا ہم نے سنا ہے، جو کچھ ہم سے نکلا ہے، اس نے تمہیں الفاظ سے پریشان کیا، تمہاری روحوں کو دبا دیا، کہا کہ {تمہیں} ختنہ کرو، اور قانون کی پاسداری کرو، جسے ہم نے کوئی {یہ} حکم نہیں دیا:\n25۔ ہمیں یہ اچھا لگا، جب ہم ایک ساتھ جمع ہوئے تھے، کہ منتخب لوگوں کو تمہارے پاس اپنے پیارے برناباس اور پولس کے ساتھ بھیجیں،\n26۔ وہ لوگ جنہوں نے ہمارے رب یسوع مسیح کے نام کے لیے اپنی جانیں خطرے میں ڈالیں۔\n27۔ لہٰذا ہم نے یہودا اور سیلاس کو بھیجا ہے، جو بھی تمہیں زبانی طور پر یہی باتیں بتائیں گے۔ {منہ: گریوی لفظ}\n28۔ کیونکہ روح القدس اور ہمارے لیے یہ اچھا لگا کہ تم پر ان ضروری چیزوں سے زیادہ بوجھ نہ ڈالیں؛\n29۔ کہ تم بتوں کو پیش کیے جانے والے گوشت، خون، گلا گھونٹنے والی چیزوں، اور سے پرہیز کرو، جن سے اگر تم خود کو بچاؤ گے تو اچھا کرو گے۔ خدا حافظ۔\n30۔ جب انہیں رخصت کیا گیا، وہ انطاکیہ پہنچے: اور جب انہوں نے ہجوم کو اکٹھا کیا، تو انہوں نے خط پہنچایا:\n31۔ {جو} جب انہوں نے پڑھا، تو تسلی پر خوشی منائی۔ {تسلی: یا، نصیحت}\n32۔ اور یہوداہ اور سیلاس، جو خود بھی نبی تھے، نے بھائیوں کو کئی الفاظ سے نصیحت کی اور ان کی تصدیق کی۔\n33۔ اور جب وہ وہاں کچھ دیر ٹھہرے تو انہیں بھائیوں کی طرف سے امن کے ساتھ رسولوں کے پاس چھوڑ دیا گیا۔\n34۔ اس کے باوجود سیلاس کو وہاں رہنا پسند آیا۔\n35۔ پولوس اور برنابا بھی انطاکیہ میں رہے، خداوند کے کلام کی تعلیم اور تبلیغ کرتے رہے، اور بہت سے دیگر لوگوں کے ساتھ بھی۔\n36۔ اور کچھ دن بعد جب پولوس نے بارناباس سے کہا، آؤ دوبارہ جائیں اور اپنے بھائیوں سے ہر اس شہر میں جائیں جہاں ہم نے خداوند کا کلام سنایا، {اور دیکھیں} کہ وہ کیسے کرتے ہیں۔\n37۔ اور برنابا نے فیصلہ کیا کہ وہ جان کو ساتھ لے جائیں گے، جس کا خاندانی نام مارک تھا۔\n38۔ لیکن پولوس نے اسے اپنے ساتھ لے جانے کے لیے مناسب نہیں سمجھا، جو پامفیلیا سے ان سے الگ ہو گئے تھے اور کام کے لیے ان کے ساتھ نہیں گئے۔\n39۔ اور ان کے درمیان جھگڑا اتنا شدید ہو گیا کہ وہ ایک دوسرے سے جدا ہو گئے: یوں برناباس نے مارک کو لے لیا اور قبرص کی طرف روانہ ہو گیا؛\n40۔ اور پولوس نے سیلاس کو چنا اور بھائیوں کی سفارش پر خدا کی رحمت کے لیے روانہ ہو گیا۔\n41۔ اور وہ شام اور کلیسیا سے گزرے، کلیساؤں کی تصدیق کی۔","1۔ پھر وہ ڈربے اور لسٹرا پہنچا: اور وہاں ایک خاص شاگرد تھا، جس کا نام تیموتھیئس تھا، جو ایک ایسی عورت کا بیٹا تھا جو یہودی تھی، اور ایمان لایا؛ لیکن ان کے والد یونانی تھے:\n2۔ جس کے بارے میں لسٹرا اور آئیکونیم میں موجود بھائیوں نے اچھی طرح رپورٹ کیا۔\n3۔ پولوس کو اس کے ساتھ جانا ہوگا؛ اور انہیں ان یہودیوں کی وجہ سے لے کر ختنہ کیا جو ان علاقوں میں تھے: کیونکہ وہ سب جانتے تھے کہ ان کے والد یونانی تھے۔\n4۔ اور جب وہ شہروں سے گزرے، تو انہوں نے انہیں وہ احکامات دیے جو یروشلم میں موجود رسولوں اور بزرگوں کی طرف سے مقرر کیے گئے تھے۔\n5۔ اسی طرح ایمان میں قائم ہونے والے کلیسائیں بھی تھیں، اور روز بروز تعداد میں اضافہ ہوتا گیا۔\n6۔ اب جب وہ فریگیہ اور گلاطیہ کے علاقے میں گئے، اور روح القدس کی طرف سے ایشیا میں کلام کی تبلیغ سے منع کیا گیا،\n7۔ جب وہ میسیا پہنچے، تو انہوں نے بیتھینیا جانے کی کوشش کی: لیکن روح نے انہیں برداشت نہیں کیا۔\n8۔ اور وہ مائسیا کے پاس سے گزرتے ہوئے ٹروآس پہنچے۔\n9۔ اور رات میں پولس کو ایک خواب آیا؛ وہاں مقدونیہ کا ایک آدمی کھڑا تھا، اور اس سے دعا کر رہا تھا، کہہ رہا تھا، مقدونیہ میں آؤ اور ہماری مدد کرو۔\n10۔ اور جب اس نے خواب دیکھا، تو ہم فورا مقدونیہ جانے کی کوشش کی، یقین سے کہ خداوند نے ہمیں بلایا ہے تاکہ انہیں انجیل سنانے کے لیے بلایا جائے۔\n11۔ لہٰذا ٹروآس سے ہار کر، ہم سیدھے راستے سے ساموتھریشیا پہنچے، اور اگلے دن نیاپولس کی طرف؛\n12۔ اور وہاں سے فلیپی تک، جو مقدونیہ کے اس حصے کا مرکزی شہر ہے، {اور} ایک کالونی ہے: اور ہم اس شہر میں کچھ دنوں تک رہے۔ {چیف: یا، پہلا}\n13۔ اور سبت کے دن ہم شہر سے دریا کے کنارے نکلے، جہاں دعا کی جاتی تھی؛ اور ہم بیٹھ گئے، اور ان عورتوں سے بات کی جو وہاں آئیں۔ {سبات: گریڈ سبت ڈے}\n14۔ اور ایک عورت جس کا نام لیدیا تھا، جو تھیاتیرا شہر کی جامنی رنگ بیچنے والی تھی اور خدا کی عبادت کرتی تھی، نے سنا {ہمیں}: جس کے دل کو خداوند نے کھول دیا، کہ وہ پولس کے بارے میں کہی گئی باتوں کی خدمت کرتی رہی۔\n15۔ اور جب وہ بپتسمہ ہوئی، اور اس کے خاندان نے ہم سے دعا کی، کہا، اگر تم نے مجھے خدا کے وفادار قرار دیا ہے، تو میرے گھر آؤ، اور وہاں رہو۔ اور اس نے ہمیں محدود کر دیا۔\n16۔ اور جب ہم دعا کے لیے گئے، تو ایک خاص دوشیزہ جس میں غیب بینی کی روح تھی، ہم سے ملی، جس نے اپنے مالکان کو بہت فائدہ پہنچایا: {فال گیری: یا، پائتھن کی}\n17۔ وہی لوگ پولوس اور ہمارے پیچھے گئے، اور پکارے، کہنے لگے، یہ لوگ سب سے بلند خدا کے خادم ہیں، جو ہمیں نجات کا راستہ دکھاتا ہے۔\n18۔ اور اس نے کئی دن ایسا کیا۔ لیکن پولس، غمگین ہو کر، مڑا اور روح سے کہا، میں تمہیں یسوع مسیح کے نام پر حکم دیتا ہوں کہ اس سے باہر آؤ۔ اور وہ اسی گھنٹے میں باہر آیا۔\n19۔ اور جب اس کے آقاؤں نے دیکھا کہ ان کی کامیابیوں کی امید ختم ہو گئی ہے، تو انہوں نے پال اور سیلاس کو پکڑ لیا، اور {ان} کو بازار میں حکمرانوں کے سامنے لے آئے، {بازار: یا، دربار}\n20۔ اور انہیں مجسٹریٹ کے پاس لے جا کر کہا، یہ لوگ یہودی ہونے کی وجہ سے ہمارے شہر کو بہت پریشان کرتے ہیں،\n21. اور وہ رسم و رواج سکھائیں جو ہمیں رومی ہونے کی وجہ سے قبول کرنے یا ان پر عمل کرنے کے لیے جائز نہیں ہیں۔\n22۔ اور ہجوم نے مل کر ان کے خلاف اٹھ کھڑے ہو گئے: اور مجسٹریٹوں نے ان کے کپڑے پھاڑ دیے اور انہیں مارنے کا حکم دیا۔\n23۔ اور جب انہوں نے ان پر کئی پٹیاں ڈال دیں، تو انہوں نے {ان} کو قید میں ڈال دیا، قیدی کو حکم دیا کہ وہ انہیں محفوظ رکھے:\n24۔ جس نے ایسا الزام وصول کر کے انہیں اندرونی قید خانے میں دھکیل دیا، اور ان کے قدم مٹھی میں مضبوط کر لیے۔\n25۔ اور آدھی رات کو پال اور سیلاس نے دعا کی، اور خدا کی حمد گائی: اور قیدیوں نے انہیں سنا۔\n26۔ اور اچانک ایک زبردست زلزلہ آیا، جس سے قید خانے کی بنیادیں ہل گئیں: اور فورا تمام دروازے کھول دیے گئے، اور سب کی پٹیاں کھول دی گئیں۔\n27۔ اور قید خانے کا محافظ نیند سے جاگا اور جب اس نے قید خانے کے دروازے کھلے دیکھے، تو اس نے اپنی تلوار نکالی اور خودکشی کر لیتا، یہ سمجھتے ہوئے کہ قیدی فرار ہو چکے ہیں۔\n28۔ لیکن پولوس نے زور سے پکارا، کہا، اپنے آپ کو نقصان نہ پہنچاؤ، کیونکہ ہم سب یہاں ہیں۔\n29۔ پھر اس نے روشنی کے لیے پکارا، اور چھلانگ لگا کر آیا، اور پولس اور سیلاس کے سامنے گر پڑا،\n30۔ اور انہیں باہر لے آیا اور کہا، جنابوں، مجھے بچنے کے لیے کیا کرنا ہوگا؟\n31۔ اور انہوں نے کہا، خداوند یسوع مسیح پر ایمان لاؤ، اور تم نجات پاؤ گے، اور تمہارا گھر۔\n32۔ اور انہوں نے اس سے خداوند کا کلام اور اس کے گھر میں موجود سب لوگوں سے کہا۔\n33۔ اور اس نے رات کے اسی وقت انہیں لیا اور ان کے کپڑے دھوئے؛ اور اسے اور اس کے سب کو فورا بپتسمہ دیا گیا۔\n34۔ اور جب اس نے انہیں اپنے گھر میں لایا، تو اس نے ان کے سامنے گوشت رکھا اور خوشی منائی، خدا پر اپنے پورے گھر کے ساتھ ایمان لاتے ہوئے۔\n35۔ اور جب دن آیا، مجسٹریٹوں نے سارجنٹس کو بھیجا، کہا، ان لوگوں کو جانے دو۔\n36۔ اور قید خانے کے رکھوالے نے یہ بات پولس سے کہی، مجسٹریٹس نے تمہیں جانے دینے کے لیے بھیجا ہے: اب چلے جاؤ اور امن سے جاؤ۔\n37۔ لیکن پولوس نے ان سے کہا، انہوں نے ہمیں بغیر مذمت کے مارا ہے، کیونکہ ہم رومی ہیں، اور ہمیں قید میں ڈال دیا ہے؛ اور اب کیا وہ ہمیں نجی طور پر باہر نکال دیتے ہیں؟ بالکل نہیں؛ لیکن انہیں خود آنے دو اور ہمیں باہر لے جانے دو۔\n38۔ اور سرجنٹس نے یہ باتیں مجسٹریٹوں کو کہیں: اور جب انہیں معلوم ہوا کہ وہ رومی ہیں تو وہ ڈر گئے۔\n39۔ اور وہ آئے اور ان سے التجا کی، انہیں باہر نکالا، اور انہیں شہر سے نکلنے کی درخواست کی۔\n40۔ اور وہ قید خانے سے باہر نکلے اور لیدیا کے گھر میں داخل ہو گئے، اور جب انہوں نے بھائیوں کو دیکھا تو انہیں تسلی دی اور روانہ ہو گئے۔","1۔ جب وہ ایمفیپولیس اور اپولونیا سے گزرے تو وہ تھیسالونیکا پہنچے، جہاں یہودیوں کی ایک عبادت گاہ تھی:\n2۔ اور پولس، جیسا کہ اس کا طریقہ تھا، ان کے پاس گیا، اور تین سبت کے دن ان سے صحیفوں کی بنیاد پر بحث کی،\n3۔ کھلنا اور یہ دعویٰ کرنا کہ مسیح نے ضرور تکلیف اٹھائی ہے اور مردوں میں سے دوبارہ زندہ ہوا ہے؛ اور یہ یسوع، جسے میں آپ کو تبلیغ کرتا ہوں، مسیح ہے۔ {کون...: یا، کون، اس نے کہا، میں تبلیغ کرتا ہوں}\n4۔ اور ان میں سے کچھ ایمان لاتے تھے، اور پولس اور سیلاس کے ساتھ تعلقات بناتے تھے؛ اور دیندار یونانیوں کی بڑی تعداد تھی، اور اہم خواتین میں سے کچھ نہیں۔\n5۔ لیکن جو یہودی ایمان نہ لاتے تھے، حسد سے متاثر ہوئے، کچھ بدکردار لوگوں کو اپنے پاس لے گئے، ایک گروہ جمع کیا، پورے شہر کو ہنگامہ برپا کر دیا، یسون کے گھر پر حملہ کیا اور انہیں لوگوں کے سامنے لانے کی کوشش کی۔\n6۔ اور جب وہ انہیں نہ پائے تو انہوں نے یسون اور کچھ بھائیوں کو شہر کے حکمرانوں کے پاس بلایا اور پکارا، جو دنیا کو الٹ پلٹ کر چکے ہیں وہ بھی یہاں آ گئے ہیں؛\n7۔ جسے جیسن نے پایا ہے: اور یہ سب قیصر کے احکامات کے خلاف ہیں، کہتے ہیں کہ ایک اور بادشاہ ہے، {ایک} یسوع۔\n8۔ اور جب انہوں نے یہ باتیں سنیں تو انہوں نے لوگوں اور شہر کے حکمرانوں کو پریشان کر دیا۔\n9۔ اور جب انہوں نے جیسن اور دوسرے کی حفاظت حاصل کی، تو انہیں جانے دیا۔\n10۔ اور بھائیوں نے فورا پولس اور سیلاس کو رات کو بیریا بھیج دیا: جو وہاں آ کر یہودیوں کی عبادت گاہ میں چلے گئے۔\n11۔ یہ لوگ تھیسالونیکا کے لوگوں سے زیادہ شریف تھے، کیونکہ انہوں نے کلام کو پوری ذہنی تیاری کے ساتھ قبول کیا، اور روزانہ صحیفوں میں تلاش کرتے کہ کیا یہ چیزیں درست ہیں۔\n12۔ اسی لیے ان میں سے بہت سے ایمان رکھتے تھے؛ اور معزز خواتین جو یونانی تھیں، اور مردوں کی، چند ہی نہیں۔\n13۔ لیکن جب تھیسالونیکا کے یہودیوں کو معلوم ہوا کہ خدا کا کلام پولس نے بیریا میں سنایا ہے، تو وہ بھی وہاں آئے اور لوگوں کو مشتعل کیا۔\n14۔ اور پھر فورا بھائیوں نے پولس کو سمندر کی طرف بھیج دیا، لیکن سیلاس اور تیموتھیئس وہاں رہے۔\n15۔ اور جن لوگوں نے پال کو سنبھالا، وہ اسے ایتھنز لے گئے: اور جب انہوں نے سیلاس اور تیموتھیئس کو حکم دیا کہ وہ جلدی اس کے پاس آئیں، تو وہ روانہ ہو گئے۔\n16۔ اب جب پولوس ایتھنز میں ان کا انتظار کر رہا تھا، اس کی روح اس میں جاگ اٹھی جب اس نے دیکھا کہ شہر مکمل طور پر بت پرستی کے لیے وقف ہے۔ {مکمل طور پر...: یا، بتوں سے بھرپور}\n17۔ اس لیے وہ یہودیوں اور دیندار افراد سے کنیسہ میں روزانہ ان سے بحث کرتا تھا جو اس سے ملتے تھے۔\n18۔ پھر ایپیکیورینز اور اسٹوئکس کے کچھ فلسفیوں نے ان سے ملاقات کی۔ اور کچھ نے کہا، یہ بکواس کرنے والا کیا کہے گا؟ کچھ میں، وہ عجیب دیوتاؤں کا سنگر لگتا ہے: کیونکہ اس نے انہیں یسوع اور قیامت کی تبلیغ کی۔ {بابلر: یا، بیکار آدمی}\n19۔ اور انہوں نے اسے لے کر آریوپاگس کے پاس لے گئے، کہنے لگے، کیا ہم جان سکتے ہیں کہ یہ نیا عقیدہ، جس کے بارے میں تم بات کر رہے ہو، کیا ہے؟ {ایریوپیگس: یا، مارس کی پہاڑی: یہ ایتھنز کی سب سے اعلیٰ عدالت تھی}\n20۔ کیونکہ تو ہمارے کانوں تک کچھ عجیب باتیں لاتا ہے: اس لیے ہم جاننا چاہتے ہیں کہ یہ چیزیں کیا معنی رکھتی ہیں۔\n21۔ (کیونکہ وہاں موجود تمام ایتھنز اور اجنبی اپنا وقت صرف بتانے یا کچھ نیا سننے میں گزارتے تھے۔)\n22۔ پھر پولس مارس کی پہاڑی کے بیچ کھڑا ہوا اور کہا، {اے ایتھنز کے لوگو، میں سمجھتا ہوں کہ تم ہر چیز میں بہت زیادہ توہم پرست ہو۔ {مارس کی پہاڑی: یا، آریوپیگیٹس کا دربار}\n23. کیونکہ جب میں گزر رہا تھا اور تمہاری عبادات کو دیکھا، تو مجھے ایک قربان گاہ ملی جس پر یہ عبارت تھی، نامعلوم خدا کے نام۔ اسی لیے جس کی تم لاعلمی میں عبادت کرتے ہو، وہ تمہیں اعلان کرتا ہے۔ {عبادتیں: یا، وہ خدا جن کی تم عبادت کرتے ہو}\n24۔ خدا جس نے دنیا اور اس میں موجود سب کچھ بنایا، کیونکہ وہ آسمان اور زمین کا رب ہے، ہاتھوں سے بنے ہوئے مندروں میں نہیں رہتا؛\n25۔ دونوں کو انسانوں کے ہاتھوں سے پوجا نہیں جاتا، جیسے اسے کسی چیز کی ضرورت ہو، کیونکہ وہ تمام زندگی، سانس اور ہر چیز کو دیتا ہے؛\n26۔ اور اس نے ایک ہی خون سے تمام قوموں کو زمین کے تمام چہرے پر رہنے کے لیے بنایا ہے، اور مقرر شدہ اوقات اور ان کی رہائش کی حدود کا تعین کیا ہے؛\n27۔ کہ وہ خداوند کی تلاش کریں، اگر وہ اس کے پیچھے محسوس کر سکیں، اور اسے پا سکیں، چاہے وہ ہم سب سے دور نہ ہو:\n28۔ کیونکہ ہم اس میں رہتے ہیں، حرکت کرتے ہیں، اور اپنا وجود رکھتے ہیں؛ جیسا کہ آپ کے کچھ شاعروں نے بھی کہا ہے، کیونکہ ہم بھی اس کی اولاد ہیں۔\n29۔ چونکہ چونکہ ہم خدا کی اولاد ہیں، ہمیں یہ نہیں سوچنا چاہیے کہ خدا کی ذات سونے، چاندی یا پتھر کی مانند ہے، جو فن اور انسان کی چال سے تراشا گیا ہے۔\n30۔ اور اس جہالت کے اوقات میں خدا نے آنکھ ماری؛ لیکن اب سب لوگوں کو ہر جگہ توبہ کرنے کا حکم دیتا ہے:\n31. کیونکہ اس نے ایک دن مقرر کیا ہے، جس میں وہ دنیا کو راستبازی میں اس شخص کے ذریعے فیصلہ کرے گا جسے اس نے مقرر کیا ہے؛ {جس کی وجہ سے} اس نے سب {انسان} کو یقین دلایا ہے، کیونکہ اس نے اسے مردوں میں سے زندہ کیا ہے۔ {دیا ہے...: یا، ایمان پیش کرتا ہے}\n32۔ اور جب انہوں نے مردوں کی قیامت کی خبر سنی تو کچھ نے مذاق اڑایا: اور کچھ نے کہا، ہم اس {معاملے} کے بارے میں تمہیں دوبارہ سنیں گے۔\n33۔ یوں پولوس ان میں سے چلا گیا۔\n34۔ تاہم کچھ لوگ اس کے ساتھ جھک جاتے ہیں اور ایمان لاتے ہیں: جن میں سے ایک دیونیسیئس دی آریوپیگائٹ، ایک عورت داماریس اور ان کے ساتھ دیگر افراد شامل ہیں۔","1۔ ان سب کے بعد پولوس ایتھنز سے روانہ ہوا اور کورنتھ آیا؛\n2۔ اور ایک یہودی ایکویلا کو پایا، جو پونٹس میں پیدا ہوا، حال ہی میں اٹلی سے آیا تھا، اپنی بیوی پریسیلا کے ساتھ؛ (کیونکہ کلاڈیئس نے تمام یہودیوں کو روم سے روانہ ہونے کا حکم دیا تھا:) اور وہ ان کے پاس آیا۔\n3۔ اور چونکہ وہ بھی اسی ہنر سے تھا، اس نے ان کے ساتھ رہائش اختیار کی اور کام کیا: کیونکہ ان کے پیشے کی وجہ سے وہ خیمے بنانے والے تھے۔\n4۔ اور وہ ہر سبت کو عبادت گاہ میں استدلال کرتا اور یہودیوں اور یونانیوں کو قائل کرتا۔\n5۔ اور جب سیلاس اور تیموتھیس مقدونیہ سے آئے، تو پولوس روح میں دباؤ ڈالا گیا، اور یہودیوں کو گواہی دی کہ یسوع مسیح تھا۔ {کیا مسیح تھا: یا، مسیح ہے}\n6۔ اور جب انہوں نے خود پر اعتراض کیا اور کفر کی، تو اس نے اپنا لباس ہلایا اور ان سے کہا، تمہارا خون تمہارے اپنے سروں پر ہو؛ میں {پاک} ہوں: اب سے میں غیر قوموں کے پاس جاؤں گا۔\n7۔ اور وہ وہاں سے روانہ ہوا، اور ایک {آدمی} کے گھر میں داخل ہوا، جس کا نام جسٹس تھا، {ایک} جو خدا کی عبادت کرتا تھا، جس کا گھر عبادت گاہ سے سخت جڑا ہوا تھا۔\n8۔ اور کرسپس، جو عبادت گاہ کا سب سے بڑا حکمران تھا، نے اپنے پورے گھر کے ساتھ خداوند پر ایمان لایا؛ اور کرنتھیوں میں سے بہت سے سننے والوں نے ایمان لانا اور بپتسمہ لیا۔\n9۔ پھر خداوند نے رات کو پال سے ایک خواب کے ذریعے کہا، ڈرو مت، بلکہ بولو، اور خاموش نہ رہو:\n10۔ کیونکہ میں تمہارے ساتھ ہوں، اور کوئی تم پر حملہ نہیں کرے گا کہ تمہیں نقصان پہنچائے: کیونکہ اس شہر میں میرے بہت لوگ ہیں۔\n11۔ اور وہ وہاں ایک سال چھ ماہ تک خدا کے کلام کی تعلیم دیتا رہا۔ {وہاں جاری ہے: گریڈ وہاں بیٹھا تھا}\n12۔ اور جب گیلیو آخایا کا نائب تھا، یہودیوں نے ایک اتفاق کے ساتھ پولس کے خلاف بغاوت کی اور اسے عدالت کی نشست پر لے آیا،\n13۔ کہتے ہوئے، یہ {ساتھی} لوگوں کو قانون کے خلاف خدا کی عبادت کرنے پر آمادہ کرتا ہے۔\n14۔ اور جب پولوس اب اپنا منہ کھولنے ہی والا تھا، گالیو نے یہودیوں سے کہا، اگر یہ غلط یا بدکاری کا معاملہ ہو، اے یہودیوں، عقل چاہتی کہ میں تم سے برداشت کروں:\n15۔ لیکن اگر بات الفاظ اور ناموں اور آپ کے قانون کی ہو، تو آپ اس کی طرف دیکھیں؛ کیونکہ میں ایسے معاملات کا جج نہیں ہوں گا۔\n16۔ اور اس نے انہیں ججمنٹ سیٹ سے ہٹا دیا۔\n17۔ پھر تمام یونانیوں نے سوستھینیز، جو عبادت گاہ کا سربراہ تھا، کو لے لیا اور اسے عدالت کی نشست کے سامنے مارا۔ اور گیلیو کو ان میں سے کسی چیز کی پرواہ نہیں تھی۔\n18۔ اور پولس {اس کے بعد} وہاں کافی دیر رکا، پھر بھائیوں سے رخصت لیا، اور وہاں سے شام روانہ ہوا، اور اس کے ساتھ پریسیلا اور ایکویلا بھی؛ اس نے سینکریا میں اپنا سر قلم کر دیا تھا: کیونکہ اس نے وعدہ کیا تھا۔\n19۔ اور وہ افسس آیا، اور انہیں وہاں چھوڑ دیا، لیکن وہ خود عبادت گاہ میں داخل ہوا اور یہودیوں سے بات چیت کی۔\n20۔ جب انہوں نے کہا کہ وہ ان کے ساتھ زیادہ وقت گزارے، تو اس نے رضامندی نہیں دی؛\n21۔ لیکن میں نے انہیں الوداع کہا، کہہ کر، مجھے ہر صورت یروشلم میں آنے والی یہ دعوت منانی ہے: لیکن اگر خدا چاہے تو میں تمہارے پاس واپس آؤں گا۔ اور وہ افسس سے روانہ ہوا۔\n22۔ اور جب وہ قیصریہ پہنچا، اوپر گیا اور چرچ کو سلام کیا، تو وہ انطاکیہ نیچے چلا گیا۔\n23۔ اور کچھ وقت وہاں گزارنے کے بعد، وہ روانہ ہوا، اور گلاطیہ اور فریگیا کے تمام علاقوں کا جائزہ لیا، تمام شاگردوں کو مضبوط کیا۔\n24۔ اور ایک یہودی جس کا نام اپولس تھا، جو اسکندریہ میں پیدا ہوا، ایک فصیح شخص، {اور} صحیفوں میں بہت طاقتور، افسس آیا۔\n25۔ اس آدمی کو خداوند کے راستے میں تعلیم دی گئی تھی؛ اور روح میں پرجوش ہونے کی وجہ سے، وہ بولتا اور محنت سے خداوند کی باتیں سکھاتا، صرف یوحنا کے بپتسمہ کو جانتے ہوئے۔\n26۔ اور اس نے کنیسہ میں جرات مندی سے بات کرنا شروع کی: جب ایکویلا اور پریسیلا نے سنا تو انہوں نے اسے اپنے پاس لے جا کر خدا کا راستہ زیادہ تفصیل سے بیان کیا۔\n27۔ اور جب وہ آخایا جانے کے لیے تیار ہوا، تو بھائیوں نے لکھا، شاگردوں کو اسے قبول کرنے کی تلقین کی: جو جب آیا تو انہوں نے ان کی بہت مدد کی جو فضل کے ذریعے ایمان رکھتے تھے:\n28۔ کیونکہ اس نے یہودیوں کو زبردست قائل کیا، {اور وہ بھی} عوامی طور پر، صحیفوں کے ذریعے ظاہر کرتے ہوئے کہ یسوع مسیح ہے۔ {مسیح: یا، کیا مسیح ہے}","1۔ اور ایسا ہوا کہ جب اپولس کورنتھ میں تھا، پولوس اوپری ساحلوں سے گزر کر افسس پہنچا: اور کچھ شاگردوں کو پایا،\n2. اس نے ان سے کہا، کیا تم نے ایمان لانے کے بعد روح القدس کو قبول کیا ہے؟ اور انہوں نے اس سے کہا، ہم نے ابھی تک نہیں سنا کہ کوئی روح القدس ہے یا نہیں۔\n3۔ اور اس نے ان سے کہا، پھر تم نے کس چیز کے لیے بپتسمہ لیا؟ اور انہوں نے کہا، یوحنا کے بپتسمہ کے لیے۔\n4۔ پھر پولس نے کہا، یوحنا نے واقعی توبہ کے بپتسمہ سے بپتسمہ دیا، لوگوں سے کہا کہ وہ اس پر ایمان لائیں جو اس کے بعد آئے گا، یعنی مسیح یسوع پر۔\n5۔ جب انہوں نے یہ سنا، تو انہیں خداوند یسوع کے نام پر بپتسمہ دیا گیا۔\n6۔ اور جب پولوس نے ان پر {اپنے} ہاتھ رکھے تو روح القدس ان پر آیا؛ اور انہوں نے زبانوں سے بات کی، اور پیش گوئی کی۔\n7۔ اور تمام مرد تقریبا بارہ سال کے تھے۔\n8۔ اور وہ عبادت گاہ میں گیا، اور تین ماہ تک جرات مندی سے بات کی، خدا کی بادشاہی سے متعلق معاملات پر بحث اور قائل کیا۔\n9۔ لیکن جب غوطہ خور سخت ہو گئے اور ایمان نہ لاتے تھے بلکہ ہجوم کے سامنے اس طرح برائی کرتے تھے، تو وہ ان سے دور ہو گیا، اور شاگردوں کو الگ کر دیا، روزانہ ایک ٹائرانس کے اسکول میں بحث کرتے رہے۔\n10۔ اور یہ سلسلہ دو سال تک جاری رہا؛ تاکہ ایشیا میں رہنے والے سب نے خداوند یسوع کا کلام سنا، چاہے یہودی ہوں یا یونانی۔\n11۔ اور خدا نے پولس کے ہاتھوں خاص معجزے کیے:\n12۔ تاکہ اس کے جسم سے بیمار رومال یا اپرون لائے جائیں، اور ان سے بیماریاں دور ہو گئیں، اور ان سے بد روحیں نکل آئیں۔\n13۔ پھر کچھ آوارہ یہودی، جن نکالنے والے تھے، نے ان پر ذمہ داری لی کہ وہ جن میں برے ارواح تھیں، خداوند یسوع کا نام پکاریں، اور کہا، ہم آپ کو یسوع کے ذریعے عہد کرتے ہیں جسے پولس تبلیغ کرتا ہے۔\n14۔ اور {ایک} سکیوا کے سات بیٹے تھے، جو ایک یہودی تھا اور پادریوں کا سردار تھا، جس نے ایسا کیا۔\n15۔ اور شیطانی روح نے جواب دیا اور کہا، یسوع کو میں جانتا ہوں، اور پولس کو جانتا ہوں؛ لیکن تم کون ہو؟\n16۔ اور وہ آدمی جس میں شیطانی روح ان پر حملہ آور ہوئی، انہیں شکست دی اور ان پر غالب آ گیا، یہاں تک کہ وہ اس گھر سے ننگے اور زخمی ہو کر بھاگ گئے۔\n17۔ اور یہ بات تمام یہودیوں اور یونانیوں کو معلوم تھی جو افسس میں بھی رہتے تھے؛ اور سب پر خوف چھا گیا، اور خداوند یسوع کا نام بلند ہوا۔\n18۔ اور بہت سے ایمان والے آئے، اعتراف کیا، اور اپنے اعمال دکھائے۔\n19۔ ان میں سے بہت سے جنہوں نے عجیب و غریب فنون لطیفہ استعمال کیے، اپنی کتابیں اکٹھی کیں اور سب کے سامنے جلا دیں: اور انہوں نے ان کی قیمت گنی، اور انہیں پچاس ہزار چاندی کے ٹکڑے ملے۔\n20. خدا کا کلام اس قدر زور سے بڑھا اور غالب آیا۔\n21۔ ان سب کے ختم ہونے کے بعد، پولوس نے روح کے ذریعے ارادہ کیا، جب وہ مقدونیہ اور اخایا سے گزر کر یروشلم جائے گا، اور کہا، جب میں وہاں پہنچ جاؤں گا تو مجھے روم بھی دیکھنا ہوگا۔\n22۔ تو اس نے مقدونیہ میں ان میں سے دو کو بھیجا جو اس کی خدمت کرتے تھے، تیموتھیئس اور ایراسٹوس؛ لیکن وہ خود ایک سیزن کے لیے ایشیا میں رہے۔\n23۔ اور اسی وقت اس حوالے سے کوئی معمولی ہلچل نہیں اٹھی۔\n24۔ ایک {آدمی} جس کا نام ڈیمیٹریوس تھا، جو چاندی کا کاریگر تھا، جو ڈیانا کے لیے چاندی کے مزار بناتا تھا، کاریگروں کو کوئی خاص فائدہ دیتا تھا؛\n25۔ جنہیں اس نے اسی پیشے کے مزدوروں کے ساتھ بلایا اور کہا، جناب، آپ جانتے ہیں کہ اس ہنر سے ہمیں اپنی دولت حاصل ہے۔\n26۔ مزید یہ کہ آپ دیکھتے اور سنتے ہیں کہ صرف ایفیسس میں نہیں بلکہ تقریبا پورے ایشیا میں، اس پولس نے بہت سے لوگوں کو قائل کیا اور انہیں دور کر دیا، یہ کہتے ہوئے کہ وہ کوئی خدا نہیں ہیں جو ہاتھوں سے بنے ہوں:\n27۔ تاکہ نہ صرف یہ ہمارا جہاز خطرے میں ہو اور ختم نہ ہو جائے؛ بلکہ یہ بھی کہ عظیم دیوی ڈیانا کے مندر کو حقیر سمجھا جائے، اور اس کی شان و شوکت کو تباہ کیا جائے، جسے پورا ایشیا اور دنیا پوجتے ہیں۔ {صفر پر مقررہ: یا، بدنام کیا گیا، یا، حقارت}\n28۔ اور جب انہوں نے یہ کہاوتیں سنی، تو وہ غصے سے بھر گئے اور پکارا، کہا، عظیم {یہ} افسیوں کی دیانا ہے۔\n29۔ اور پورا شہر افراتفری میں پھیل گیا: اور جب انہوں نے گائیئس اور اریسٹارکس، مقدونیہ کے لوگ، پولوس کے سفر کے ساتھی، کو پکڑ لیا، تو وہ ایک ساتھ تھیٹر میں دوڑے۔\n30۔ اور جب پولوس لوگوں میں داخل ہونا چاہتا تو شاگردوں نے اسے برداشت نہیں کیا۔\n31۔ اور ایشیا کے کچھ سردار، جو اس کے دوست تھے، اس کے پاس بھیجے گئے، یہ چاہتے ہوئے کہ وہ خود کو تھیٹر میں نہ لے جائے۔\n32۔ اس لیے کچھ نے ایک بات پکاری، اور کچھ اور: کیونکہ مجمع الجھن میں تھا؛ اور زیادہ تر حصے کو معلوم نہیں تھا کہ وہ کیوں اکٹھے ہوئے۔\n33۔ اور انہوں نے سکندر کو ہجوم میں سے نکالا، یہودیوں نے اسے آگے کیا۔ اور سکندر نے ہاتھ سے اشارہ کیا، اور عوام کے سامنے اپنا دفاع کرنا چاہتا تھا۔\n34۔ لیکن جب انہیں معلوم ہوا کہ وہ یہودی ہے، تو دو گھنٹے کے اندر سب نے ایک ہی آواز میں پکارا، عظیم {ہے} افسیوں کی ڈیانا۔\n35۔ اور جب شہر کے کلرک نے لوگوں کو خوش کیا، تو کہا، {اے افسس کے لوگو، کون سا آدمی ہے جو نہیں جانتا کہ افسیوں کا شہر عظیم دیوی دیانا کا پوجا کرتا ہے، اور اس {شبیہ} کا جو مشتری سے گرا ہے؟ {ایک عبادت گزار: گری۔ مندر کا محافظ}\n36۔ اگر آپ دیکھیں کہ ان باتوں کے خلاف بات نہیں کی جا سکتی، تو آپ کو خاموش رہنا چاہیے اور جلد بازی میں کچھ نہ کرنا چاہیے۔\n37۔ کیونکہ تم نے یہ لوگ یہاں لائے ہیں، جو نہ تو کلیساؤں کے چور ہیں اور نہ ہی تمہاری دیوی کے کفر کرنے والے۔\n38۔ لہٰذا اگر دیمتریوس اور اس کے ساتھ موجود کاریگر کسی شخص کے خلاف کوئی معاملہ رکھتے ہیں، تو قانون کھلا ہوتا ہے، اور نائب بھی ہوتے ہیں: وہ ایک دوسرے کو الزام دیتے ہیں۔ {قانون...: یا، عدالت کے دن برقرار رکھے جاتے ہیں}\n39۔ لیکن اگر آپ کسی اور معاملے کے بارے میں سوال کریں تو اسے جائز مجلس میں طے کیا جائے گا۔ {قانونی: یا، عام}\n40۔ کیونکہ ہم اس دن کے ہنگامے کی وجہ سے سوال اٹھانے کے خطرے میں ہیں، کیونکہ ہم اس محفل کی کوئی وضاحت نہیں کر سکتے۔\n41۔ اور جب اس نے یہ بات کہی، تو اس نے اسمبلی کو رخصت کر دیا۔","1۔ اور جب ہنگامہ ختم ہوا، پولس نے شاگردوں کو بلایا، انہیں گلے لگایا، اور مقدونیہ جانے کے لیے روانہ ہو گیا۔\n2۔ اور جب اس نے ان حصوں کا جائزہ لیا اور انہیں بہت نصیحت دی، تو وہ یونان آیا،\n3. اور {یہاں} تین ماہ رہائے۔ اور جب یہودیوں نے اس کا انتظار کیا، جب وہ شام جانے والا تھا، تو اس نے مقدونیہ کے راستے واپس جانے کا ارادہ کیا۔\n4۔ اور وہاں اس کے ساتھ ایشیا سوپیٹر آف بیریا گئے؛ اور تھیسالونیائیوں، اریسٹارکس اور سیکنڈس کی؛ اور گائوس آف ڈربے اور تیموتھیئس؛ اور ایشیا، ٹائیکیکس اور ٹروفیمس۔\n5. یہ جو پہلے جا رہے تھے، ہمارے لیے ٹروآس میں رکے ہوئے تھے۔\n6۔ اور ہم فلیپی سے بغیر خمیر کی روٹی کے دنوں کے بعد روانہ ہوئے، اور پانچ دن میں ان کے پاس ٹروآس پہنچے؛ جہاں ہم سات دن رہے۔\n7۔ اور ہفتے کے پہلے دن، جب شاگرد روٹی توڑنے کے لیے اکٹھے ہوئے، پولوس نے ان سے تبلیغ کی، کل روانہ ہونے کے لیے تیار؛ اور اپنی تقریر آدھی رات تک جاری رکھی۔\n8۔ اور اوپر والے کمرے میں بہت سی روشنیاں تھیں، جہاں وہ اکٹھی تھیں۔\n9۔ اور وہاں ایک کھڑکی میں ایک نوجوان بیٹھا تھا جس کا نام ایوتیکس تھا، گہری نیند میں جا رہا تھا: اور چونکہ پولوس طویل تبلیغ کر رہا تھا، وہ نیند میں ڈوب گیا، تیسرے لوفت سے گر گیا، اور اسے مردہ اٹھایا گیا۔\n10۔ اور پولوس نیچے آیا، اس پر گر پڑا، اور اسے گلے لگا کر کہا، خود کو پریشان نہ کرو؛ کیونکہ اس کی زندگی اس میں ہے۔\n11۔ جب وہ دوبارہ اوپر آیا، اور روٹی توڑی، کھایا، اور کافی دیر باتیں کیں، یہاں تک کہ صبح نکلے، تو وہ روانہ ہو گیا۔\n12۔ اور انہوں نے نوجوان کو زندہ لایا، اور انہیں کچھ تسلی نہیں ملی۔\n13۔ اور ہم پہلے جہاز پر چلے گئے، اور اسوس کی طرف روانہ ہوئے، وہاں پولس کو لینے کا ارادہ رکھتے ہوئے: کیونکہ اس نے ایسا ہی فیصلہ کیا تھا، اور پیدل چلنے کا ارادہ کیا۔\n14۔ اور جب وہ اسوس میں ہم سے ملا، ہم نے اسے اپنے پاس رکھا اور میٹیلین آ گئے۔\n15۔ اور ہم وہاں سے روانہ ہوئے، اور اگلے دن خیوس کے خلاف پہنچے؛ اور اگلے دن ہم ساموس پہنچے، اور ٹروگیلیم میں ٹھہرے؛ اور اگلے {دن} ہم میلیٹس پہنچے۔\n16۔ کیونکہ پولوس نے فیصلہ کیا تھا کہ وہ ایفیسس کے راستے روانہ ہوگا، کیونکہ وہ ایشیا میں وقت گزارنا نہیں چاہتا تھا: کیونکہ اگر ممکن ہو تو وہ پنٹیکوسٹ کے دن یروشلم پہنچنے کی جلدی کرتا تھا۔\n17۔ اور میلیٹس سے اس نے افسس بھیجا اور کلیسیا کے بزرگوں کو بلایا۔\n18۔ اور جب وہ اس کے پاس آئے، تو اس نے ان سے کہا، تم جانتے ہو، جب سے میں ایشیا میں آیا تھا، میں تمہارے ساتھ ہر وقت کس طرح رہا ہوں،\n19۔ خداوند کی خدمت انکساری کے ساتھ، بہت سے آنسوؤں اور آزمائشوں کے ساتھ، جو یہودیوں کے انتظار میں پڑنے سے مجھ پر آئیں:\n20۔ {اور} کہ میں نے وہ کچھ بھی نہیں چھپایا جو تمہارے لیے فائدہ مند ہو، لیکن تمہیں دکھایا، اور تمہیں عوامی طور پر سکھایا، اور گھر گھر سکھایا،\n21۔ یہودیوں اور یونانیوں دونوں کے سامنے خدا کی طرف توبہ اور ہمارے رب یسوع مسیح پر ایمان کی گواہی دینا۔\n22. اور اب، دیکھو، میں روح کے ساتھ یروشلم جا رہا ہوں، یہ جانے بغیر کہ وہاں میرے ساتھ کیا ہونے والا ہے:\n23۔ سوائے اس کے کہ روح القدس ہر شہر میں گواہی دے، اور کہے کہ بندھن اور مصیبتیں میرے ساتھ رہیں گی۔ {میرے لیے رہو: یا، میرا انتظار کرو}\n24. لیکن ان میں سے کوئی بھی چیز مجھے متاثر نہیں کرتی، نہ ہی میں اپنی زندگی کو اپنے لیے عزیز سمجھتا ہوں، تاکہ میں خوشی سے اپنا سفر مکمل کر سکوں، اور وہ خدمت جو میں نے خداوند یسوع کی طرف سے حاصل کی ہے، خدا کے فضل کی خوشخبری کی گواہی دینے کے لیے۔\n25۔ اور اب، دیکھو، میں جانتا ہوں کہ تم سب، جن کے درمیان میں خدا کی بادشاہی کی تبلیغ کر رہا ہوں، میرا چہرہ دوبارہ نہیں دیکھو گے۔\n26۔ اسی لیے میں تمہیں آج کا دن ریکارڈ کرنے کے لیے لے جاتا ہوں، کہ میں {انسان} کے خون سے پاک ہوں۔\n27۔ کیونکہ میں نے آپ کو خدا کی تمام نصیحتیں دینے سے نہیں کترایا۔\n28۔ اس لیے اپنے اور تمام ریوڑ سے ہوشیار رہو، جن پر روح القدس نے تمہیں نگران بنایا ہے، تاکہ خدا کے چرچ کو کھلا سکیں، جو اس نے اپنے خون سے خریدی ہے۔\n29۔ کیونکہ میں یہ جانتا ہوں کہ میرے جانے کے بعد تم میں خوفناک بھیڑیے داخل ہوں گے، اور ریوڑ کو نہیں چھوڑیں گے۔\n30۔ اسی طرح آپ کے اپنے آپ میں سے لوگ اٹھیں گے، غلط باتیں کریں گے، تاکہ شاگردوں کو ان کے پیچھے لے جائیں۔\n31. لہٰذا دیکھو، اور یاد رکھو کہ تین سال کے عرصے میں میں نے ہر رات اور دن آنسوؤں سے خبردار کرنا بند کر دیا۔\n32۔ اور اب، بھائیو، میں آپ کو خدا کے سپرد کرتا ہوں، اور اس کے فضل کے کلام کو، جو آپ کو تعمیر کر سکتا ہے، اور آپ کو ان تمام پاکیزہ لوگوں میں وراثت دے سکتا ہے۔\n33۔ میں نے کسی کی چاندی، سونا، یا لباس کی خواہش نہیں کی۔\n34۔ جی ہاں، آپ خود جانتے ہیں کہ ان ہاتھوں نے میری ضروریات پوری کی ہیں، اور جو میرے ساتھ تھے۔\n35. میں نے آپ کو سب کچھ دکھایا ہے کہ آپ کو کتنی محنت کرنی چاہیے کہ کمزوروں کی مدد کریں، اور خداوند یسوع کے الفاظ کو یاد رکھیں، جس نے کہا، دینا لینے سے زیادہ بابرکت ہے۔\n36۔ اور جب اس نے یہ کہا، تو وہ گھٹنے ٹیک کر سب کے ساتھ دعا کرنے لگا۔\n37۔ اور وہ سب رونے لگے، پولس کی گردن پر گر گئے، اور اسے بوسہ دیا،\n38۔ سب سے زیادہ ان الفاظ پر افسوس جو انہوں نے کہے، کہ وہ اس کا چہرہ دوبارہ نہ دیکھیں۔ اور وہ اس کے ساتھ جہاز تک گئے۔","1۔ اور ایسا ہوا کہ جب ہم ان سے نکل گئے اور روانہ ہو گئے، تو ہم سیدھے راستے سے کوس پہنچے، اور {دن} کے بعد روڈس کی طرف، اور وہاں سے پٹارا تک:\n2۔ اور جب ایک جہاز فینیشیا کی طرف جا رہا تھا، تو ہم سوار ہوئے اور روانہ ہوئے۔\n3۔ جب ہم نے قبرص دریافت کیا، تو ہم نے اسے بائیں طرف چھوڑ دیا، شام کی طرف روانہ ہوئے، اور صور پر اترے: کیونکہ وہاں جہاز کو اپنا بوجھ اتارنا تھا۔\n4۔ اور جب ہم نے شاگرد پائے، تو ہم وہاں سات دن رہے: جنہوں نے پولس کو روح کے ذریعے کہا کہ وہ یروشلم نہ جائے۔\n5۔ اور جب ہم نے وہ دن مکمل کیے، تو ہم روانہ ہوئے اور اپنی راہ پر چل دیے؛ اور وہ سب ہمیں اپنی بیویوں اور بچوں کے ساتھ لے گئے، یہاں تک کہ ہم شہر سے باہر نکل گئے: اور ہم ساحل پر گھٹنے ٹیک کر دعا کرنے لگے۔\n6۔ اور جب ہم نے ایک دوسرے سے رخصت لی، تو ہم نے جہاز پر قبضہ کیا؛ اور وہ دوبارہ گھر لوٹ آئے۔\n7۔ اور جب ہم نے صور سے اپنا سفر مکمل کیا، تو ہم بطلیمیس پہنچے، بھائیوں کو سلام کیا، اور ایک دن ان کے ساتھ ٹھہرے۔\n8۔ اور اگلے دن ہم جو پولوس کے ساتھ تھے، روانہ ہوئے اور قیصریہ پہنچے: اور ہم فلپ مبلغ کے گھر میں داخل ہوئے، جو سات میں سے ایک تھا؛ اور اس کے ساتھ رہتا تھا۔\n9۔ اور اسی آدمی کی چار بیٹیاں تھیں، کنواری، جنہوں نے نبوت کی۔\n10۔ اور جب ہم وہاں کئی دن رہے، تو یہودیہ سے ایک نبی آیا، جس کا نام اگابوس تھا۔\n11۔ اور جب وہ ہمارے پاس آیا، اس نے پولس کی بیلٹ لی، اپنے ہاتھ اور پاؤں باندھ دیے، اور کہا، روح القدس کہتا ہے، اسی طرح یروشلم کے یہودی اس بندھن کے مالک کو باندھ دیں گے، اور اسے غیر یہودیوں کے ہاتھوں میں دے دیں گے۔\n12۔ اور جب ہم نے یہ باتیں سنیں، تو ہم اور اس جگہ کے لوگ دونوں نے اس سے درخواست کی کہ وہ یروشلم نہ جائے۔\n13۔ پھر پولوس نے جواب دیا، تم کیوں روتے ہو اور میرا دل توڑتے ہو؟ کیونکہ میں صرف پابند ہونے کے لیے نہیں، بلکہ یروشلم میں خداوند یسوع کے نام کے لیے مرنے کے لیے بھی تیار ہوں۔\n14۔ اور جب وہ قائل نہ ہوا، تو ہم نے رک کر کہا، خداوند کی مرضی پوری ہو۔\n15۔ اور ان دنوں کے بعد ہم نے اپنی گاڑیاں لیں اور یروشلم کی طرف روانہ ہوئے۔\n16۔ ہمارے ساتھ قیصریہ کے کچھ شاگرد بھی گئے، اور ان کے ساتھ قبرص کا مناسون لائے، جو ایک پرانا شاگرد تھا، جس کے ساتھ ہمیں قیام کرنا تھا۔\n17۔ اور جب ہم یروشلم پہنچے، بھائیوں نے ہمیں خوشی سے قبول کیا۔\n18۔ اور اگلے دن پولس ہمارے ساتھ یعقوب کے پاس گیا؛ اور تمام بزرگ موجود تھے۔\n19۔ اور جب اس نے انہیں سلام کیا، تو خاص طور پر اعلان کیا کہ خدا نے اپنی خدمت کے ذریعے غیر یہودیوں میں کیا کچھ کیا۔\n20۔ اور جب انہوں نے یہ سنا، تو انہوں نے خداوند کی جلال کی اور کہا، بھائی، تو دیکھتے ہو کہ ہزاروں یہودی ایمان رکھتے ہیں؛ اور وہ سب قانون کے پابند ہیں:\n21۔ اور انہیں آپ کے بارے میں بتایا گیا ہے کہ آپ تمام یہودیوں کو جو غیر یہودیوں میں ہیں، موسیٰ کو چھوڑنے کی تعلیم دیتے ہیں، کہتے ہیں کہ انہیں اپنے بچوں کا ختنہ نہیں کرنا چاہیے، نہ ہی رسم و رواج کی پیروی کرنی چاہیے۔\n22۔ تو پھر یہ کیا ہے؟ ہجوم کو اکٹھا ہونا چاہیے: کیونکہ وہ سنیں گے کہ تم آ گئے ہو۔\n23. لہٰذا یہ کرو جو ہم تم سے کہتے ہیں: ہمارے پاس چار آدمی ہیں جن پر عہد ہے؛\n24۔ انہیں لے لو، اور ان کے ساتھ خود کو پاک کرو، اور ان کے ساتھ ذمہ داری سنبھالو، تاکہ وہ اپنے سر منڈوا سکیں: اور سب جان لیں کہ وہ چیزیں جن کے بارے میں انہوں نے تمہارے بارے میں بتایا تھا، کچھ بھی نہیں؛ لیکن {کہ} تم خود بھی منظم طریقے سے چلتے ہو، اور قانون کی پاسداری کرتے ہو۔\n25۔ غیر یہودیوں کے بارے میں جو ایمان رکھتے ہیں، ہم نے لکھا ہے {اور} نتیجہ اخذ کیا ہے کہ وہ ایسی کوئی چیز نہیں مانتے، سوائے اس کے کہ وہ خود کو بتوں کو پیش کی جانے والی چیزوں، خون، گلا گھونٹنے اور سے بچاتے ہیں۔\n26۔ پھر پولوس نے ان مردوں کو لیا، اور اگلے دن ان کے ساتھ پاک ہو کر ہیکل میں داخل ہوا، تاکہ پاکیزگی کے دنوں کی تکمیل کی علامت ہو، یہاں تک کہ ہر ایک کے لیے ایک قربانی پیش کی جائے۔\n27۔ اور جب سات دن تقریبا ختم ہو گئے، تو ایشیا کے یہودی جب انہوں نے اسے مندر میں دیکھا، تو سب لوگوں کو ہلکا سا جھنجھوڑ دیا اور اس پر ہاتھ رکھ دیے،\n28۔ اسرائیلی حضرات، مدد کرو پکار: یہ وہ آدمی ہے جو ہر جگہ سب {انسان} کو لوگوں کے خلاف، قانون اور اس جگہ کے خلاف سکھاتا ہے: اور یونانیوں کو بھی مندر میں لایا ہے، اور اس مقدس جگہ کو آلودہ کر دیا ہے۔\n29۔ (کیونکہ انہوں نے اس سے پہلے شہر میں ٹروفیمس کو ایک ایفیسی دیکھا تھا، جسے وہ سمجھتے تھے کہ پولوس نے مندر میں لایا تھا۔)\n30۔ اور پورا شہر منتقل ہو گیا، اور لوگ اکٹھے دوڑے: اور انہوں نے پال کو لے کر مندر سے نکالا، اور فورا دروازے بند کر دیے گئے۔\n31۔ اور جب وہ اسے مارنے لگے تو گروہ کے سردار کو خبر ملی کہ پورا یروشلم ہلچل مچا رہا ہے۔\n32۔ جس نے فورا سپاہیوں اور سینچورینز کو لے کر ان کے پاس دوڑا: اور جب انہوں نے چیف کپتان اور سپاہیوں کو دیکھا، تو وہ پولس کو مارتے ہوئے چھوڑ گئے۔\n33۔ پھر چیف کپتان قریب آیا، اسے پکڑ کر حکم دیا کہ اسے دو زنجیروں سے باندھا جائے؛ اور پوچھا کہ وہ کون ہے، اور اس نے کیا کیا ہے۔\n34۔ اور کچھ نے ہجوم میں ایک بات پکاری، کچھ اور، اور جب وہ ہنگامے کی یقین دہانی نہ جان سکا، تو اس نے حکم دیا کہ اسے قلعے کے اندر لے جایا جائے۔\n35۔ اور جب وہ سیڑھیوں پر پہنچا، تو ایسا ہی ہوا کہ وہ لوگوں کے تشدد کے لیے سپاہیوں میں سے پیدا ہوا۔\n36۔ کیونکہ لوگوں کی بڑی تعداد اس کے پیچھے چلتی ہوئی چلتی رہی، اسے لے جاؤ۔\n37۔ اور جب پال کو قلعے میں لے جایا جانا تھا، اس نے چیف کپتان سے کہا، کیا میں تم سے بات کر سکتا ہوں؟ کس نے کہا، کیا تم یونانی بول سکتے ہو؟\n38۔ کیا تم وہ مصری نہیں جو آج کل ہنگامہ برپا کر کے چار ہزار قاتل لوگوں کو ویرانے میں لے گیا؟\n39۔ لیکن پولوس نے کہا، میں ایک ایسا آدمی ہوں جو ترسوس کا یہودی ہوں، کلیشیا کا ایک شہر، ایک عام شہر کا شہری ہوں: اور میں تم سے التجا کرتا ہوں، مجھے لوگوں سے بات کرنے دو۔\n40۔ اور جب اس نے اسے اجازت دی، پولس سیڑھیوں پر کھڑا ہوا اور لوگوں کو ہاتھ سے اشارہ کیا۔ اور جب ایک بڑی خاموشی چھا گئی، تو اس نے عبرانی زبان میں ان سے کہا،","1. حضرات، بھائیو، اور باپوں، میری حمایت سنو {جو میں اب تم سے کرتا ہوں}۔\n2۔ (اور جب انہوں نے سنا کہ اس نے ان سے عبرانی زبان میں بات کی، تو وہ زیادہ خاموش رہے: اور وہ کہتا ہے،)\n3۔ میں واقعی ایک یہودی ہوں، جو ترسوس میں پیدا ہوا، کلیشیا میں ایک شہر، پھر بھی اس شہر میں گمالیئل کے قدموں میں پلا بڑھا، اور باپ اجداد کے قانون کے کامل طریقے کے مطابق تعلیم دی گئی، اور خدا کے لیے پرجوش تھا، جیسا کہ آپ سب آج ہیں۔\n4۔ اور میں نے اسی طرح موت تک ظلم کیا، مردوں اور عورتوں دونوں کو باندھ کر جیلوں میں پہنچایا۔\n5۔ جیسا کہ اعلیٰ کاهن بھی مجھے گواہ دیتا ہے، اور بزرگوں کی تمام جائیداد بھی، جن سے میں نے بھائیوں کو خطوط وصول کیے، اور دمشق گیا، تاکہ ان کو یروشلم لے آؤں جو وہاں بندھے ہوئے تھے، تاکہ انہیں سزا دی جا سکے۔\n6۔ اور ایسا ہوا کہ جب میں اپنا سفر کر رہا تھا اور دوپہر کے قریب دمشق کے قریب پہنچا، اچانک آسمان سے میرے گرد ایک عظیم روشنی چمک اٹھی۔\n7۔ اور میں زمین پر گر گیا، اور ایک آواز سنی جو مجھ سے کہہ رہی تھی: ساؤل، ساؤل، تم مجھے کیوں ستاتے ہو؟\n8۔ اور میں نے جواب دیا، اے خداوند، تو کون ہو؟ اور اس نے مجھ سے کہا، میں ناصرت کا یسوع ہوں، جسے تم ستاتے ہو۔\n9۔ اور جو میرے ساتھ تھے انہوں نے واقعی روشنی دیکھی اور ڈر گئے؛ لیکن انہوں نے اس کی آواز نہیں سنی جو مجھ سے بولی۔\n10۔ اور میں نے کہا، میں کیا کروں، خداوند؟ اور خداوند نے مجھ سے کہا، اٹھو اور دمشق میں جاؤ؛ اور وہاں تمہیں وہ سب کچھ بتایا جائے گا جو تمہارے لیے مقرر کیے گئے ہیں۔\n11۔ اور جب میں اس روشنی کی شان کو دیکھ نہ سکا، ان لوگوں کے ہاتھ کی رہنمائی میں جو میرے ساتھ تھے، میں دمشق پہنچا۔\n12۔ اور ایک انانیاس، جو شریعت کے مطابق ایک دیندار آدمی تھا، اور وہاں رہنے والے تمام یہودیوں کی اچھی خبر رکھتا تھا،\n13۔ میرے پاس آیا، کھڑا ہوا اور مجھ سے کہا، بھائی ساؤل، اپنی نظر قبول کرو۔ اور اسی گھنٹے میں نے اس کی طرف دیکھا۔\n14۔ اور اس نے کہا، ہمارے آباؤ اجداد کے خدا نے تمہیں چنا ہے، تاکہ تم اس کی مرضی جانو، اور اس نیک کو دیکھو، اور اس کے منہ کی آواز سنو۔\n15۔ کیونکہ تم سب لوگوں کے سامنے اس کی گواہی بنو گے جو تم نے دیکھا اور سنا۔\n16. اور اب تم سب سے زیادہ کیوں رکے ہو؟ اٹھو، بپتسمہ لو، اور اپنے گناہ دھو دو، خداوند کے نام کو پکارو۔\n17۔ اور ایسا ہوا کہ جب میں دوبارہ یروشلم آیا، چاہے میں مندر میں دعا کر رہا تھا، میں ایک غنودگی میں تھا؛\n18۔ اور دیکھا کہ وہ مجھ سے کہہ رہا ہے، جلدی کرو اور جلدی یروشلم سے نکل جاؤ، کیونکہ وہ میرے بارے میں تمہاری گواہی قبول نہیں کریں گے۔\n19۔ اور میں نے کہا، اے خداوند، وہ جانتے ہیں کہ میں نے ہر عبادت گاہ میں ان لوگوں کو قید کیا اور مارا جو تم پر ایمان لاتے تھے:\n20۔ اور جب تیرے شہید اسٹیفن کا خون بہایا گیا، میں بھی اس کی موت کے لیے تیار تھا، اور ان لوگوں کا لباس سنبھالا جنہوں نے اسے مارا۔\n21۔ اور اس نے مجھ سے کہا، چلے جاؤ، کیونکہ میں تمہیں دور غیر یہودیوں کے پاس بھیجوں گا۔\n22۔ اور انہوں نے اسے اس لفظ کی سماعت دی، اور پھر اپنی آوازیں بلند کیں اور کہا، ایسے {ساتھی} کو زمین سے دور کر دو، کیونکہ یہ مناسب نہیں کہ وہ زندہ رہے۔\n23۔ اور جب انہوں نے چیخا، اپنے کپڑے اتار دیے، اور ہوا میں گرد اچھال دی،\n24۔ چیف کپتان نے حکم دیا کہ اسے قلعے میں لایا جائے، اور حکم دیا کہ اسے کوڑے مار کر معائنہ کیا جائے؛ تاکہ وہ جان سکے کہ وہ اس کے خلاف کیوں روتے ہیں۔\n25۔ اور جب انہوں نے اسے تھونگز میں باندھا، پولوس نے اس سینچورین سے کہا جو کھڑا تھا، کیا یہ جائز ہے کہ تم ایک رومی اور غیر ملامت شدہ آدمی کو کوڑے مارو؟\n26۔ جب سینچورین نے یہ سنا، تو وہ گیا اور چیف کپتان کو بتایا، کہا، جو تم کر رہے ہو اس پر دھیان دو، کیونکہ یہ آدمی رومی ہے۔\n27۔ پھر چیف کپتان آیا اور اس سے کہا، بتاؤ، کیا تم رومی ہو؟ اس نے کہا، ہاں۔\n28۔ اور چیف کیپٹن نے جواب دیا، بڑی رقم سے میں نے یہ آزادی حاصل کی۔ اور پال نے کہا، لیکن میں {آزاد} پیدا ہوا تھا۔\n29۔ پھر وہ فورا اس سے روانہ ہو گئے جو اسے جانچنا چاہیے تھا: اور چیف کیپٹن بھی ڈر گیا، کیونکہ اسے معلوم ہوا کہ وہ رومی ہے، اور کیونکہ اس نے اسے باندھا تھا۔ {اس کا معائنہ کیا: یا، اسے اذیت دی}\n30۔ کل، چونکہ وہ یقین کو جاننا چاہتا تھا کہ اس پر یہودیوں کا الزام کیوں لگایا گیا، اس نے اسے اس کے گروہوں سے آزاد کر دیا، اور سردار کاہنوں اور ان کے تمام مشیروں کو حکم دیا کہ وہ حاضر ہوں، اور پولس کو نیچے لایا اور ان کے سامنے رکھا۔","1۔ اور پولس، خلوص سے کونسل کو دیکھ کر، کہا، اے انسانو {اور} بھائیو، میں آج تک خدا کے سامنے پوری ضمیر کے ساتھ زندگی گزار رہا ہوں۔\n2۔ اور سردار کاہن حنانیا نے ان لوگوں کو حکم دیا جو اس کے ساتھ کھڑے تھے کہ وہ اس کے منہ پر ماریں۔\n3۔ پھر پولس نے اس سے کہا، خدا تمہیں مارے گا، اے سفید دیوار، کیونکہ کیا تم مجھے قانون کے مطابق فیصلہ کرنے کے لیے بیٹھے ہو، اور مجھے قانون کے خلاف مارنے کا حکم دیتے ہو؟\n4۔ اور جو لوگ کھڑے تھے انہوں نے کہا، کیا تم خدا کے اعلیٰ کاہن کو برا سمجھتے ہو؟\n5۔ پھر پولس نے کہا، بھائیو، مجھے نہیں معلوم کہ وہ اعلیٰ کاہن تھا: کیونکہ لکھا ہے، تم اپنے لوگوں کے حکمران کے بارے میں برا نہ بولنا۔\n6۔ لیکن جب پولوس نے دیکھا کہ ایک حصہ صدوقی ہے اور باقی فریسی، تو اس نے کونسل میں پکارا، اے بھائیو، میں فریسی ہوں، فریسی کا بیٹا: مردوں کی امید اور قیامت پر مجھ پر سوال اٹھایا جاتا ہے۔\n7۔ اور جب اس نے یہ کہا، تو فریسیوں اور صدوقیوں کے درمیان اختلاف پیدا ہوا: اور ہجوم تقسیم ہو گیا۔\n8۔ کیونکہ صدوقیوں کہتے ہیں کہ نہ کوئی قیامت ہے، نہ فرشتہ اور نہ روح: بلکہ فریسی دونوں کا اعتراف کرتے ہیں۔\n9۔ اور ایک بڑی پکار اٹھی: اور فریسیوں کے کاتب اٹھے اور کوشش کی، کہنے لگے، ہمیں اس آدمی میں کوئی برائی نظر نہیں آتی: لیکن اگر کوئی روح یا فرشتہ اس سے بات کر چکا ہے، تو ہم خدا کے خلاف نہ لڑیں۔\n10۔ اور جب بڑا اختلاف ہوا، تو چیف کپتان نے، خوفزدہ کہ کہیں پال کو ٹکڑوں میں نہ کھینچ لیا جائے، سپاہیوں کو حکم دیا کہ وہ نیچے جائیں، اور اسے زبردستی اپنے درمیان سے لے کر قلعے میں لے آئیں۔\n11۔ اور اگلی رات خداوند اس کے ساتھ کھڑا ہوا اور کہا، خوش رہو، پولس، کیونکہ جیسے تم نے یروشلم میں میرے بارے میں گواہی دی، ویسے ہی تم روم میں بھی گواہی دینی چاہیے۔\n12۔ اور جب دن آیا، کچھ یہودیوں نے اکٹھے ہو کر خود کو لعنت میں باندھ لیا، کہا کہ جب تک وہ پولوس کو قتل نہ کر دیں، نہ کھائیں گے نہ پئیں گے۔ {لعنت کے تحت: یا، سزا کی قسم کے ساتھ}\n13۔ اور وہ چالیس سے زیادہ تھے جنہوں نے یہ سازش کی۔\n14۔ اور وہ سردار پادریوں اور بزرگوں کے پاس آئے اور کہا، ہم نے خود کو ایک بڑی لعنت میں باندھا ہے کہ ہم کچھ نہیں کھائیں گے جب تک کہ ہم پولوس کو قتل نہ کر دیں۔\n15۔ اب تم کونسل کے ساتھ چیف کپتان کو اشارہ دو کہ وہ اسے کل تمہارے پاس لے آئے، جیسے تم اس کے بارے میں کچھ زیادہ واضح پوچھنا چاہتے ہو: اور ہم، یا جب بھی وہ قریب آئے، اسے مارنے کے لیے تیار ہیں۔\n16۔ اور جب پولس کی بہن کے بیٹے کو معلوم ہوا کہ وہ انتظار میں ہیں، تو وہ قلعے میں داخل ہوا اور پولوس کو بتایا۔\n17۔ پھر پولوس نے ایک سینچورین کو بلایا اور کہا، اس نوجوان کو چیف کپتان کے پاس لے آؤ، کیونکہ اسے کچھ کہنا ہے۔\n18۔ تو اس نے اسے لے کر چیف کیپٹن کے پاس لے جا کر کہا، قیدی پال نے مجھے بلایا اور دعا کی کہ میں اس نوجوان کو تمہارے پاس لے آؤں، جس کے پاس تم سے کچھ کہنا ہے۔\n19۔ پھر چیف کپتان نے اس کا ہاتھ پکڑ کر {اس کے ساتھ} چلا گیا اور {اس} سے پوچھا، تم مجھے کیا بتانا چاہتے ہو؟\n20۔ اور اس نے کہا، یہودیوں نے تم سے درخواست کی ہے کہ تم پولس کو کل کونسل میں لے آؤ، گویا وہ اس سے کچھ بہتر پوچھنا چاہتے ہیں۔\n21۔ لیکن تم ان کے سامنے نہ جھکاؤ، کیونکہ ان میں سے چالیس سے زیادہ آدمی اس کے انتظار میں ہیں، جنہوں نے خود کو یہ قسم دی ہے کہ جب تک وہ اسے قتل نہ کر دیں، نہ کھائیں گے نہ پئیں گے؛ اور اب وہ تیار ہیں، تم سے وعدے کی تلاش میں۔\n22۔ تو چیف کپتان نے نوجوان کو جانے دیا، اور حکم دیا کہ کوئی شخص نہ بتائے کہ تم نے یہ باتیں مجھے دکھائی ہیں۔\n23۔ اور اس نے دو سینچورینز کو بلایا، کہا، دو سو سپاہی قیصریہ جانے کے لیے تیار کرو، اور تین سو گھڑ سوار اور دو سو نیزہ بردار، رات کے تیسرے وقت پر؛\n24۔ اور ان کے لیے جانور فراہم کرو، تاکہ وہ پال پر حملہ کر سکیں، اور اسے فیلکس گورنر کے پاس محفوظ لے آئیں۔\n25۔ اور اس نے اس طرح ایک خط لکھا:\n26۔ کلاڈیئس لیسیاس، سب سے بہترین گورنر فیلکس کو {بھیجیں} سلام۔\n27۔ یہ آدمی یہودیوں میں سے لیا گیا، اور اسے مارنا چاہیے تھا: پھر میں فوج کے ساتھ آیا اور اسے بچایا، یہ جان کر کہ وہ رومی ہے۔\n28۔ اور جب میں جاننا چاہتا کہ انہوں نے اس پر الزام کیوں لگایا، تو میں نے اسے ان کی کونسل میں شامل کیا:\n29۔ جس پر میں نے اپنے قانون کے سوالات کا الزام لگایا، لیکن اس پر موت یا قید کے لائق کوئی الزام عائد نہیں کیا گیا۔\n30۔ اور جب مجھے بتایا گیا کہ یہودیوں نے اس آدمی کا انتظار کیا ہے، تو میں نے فورا تمہارے پاس بھیجا اور اس کے الزام لگانے والوں کو حکم دیا کہ وہ تمہارے سامنے وہ سب کچھ بتائیں جو انہوں نے اس کے خلاف کیا۔ الوداع۔\n31۔ پھر سپاہیوں نے، جیسا کہ انہیں حکم دیا گیا تھا، پال کو لے کر رات کو اینٹیپاتریس لے آئے۔\n32۔ کل وہ گھڑ سواروں کو چھوڑ کر اس کے ساتھ چلے گئے، اور قلعے واپس آئے:\n33۔ جب وہ قیصریہ پہنچے اور گورنر کو خط دیا، تو پولس کو بھی اس کے سامنے پیش کیا۔\n34۔ اور جب گورنر نے {خط} پڑھا، تو اس نے پوچھا کہ وہ کون سا صوبہ ہے۔ اور جب اسے سمجھ آیا کہ {وہ} کلیشیا کا ہے؛\n35۔ میں تمہاری بات سنوں گا، اس نے کہا، جب تمہارے مدعی بھی آئیں گے۔ اور اس نے حکم دیا کہ اسے ہیرودیس کے عدالتی ہال میں رکھا جائے۔","1۔ اور پانچ دن بعد انانیاس سردار کاہن بزرگوں کے ساتھ نیچے آیا، اور {ساتھ} ایک مقرر {نام} ترٹولوس کے ساتھ، جس نے گورنر کو پولس کے خلاف اطلاع دی۔\n2۔ اور جب اسے بلایا گیا، تو ٹرٹولس نے {اسے} پر الزام لگانا شروع کیا، کہا، کیونکہ تیرے ذریعے ہمیں بڑی سکون ملتا ہے، اور اس قوم کے لیے بہت نیک کام انجام دیے جاتے ہیں،\n3. ہم ہمیشہ اور ہر جگہ سب سے معزز فیلکس کو شکرگزاری کے ساتھ قبول کرتے ہیں۔\n4۔ اس کے باوجود، کہ میں آپ کے لیے مزید بور نہیں ہوں، میں آپ سے درخواست کرتا ہوں کہ آپ اپنی رحم دلی کے بارے میں ہمیں چند الفاظ سنیں۔\n5۔ کیونکہ ہم نے اس شخص کو {a} ایک وبا دار {آدمی} پایا ہے، جو دنیا بھر کے یہودیوں میں بغاوت پھیلانے والا ہے، اور ناصریوں کے فرقے کا سرغنہ ہے:\n6۔ جس نے بھی مندر کی بے حرمتی کی: جسے ہم نے لیا اور اپنے قانون کے مطابق فیصلہ کرنا چاہا۔\n7۔ لیکن چیف کیپٹن لیسیاس نے ہم پر حملہ کیا، اور بڑی شدت سے اسے ہمارے ہاتھوں سے لے لیا،\n8۔ اپنے الزام لگانے والوں کو حکم دینا کہ وہ تمہارے پاس آئیں: یہ جانچ کر کہ تم خود کس کو ان سب باتوں کا علم رکھتے ہو، جن پر ہم الزام لگا رہے ہیں۔\n9۔ اور یہودیوں نے بھی اتفاق کیا، کہا کہ یہ باتیں درست ہیں۔\n10۔ پھر پولس، جب گورنر نے اسے بولنے کا اشارہ کیا، تو جواب دیا، چونکہ میں جانتا ہوں کہ تم کئی سالوں سے اس قوم کے جج رہے ہو، میں اپنے لیے زیادہ خوش دلی سے جواب دیتا ہوں:\n11۔ تاکہ تم سمجھ سکو، کہ میں یروشلم میں عبادت کے لیے جانے کو صرف بارہ دن ہوئے ہیں۔\n12۔ اور انہوں نے مجھے مندر میں کسی آدمی سے بحث کرتے ہوئے نہیں پایا، نہ لوگوں کو زندہ کرتے ہوئے، نہ عبادت گاہوں میں، نہ شہر میں:\n13۔ نہ ہی وہ وہ چیزیں ثابت کر سکتے ہیں جن پر وہ اب مجھ پر الزام لگا رہے ہیں۔\n14۔ لیکن میں یہ اعتراف کرتا ہوں کہ جس طرح وہ بدعت کہتے ہیں، اسی طرح میں اپنے آباؤ اجداد کے خدا کی عبادت کرتا ہوں، اور شریعت اور نبیوں میں لکھی ہر چیز پر ایمان رکھتا ہوں:\n15۔ اور خدا کی طرف امید رکھیں، جسے وہ خود بھی اجازت دیتے ہیں، کہ مردوں کی دوبارہ زندہ ہوگی، چاہے وہ نیک ہوں یا ناانصاف۔\n16۔ اور یہاں میں خود کو یہ مشق دیتا ہوں کہ ہمیشہ خدا اور انسانوں کے خلاف کوئی ضمیر نہ ہو۔\n17۔ کئی سالوں کے بعد میں اپنی قوم کو خیرات اور نذرانے لانے آیا ہوں۔\n18۔ جس پر ایشیا کے کچھ یہودیوں نے مجھے ہیکل میں پاک پایا، نہ ہجوم سے، نہ ہنگامے سے۔\n19۔ جو آپ سے پہلے یہاں ہوتے، اور اگر انہیں میرے خلاف اعتراض کرنا چاہیے ہوتا۔\n20۔ یا پھر یہی {یہاں} کہیں، اگر انہوں نے مجھ میں کوئی برائی دیکھی ہے، جب میں کونسل کے سامنے کھڑا ہوں،\n21. سوائے اس ایک آواز کے، جس کے لیے میں نے ان کے درمیان کھڑے ہو کر پکارا، مردوں کی قیامت کو چھوتے ہوئے، آج تم مجھ پر سوال اٹھاتے ہو۔\n22۔ اور جب فیلکس نے یہ باتیں سنیں، کیونکہ وہ اس طریقے کا زیادہ علم رکھتا تھا، تو اس نے انہیں مؤخر کر دیا اور کہا، جب لیسیاس چیف کپتان نیچے آئے گا، تو میں تمہارے معاملے کی مکمل تفصیل جان لوں گا۔\n23. اور اس نے ایک سینچورین کو حکم دیا کہ وہ پال کو رکھے، اور اسے آزادی دے، اور کہ وہ اپنے کسی جاننے والے کو خدمت کرنے یا اس کے پاس آنے سے منع نہ کرے۔\n24۔ اور کچھ دنوں بعد، جب فیلکس اپنی بیوی ڈروسلا کے ساتھ آیا، جو یہودی تھی، اس نے پولس کو بلایا اور اسے مسیح پر ایمان کے بارے میں سنا۔\n25۔ اور جب اس نے نیکی، اعتدال اور آنے والے فیصلے کے بارے میں سوچا، تو فیلکس کانپ اٹھا اور جواب دیا، اس وقت اپنے راستے پر چلو؛ جب میرے پاس مناسب وقت ہوگا، میں تمہیں پکاروں گا۔\n26۔ اس نے یہ بھی امید کی کہ پال اسے پیسے دیے جائیں تاکہ وہ اسے کھو دے: اسی لیے اس نے اکثر لوگوں کو بلایا اور اس سے بات چیت کی۔\n27۔ لیکن دو سال بعد پورسیئس فیسٹس فیلکس کے کمرے میں آیا: اور فیلکس، یہودیوں کو خوشی دینے کے لیے، پولس کو باندھ کر چھوڑ گیا۔","1۔ جب فیسٹس صوبے میں آیا، تین دن بعد وہ قیصریہ سے یروشلم چڑھا۔\n2۔ پھر اعلیٰ کاہن اور یہودیوں کے سردار نے اسے پولس کے خلاف اطلاع دی اور اس سے درخواست کی،\n3۔ اور اس کے خلاف عنایت کی خواہش کی کہ وہ اسے یروشلم بھیجے، راستے میں اسے مارنے کے لیے۔\n4۔ لیکن فیسٹس نے جواب دیا کہ پولوس کو قیصریہ میں رکھا جائے، اور وہ خود جلد ہی وہاں روانہ ہو جائے۔\n5۔ لہٰذا، اس نے کہا، جو تم میں سے جو قابل ہے، میرے ساتھ نیچے آ کر اس آدمی پر الزام لگائیں، اگر اس میں کوئی برائی ہے۔\n6۔ اور جب وہ ان کے درمیان دس دن سے زیادہ رہا، تو قیصریہ گیا؛ اور اگلے دن عدالت کی نشست پر بیٹھ کر پولس کو لانے کا حکم دیا۔ {مزید...: یا، جیسا کہ کچھ نسخوں میں لکھا ہے، آٹھ یا دس دن سے زیادہ نہیں}\n7۔ اور جب وہ آیا، یروشلم سے آنے والے یہودی ارد گرد کھڑے ہو گئے اور پولس کے خلاف کئی اور سنگین شکایات کیں، جنہیں وہ ثابت نہ کر سکے۔\n8۔ اگرچہ اس نے خود جواب دیا، نہ یہودیوں کے قانون کے خلاف، نہ ہیکل کے خلاف، اور نہ ابھی قیصر کے خلاف، میں نے کچھ بھی ناراض نہیں کیا۔\n9۔ لیکن فیسٹس، جو یہودیوں کو خوش کرنے کے لیے تیار تھا، نے جواب دیا اور کہا، کیا تم یروشلم جاؤ گے، اور وہاں میرے سامنے ان باتوں کا فیصلہ کیا جائے گا؟\n10۔ پھر پولس نے کہا، میں قیصر کے فیصلے کے مقام پر کھڑا ہوں، جہاں مجھے فیصلہ ہونا چاہیے: میں نے یہودیوں کے ساتھ کوئی ظلم نہیں کیا، جیسا کہ تم اچھی طرح جانتے ہو۔\n11۔ کیونکہ اگر میں مجرم ہوں، یا کوئی ایسا کام کر چکا ہوں جو موت کے لائق ہو، تو میں مرنے سے انکار کرتا ہوں: لیکن اگر ان میں سے کوئی بھی چیز نہ ہو جس کے بارے میں وہ مجھ پر الزام لگاتے ہیں، تو کوئی مجھے ان کے حوالے نہیں کر سکتا۔ میں سیزر سے اپیل کرتا ہوں۔\n12۔ پھر فیسٹس نے جب کونسل سے مشورہ کیا تو جواب دیا، کیا تم نے قیصر سے اپیل کی ہے؟ تم قیصر کے پاس جاؤ گے۔\n13۔ اور کچھ دنوں بعد بادشاہ اگریپا اور برنیس قیصریہ آئے تاکہ فیسٹس کو سلام کریں۔\n14۔ اور جب وہ کئی دن وہاں تھے، فیسٹس نے بادشاہ کے سامنے پولس کی بات سنائی، کہا، ایک شخص ہے جو فیلکس کی طرف سے بندھن میں چھوڑا گیا ہے:\n15۔ کس کے بارے میں، جب میں یروشلم میں تھا، سردار کاہنوں اور یہودیوں کے بزرگوں نے {مجھ سے} اطلاع دی، تاکہ {اس کے خلاف فیصلہ ہو} جائے۔\n16۔ جس سے میں نے جواب دیا، رومیوں کا طریقہ یہ نہیں کہ وہ کسی کو مرنے پر مجبور کریں، اس سے پہلے کہ ملزم کو الزام لگانے والوں کا سامنا کرنا ہو، اور اس کے خلاف کیے گئے جرم کے بارے میں خود جوابدہ ہونے کی اجازت ہو۔\n17۔ لہٰذا، جب وہ یہاں آئے، تو کل بغیر کسی تاخیر کے میں نے عدالت کی نشست پر بیٹھ کر حکم دیا کہ اس آدمی کو باہر لایا جائے۔\n18۔ جس کے خلاف جب الزام لگانے والے کھڑے ہوئے تو انہوں نے ایسی باتوں کا کوئی الزام نہیں لگایا جیسا کہ میں نے سمجھا:\n19۔ لیکن ان کے اپنے توہمات اور ایک یسوع کے بارے میں کچھ سوالات تھے، جو مر چکا تھا اور جسے پولوس نے زندہ قرار دیا تھا۔\n20۔ اور چونکہ مجھے ایسے سوالات پر شک تھا، میں نے {ان} سے پوچھا کہ کیا وہ یروشلم جائیں گے، اور وہاں ان معاملات پر فیصلہ کیا جائے گا۔ {مجھے شک تھا...: یا، مجھے شک تھا کہ اس بارے میں کیسے پوچھوں}\n21۔ لیکن جب پال نے آگسٹس کی سماعت کے لیے مخصوص رہنے کی درخواست کی، تو میں نے حکم دیا کہ اسے قیصر کے پاس بھیجنے تک رکھا جائے۔ {سماعت: یا، فیصلہ}\n22۔ پھر اگریپا نے فیسٹس سے کہا، میں بھی خود اس آدمی کی بات سنوں گا۔ کل کے لیے، اس نے کہا، تم اسے سنو گے۔\n23۔ اور کل جب اگریپا آیا، اور برنیس، بڑی شان و شوکت کے ساتھ، اور شہر کے چیف کپتانوں اور اہم لوگوں کے ساتھ سننے کی جگہ پر داخل ہوئے، تو فیسٹس کے حکم پر پال کو پیش کیا گیا۔\n24۔ اور فیسٹس نے کہا، بادشاہ اگریپا، اور تمام لوگ جو ہمارے ساتھ موجود ہیں، تم اس آدمی کو دیکھ رہے ہو، جس کے بارے میں تمام یہودیوں نے میرے ساتھ معاملہ کیا، یروشلم میں بھی، اور {یہاں بھی}، جو چیخ رہا ہے کہ اسے مزید زندہ نہیں رہنا چاہیے۔\n25۔ لیکن جب مجھے معلوم ہوا کہ اس نے موت کے لائق کچھ نہیں کیا، اور اس نے خود آگسٹس سے اپیل کی ہے، تو میں نے اسے بھیجنے کا فیصلہ کیا۔\n26۔ جس کے بارے میں میرے پاس اپنے آقا کو لکھنے کے لیے کوئی یقینی بات نہیں ہے۔ اسی لیے میں نے اسے تمہارے سامنے پیش کیا ہے، اور خاص طور پر تمہارے سامنے، اے بادشاہ اگریپا، تاکہ جانچ پڑتال کے بعد مجھے کچھ لکھنے کو ملے۔\n27۔ کیونکہ میرے خیال میں قیدی کو بھیجنا غیر معقول لگتا ہے، اور اس کے خلاف کیے گئے جرائم کی نشاندہی نہ کرے۔","1۔ پھر اگریپا نے پولس سے کہا، تمہیں اپنے لیے بولنے کی اجازت ہے۔ پھر پولوس نے ہاتھ بڑھایا اور خود جواب دیا:\n2۔ میں خود کو خوش سمجھتا ہوں، بادشاہ اگریپا، کیونکہ آج میں خود تمہارے سامنے ان تمام الزامات کا جواب دوں گا جن کے بارے میں مجھے یہودیوں کے بارے میں الزام دیا گیا ہے:\n3. خاص طور پر {کیونکہ میں جانتا ہوں} کہ تم یہودیوں کے درمیان موجود تمام رسم و رواج اور سوالات میں ماہر ہو: اسی لیے میں تم سے درخواست کرتا ہوں کہ صبر سے میری بات سنو۔\n4۔ میری جوانی سے زندگی کا انداز، جو سب سے پہلے یروشلم میں میری قوم میں تھا، تمام یہودیوں کو جانتا تھا؛\n5۔ جو مجھے شروع سے جانتا تھا، اگر وہ گواہی دیں، کہ ہمارے مذہب کے سب سے سخت فرقے کے بعد میں فریسی کی حیثیت رکھتا ہوں۔\n6۔ اور اب میں کھڑا ہوں اور خدا کے ہمارے آباؤ اجداد سے کیے گئے وعدے کی امید کے لیے فیصلہ کیا جا رہا ہوں:\n7۔ جس کے لیے ہمارے بارہ قبائل، جو خدا کی خدمت میں دن رات ہیں، امید کرتے ہیں کہ وہ آئیں گے۔ اسی امید کے لیے، بادشاہ اگریپا، مجھ پر یہودیوں کا الزام ہے۔ {دن اور رات: گری۔ رات اور دن}\n8. آپ کے لیے یہ کیوں ناقابل یقین سمجھا جائے کہ خدا مردوں کو زندہ کرے؟\n9۔ میں نے واقعی اپنے آپ سے سوچا کہ مجھے یسوع ناصری کے نام کے خلاف بہت سی چیزیں کرنی چاہئیں۔\n10۔ جو کچھ میں نے یروشلم میں بھی کیا: اور بہت سے مقدسین کو میں نے قید میں بند کر دیا، کیونکہ مجھے سردار کاہنوں سے اختیار ملا؛ اور جب انہیں قتل کر دیا گیا، میں نے ان کے خلاف اپنی آواز دی۔\n11۔ اور میں نے انہیں ہر عبادت گاہ میں بار بار سزا دی، اور انہیں کفر کرنے پر مجبور کیا؛ اور ان کے خلاف شدید پاگل ہونے کی وجہ سے، میں نے انہیں اجنبی شہروں تک بھی ستایا۔\n12۔ جب میں سردار کاهنوں کی اجازت اور حکم کے ساتھ دمشق گیا،\n13۔ دوپہر کے وقت، اے بادشاہ، میں نے راستے میں آسمان کی روشنی دیکھی، سورج کی روشنی کے اوپر، میرے گرد اور ان کے گرد جو میرے ساتھ سفر کر رہے تھے۔\n14۔ اور جب ہم سب زمین پر گر گئے، میں نے ایک آواز سنی جو مجھ سے بات کر رہی تھی، اور عبرانی زبان میں کہہ رہی تھی، ساؤل، ساؤل، تم مجھے کیوں ستاتے ہو؟ {تمہارے لیے ان کمینوں کے خلاف لات مارنا مشکل ہے۔\n15۔ اور میں نے کہا، اے خداوند، تو کون ہو؟ اور اس نے کہا، میں وہ یسوع ہوں جسے تم ستاتے ہو۔\n16. لیکن اٹھو اور اپنے قدموں پر کھڑے ہو جاؤ، کیونکہ میں نے تمہیں اس مقصد کے لیے ظاہر کیا ہے، تاکہ تمہیں وزیر اور گواہ بناؤں ان دونوں باتوں کی جو تم نے دیکھی ہیں، اور ان چیزوں کی جن میں میں تمہیں دکھاؤں گا؛\n17۔ تمہیں لوگوں سے اور غیر قوموں سے نجات دوں، جن کے پاس میں اب تمہیں بھیجتا ہوں،\n18۔ ان کی آنکھیں کھولوں، {اور} اندھیرے سے روشنی میں بدل دوں، اور شیطان کی طاقت سے خدا کی طرف لے جاؤں، تاکہ وہ گناہوں کی معافی اور ان میں وراثت حاصل کر سکیں جو ایمان سے پاک ہیں۔\n19۔ اس لیے، اے بادشاہ اگریپا، میں آسمانی خواب کی نافرمانی نہیں کر سکا:\n20. لیکن پہلے دمشق، یروشلم میں، یہودیہ کے تمام ساحلوں پر، اور پھر غیر قوموں کو دکھایا کہ وہ توبہ کریں، خدا کی طرف رجوع کریں، اور توبہ کے لیے کام کریں۔\n21۔ انہی وجوہات کی بنا پر یہودیوں نے مجھے مندر میں پکڑ لیا اور مجھے مارنے لگے۔\n22۔ لہٰذا خدا کی مدد حاصل کرنے کے بعد، میں آج تک چھوٹے اور بڑے دونوں کو گواہی دیتا ہوں، اور صرف وہ باتیں کہتا ہوں جو نبیوں اور موسیٰ نے کہا تھا:\n23۔ کہ مسیح تکلیف اٹھائے، {اور} کہ وہ سب سے پہلے مردوں میں سے زندہ ہو، اور لوگوں اور غیر قوموں کو روشنی دکھائے۔\n24۔ اور جب وہ اپنے لیے بول رہا تھا، تو فیسٹس نے بلند آواز میں کہا، پولس، تم اپنے آپ سے باہر ہو؛ بہت سی تعلیم تمہیں غصہ دلاتی ہے۔\n25۔ لیکن اس نے کہا، میں پاگل نہیں ہوں، سب سے معزز فیسٹس؛ بلکہ سچائی اور سنجیدگی کے الفاظ بولو۔\n26۔ کیونکہ بادشاہ ان باتوں سے واقف ہے، جس کے سامنے میں بھی کھل کر بات کرتا ہوں: کیونکہ میں قائل ہوں کہ ان میں سے کوئی چیز اس سے چھپی نہیں ہے؛ کیونکہ یہ کام کونے میں نہیں کیا گیا تھا۔\n27۔ بادشاہ اگریپا، کیا تم انبیاء پر ایمان رکھتے ہو؟ میں جانتا ہوں کہ تم ایمان رکھتے ہو۔\n28۔ پھر اگریپا نے پولس سے کہا، تقریبا تم مجھے مسیحی بننے پر قائل کر لیتے ہو۔\n29۔ اور پولس نے کہا، میں خدا سے دعا کرتا ہوں کہ نہ صرف تم بلکہ آج جو لوگ مجھے سنتے ہیں، دونوں تقریبا اور سب کچھ میرے جیسے ہوں، سوائے ان بندھنوں کے۔\n30۔ اور جب اس نے یہ کہا، بادشاہ اٹھا، گورنر، برنیس، اور جو ان کے ساتھ بیٹھے تھے:\n31۔ اور جب وہ چلے گئے، تو انہوں نے آپس میں بات کی، کہنے لگے، یہ آدمی موت یا بندھن کے لائق کچھ نہیں کرتا۔\n32۔ پھر اگریپا نے فیسٹس سے کہا، اگر اس نے قیصر سے اپیل نہ کی ہوتی تو یہ آدمی رہا ہو سکتا تھا۔","1۔ اور جب فیصلہ ہوا کہ ہمیں اٹلی جانا چاہیے، تو انہوں نے پال اور کچھ دیگر قیدیوں کو آگسٹس کے گروہ کا سینچورین جولیس کے حوالے کر دیا۔\n2۔ اور ایڈرامیٹیم کے جہاز میں سوار ہو کر، ہم نے لانچ کیا، جس کا مقصد ایشیا کے ساحلوں سے گزرنا تھا؛ {ایک} اریسٹارکس، جو تھیسالونیکا کا مقدونی تھا، ہمارے ساتھ تھا۔\n3۔ اور اگلے دن ہم نے سیدون کو چھوا۔ اور جولیس نے شائستگی سے پال سے درخواست کی، اور اسے اپنے دوستوں کے پاس جا کر تازہ دم ہونے کی اجازت دی۔\n4۔ اور جب ہم وہاں سے روانہ ہوئے، تو ہم قبرص کے نیچے سے گزرے، کیونکہ ہوائیں مخالف تھیں۔\n5۔ اور جب ہم سیلیشیا اور پامفیلیا کے سمندر کے پار روانہ ہوئے، تو ہم مائرا پہنچے، جو لیشیا کا ایک شہر ہے۔\n6۔ اور وہاں سینچورین نے اسکندریہ کا ایک جہاز اٹلی میں داخل ہوتے پایا؛ اور اس نے ہمیں اس میں ڈال دیا۔\n7۔ اور جب ہم کئی دن آہستہ آہستہ سفر کر چکے تھے، اور کنیڈس کے خلاف کم ہی آ گئے، ہوا ہمیں متاثر نہ کر رہی تھی، تو ہم کریٹ کے نیچے سے روانہ ہوئے، سالمون کی طرف؛ {کریٹ: یا، کینڈی}\n8۔ اور، بمشکل ہی گزرتے ہوئے، ایک جگہ پہنچے جسے 'فیئر ہیونز' کہا جاتا ہے؛ قریب ہی لاسیا کا شہر تھا۔\n9۔ اب جب بہت وقت گزر گیا، اور جب روانگی خطرناک ہو گئی تھی، کیونکہ روزہ ختم ہو چکا تھا، پولوس نے {انہیں} کو نصیحت کی، {روزہ: روزہ ساتویں مہینے کے دسویں دن تھا}\n10۔ اور میں نے ان سے کہا، جنابوں، مجھے لگتا ہے کہ یہ سفر نہ صرف سامان اور جہاز بلکہ ہماری جانوں کو بھی نقصان پہنچائے گا۔ {زخمی: یا، چوٹ}\n11۔ پھر بھی، سینچورین نے جہاز کے مالک اور کپتان پر یقین کیا، ان باتوں سے زیادہ جو پولس نے کہی تھیں۔\n12۔ اور چونکہ پناہ گاہ سردیوں میں گزارنے کے لیے موزوں نہیں تھی، اس لیے زیادہ تر لوگوں کو مشورہ دیا گیا کہ وہ وہاں سے بھی روانہ ہو جائیں، اگر کسی بھی طرح فینیس پہنچ سکیں، {اور وہاں سردیوں کے لیے}؛ {جو کہ} کریٹ کا ایک پناہ گاہ ہے، اور جنوب مغرب اور شمال مغرب کی طرف واقع ہے۔\n13۔ اور جب جنوبی ہوا ہلکی سی چل رہی تھی، یہ سمجھتے ہوئے کہ انہوں نے اپنا مقصد حاصل کر لیا ہے، اور {وہاں سے} کھو دیا، تو وہ کریٹ کے قریب سے روانہ ہوئے۔\n14۔ لیکن کچھ ہی دیر بعد اس کے خلاف ایک طوفانی ہوا اٹھی، جسے یوروکلائیڈن کہا جاتا ہے۔ {ابھرو: یا، بیٹ}\n15۔ اور جب جہاز پھنس گیا اور ہوا میں برداشت نہ کر سکا، تو ہم نے {اسے} کو چلنے دیا۔\n16۔ اور ایک خاص جزیرے کے نیچے چلتے ہوئے، جسے کلاؤڈا کہا جاتا ہے، ہمیں کشتی کے ذریعے بہت کام کرنا تھا:\n17۔ جب انہوں نے جہاز کو سنبھالا تو انہوں نے جہاز کی بنیاد رکھی؛ اور، اس خوف سے کہ کہیں وہ دلدل ریت میں نہ گر جائیں، اس لیے انہیں دھکیل دیا گیا۔\n18۔ اور جب ہمیں شدید طوفان کا سامنا کرنا پڑا، اگلے {دن} انہوں نے جہاز کو ہلکا کر دیا؛\n19۔ اور تیسرے دن ہم نے اپنے ہاتھوں سے جہاز کی لہر پھینک دی۔\n20۔ اور جب کئی دنوں تک نہ سورج نمودار ہوا اور نہ ہی ستارے، اور ہم پر کوئی چھوٹا طوفان نہ آیا، تو پھر ہماری نجات کی تمام امید ختم ہو گئی۔\n21۔ لیکن طویل پرہیز کے بعد پولس ان کے درمیان کھڑا ہوا اور کہا، جنابوں، آپ کو میری بات سننی چاہیے تھی، اور کریٹ سے فرار نہ ہو کر یہ نقصان اور نقصان برداشت کرنا چاہیے تھا۔\n22۔ اور اب میں آپ کو نصیحت کرتا ہوں کہ خوش رہیں: کیونکہ آپ میں سے کسی کی جان ضائع نہیں ہوگی، سوائے جہاز کے۔\n23۔ کیونکہ اس رات میرے ساتھ خدا کا فرشتہ کھڑا تھا، جس کی میں ہوں، اور جس کی میں عبادت کرتا ہوں،\n24۔ کہا، ڈر مت، پولس؛ تمہیں قیصر کے سامنے پیش کیا جانا چاہیے: اور دیکھو، خدا نے تمہیں وہ سب دے دیے ہیں جو تمہارے ساتھ سفر کرتے ہیں۔\n25۔ لہٰذا، حضرات، خوش رہیں: کیونکہ میں خدا پر ایمان رکھتا ہوں کہ یہ ویسا ہی ہوگا جیسا مجھے بتایا گیا تھا۔\n26۔ تاہم ہمیں ایک خاص جزیرے پر پھینکا جانا چاہیے۔\n27۔ لیکن جب چودہویں رات آئی، جب ہمیں ایڈریا میں اوپر نیچے لے جایا جا رہا تھا، تقریبا آدھی رات کے قریب جہاز رانوں نے سمجھا کہ وہ کسی علاقے کے قریب پہنچ گئے ہیں؛\n28۔ اور اس نے غور کیا، اور بیس فیتھم تک پہنچا: اور جب وہ تھوڑا آگے گئے تو دوبارہ کوشش کی، اور اسے پندرہ فیتھم پایا۔\n29۔ پھر، اس خوف سے کہ کہیں ہم پتھروں پر نہ گر جائیں، انہوں نے جہاز کے پچھلے حصے سے چار لنگر نکالے اور دن کی دعا کی۔\n30۔ اور جب جہاز والے جہاز سے بھاگنے ہی والے تھے، تو انہوں نے کشتی کو سمندر میں اتارا، رنگ کے نیچے جیسے وہ اگلے جہاز سے لنگر ڈالنا چاہتے ہوں،\n31۔ پولوس نے سینچورین اور سپاہیوں سے کہا، جب تک یہ جہاز میں نہ رہیں، تم بچ نہیں سکتے۔\n32۔ پھر سپاہیوں نے کشتی کی رسیاں کاٹ دیں اور اسے گرنے دیا۔\n33۔ اور جب دن آ رہا تھا، پولوس نے سب سے گوشت لینے کی درخواست کی، اور کہا، آج چودہواں دن ہے کہ تم نے کچھ نہیں لیا اور روزہ رکھا ہے۔\n34۔ اسی لیے میں تم سے دعا کرتا ہوں کہ کچھ گوشت لے لو: کیونکہ یہ تمہاری صحت کے لیے ہے: کیونکہ تم میں سے کسی کے سر سے ایک بال بھی نہیں گرے گا۔\n35۔ اور جب اس نے یہ کہا، تو اس نے روٹی لی، اور سب کے سامنے خدا کا شکر ادا کیا، اور جب اس نے روٹی توڑ دی تو کھانا شروع کیا۔\n36۔ پھر وہ سب خوش مزاج تھے، اور انہوں نے {کچھ} گوشت بھی لیا۔\n37۔ اور ہم جہاز میں کل ملا کر دو سو تین سو سولہ جانیں تھیں۔\n38۔ اور جب وہ کافی کھا گئے، تو انہوں نے جہاز کو ہلکا کیا اور گندم کو سمندر میں پھینک دیا۔\n39۔ اور جب دن آیا، تو وہ زمین کو نہیں جانتے تھے: لیکن انہوں نے ایک خاص ندی دریافت کی جس کا کنارہ تھا، جس میں وہ چاہتے تھے کہ اگر ممکن ہو تو کشتی میں گاڑ سکیں۔\n40۔ اور جب انہوں نے لنگر اٹھا لیے، تو وہ خود کو سمندر کی طرف لگا دیے، اور روڈر بینڈز کھولے، مین سیل کو ہوا کے مطابق اٹھایا اور کنارے کی طرف بڑھے۔ {لیا گیا...: یا، لنگر کاٹ دیے، انہیں سمندر میں چھوڑ دیا}\n41۔ اور دو سمندر ملنے والی جگہ پر گر کر جہاز کو زمین پر چلا گیا؛ اور اگلا حصہ مضبوطی سے چپک گیا، اور ناقابل حرکت رہا، لیکن پچھلا حصہ لہروں کی شدت سے ٹوٹ گیا۔\n42۔ اور سپاہیوں کا مشورہ تھا کہ قیدیوں کو مار ڈالیں، ورنہ کوئی تیر کر باہر نکل جائے گا اور فرار ہو جائے گا۔\n43۔ لیکن سینچورین، جو پال کو بچانے کے لیے تیار تھا، نے انہیں ان کے مقصد سے روکا؛ اور حکم دیا کہ جو تیر سکتے ہیں وہ پہلے خود کو سمندر میں پھینکیں اور زمین پر پہنچیں:\n44۔ اور باقی، کچھ بورڈز پر، اور کچھ جہاز کے {ٹوٹے ہوئے ٹکڑوں} پر۔ اور یوں وہ سب محفوظ طریقے سے اتر گئے۔","1۔ اور جب وہ فرار ہوئے، تو انہیں معلوم ہوا کہ جزیرے کا نام میلیٹا ہے۔\n2۔ اور وحشی لوگوں نے ہم پر کوئی خاص مہربانی کی: کیونکہ انہوں نے آگ جلائی، اور ہمیں سب کو قبول کیا، موجودہ بارش اور سردی کی وجہ سے۔\n3۔ اور جب پولوس نے لکڑیوں کا گٹھا جمع کیا اور آگ پر رکھا، تو گرمی سے ایک سانپ نکلا اور اس کے ہاتھ پر باندھ لیا۔\n4۔ اور جب وحشیوں نے اس {زہریلا} درندے کو اپنے ہاتھ پر لٹکتے دیکھا، تو انہوں نے آپس میں کہا، یقینا یہ آدمی قاتل ہے، جو اگرچہ سمندر سے بچ نکلا ہے، لیکن انتقام زندہ رہنے کی اجازت نہیں دیتا۔\n5۔ اور اس نے درندے کو آگ میں جھٹک دیا، اور کوئی نقصان محسوس نہ ہوا۔\n6۔ جیسے بھی وہ دیکھتے تھے کہ وہ کب سوجا ہوا یا اچانک مر گیا تھا: لیکن جب انہوں نے کافی دیر تک دیکھا اور اسے کوئی نقصان نہیں پہنچا، تو انہوں نے اپنا ارادہ بدل لیا اور کہا کہ وہ ایک خدا ہے۔\n7۔ انہی کوارٹرز میں جزیرے کے سردار کی جائیدادیں تھیں، جس کا نام پبلیئس تھا؛ جنہوں نے ہمیں خوش آمدید کہا، اور تین دن مہذب انداز میں رہائش دی۔\n8۔ اور ایسا ہوا کہ پبلیوس کے والد بخار اور خون آلود بیماری میں مبتلا تھے: جس کے پاس پولس آیا، دعا کی، اس پر ہاتھ رکھے اور شفا دی۔\n9۔ جب یہ سب ہوا، تو جزیرے میں بیماریاں رکھنے والے دوسرے بھی آئے اور شفا پائیں:\n10۔ جس نے ہمیں کئی اعزازات سے نوازا؛ اور جب ہم روانہ ہوئے، تو انہوں نے ہمیں وہ چیزیں دی جو ضروری تھیں۔\n11۔ اور تین ماہ بعد ہم اسکندریہ کے ایک جہاز میں روانہ ہوئے، جو جزیرے میں سردیوں میں گزار چکا تھا، جس کا نشان کاسٹر اور پولکس تھا۔\n12۔ اور سیرکیوز پر لینڈنگ کرتے ہوئے، ہم تین دن رہے۔\n13۔ اور وہاں سے ہم نے ایک قطب نما لیا اور ریگیوم پہنچے: اور ایک دن بعد جنوبی ہوا چلائی، اور ہم اگلے دن پوتیولی پہنچے:\n14۔ جہاں ہمیں بھائی ملے، اور ان کے ساتھ سات دن رکنے کی خواہش کی گئی: اور یوں ہم روم کی طرف روانہ ہوئے۔\n15۔ اور وہاں سے، جب بھائیوں نے ہمارے بارے میں سنا، تو وہ ہمیں اپی فورم اور تینوں سرائے تک ملنے آئے، جنہیں پولوس نے دیکھا تو خدا کا شکر ادا کیا اور حوصلہ کیا۔\n16۔ اور جب ہم روم پہنچے، تو سینچورین نے قیدیوں کو گارڈ کے کپتان کے حوالے کیا: لیکن پال کو ایک سپاہی کے ساتھ اکیلا رہنے دیا گیا جو اسے رکھتا تھا۔\n17۔ اور ایسا ہوا کہ تین دن بعد پولوس نے یہودیوں کے سردار کو اکٹھا کیا: اور جب وہ اکٹھے ہوئے تو انہوں نے کہا، اے لوگ {اور} بھائیو، اگرچہ میں نے لوگوں یا ہمارے آباؤ اجداد کے رسم و رواج کے خلاف کچھ نہیں کیا، پھر بھی میں یروشلم سے رومیوں کے ہاتھوں قیدی بن گیا۔\n18۔ جو جب انہوں نے میرا معائنہ کیا تھا، تو مجھے جانے دیتا، کیونکہ میرے اندر موت کی کوئی وجہ نہیں تھی۔\n19۔ لیکن جب یہودیوں نے اس کے خلاف بات کی، تو مجھے قیصر سے اپیل کرنے پر مجبور کیا گیا؛ حالانکہ مجھے اپنی قوم پر الزام نہیں لگانا چاہیے تھا۔\n20۔ اسی مقصد کے لیے میں نے تمہیں بلایا ہے کہ تم سے ملو اور تمہارے ساتھ بات کروں: کیونکہ اسرائیل کی امید کے لیے میں اس زنجیر سے بندھا ہوا ہوں۔\n21۔ اور انہوں نے اس سے کہا، ہمیں یہودیہ کی طرف سے تمہارے بارے میں کوئی خط موصول نہیں ہوا، نہ ہی آنے والے بھائیوں میں سے کسی نے تمہیں کوئی برا سلوک یا برا سلوک کیا۔\n22. لیکن ہم آپ کے بارے میں سننا چاہتے ہیں کہ آپ کیا سوچتے ہیں: کیونکہ اس فرقے کے بارے میں، ہم جانتے ہیں کہ جہاں بھی اس کے خلاف بات کی جاتی ہے۔\n23۔ اور جب انہوں نے اسے ایک دن مقرر کیا، تو بہت سے لوگ اس کے گھر آئے؛ جن کے سامنے انہوں نے خدا کی بادشاہی کی وضاحت اور گواہی دی، انہیں یسوع کے بارے میں صبح سے شام تک موسیٰ کے قانون اور انبیاء دونوں کے بارے میں قائل کیا۔\n24۔ اور کچھ نے ان باتوں پر یقین کیا جو کہی گئیں، اور کچھ نے نہیں۔\n25۔ اور جب انہوں نے آپس میں اتفاق نہ کیا، تو وہ روانہ ہو گئے، جب پولس نے ایک لفظ کہا، \"روح القدس نے اشیاس نبی نے ہمارے آباؤ اجداد سے کہا،\n26۔ کہتا ہے، اس قوم کے پاس جاؤ اور کہو، سنو گے، اور سمجھو گے نہیں؛ اور دیکھتے ہوئے دیکھو گے، نہ دیکھو گے:\n27۔ کیونکہ اس قوم کا دل موم سے بھرا ہوا ہے، ان کے کان سننے سے مدھم ہیں، اور ان کی آنکھیں بند ہیں؛ تاکہ وہ {اپنی} آنکھوں سے دیکھیں، اور {اپنی} کانوں سے سنیں، اور {اپنی} دل سے سمجھیں، اور وہ تبدیل ہو جائیں، اور میں انہیں شفا دوں۔\n28۔ لہٰذا تمہیں معلوم رہے کہ خدا کی نجات غیر یہودیوں کو بھیجی گئی ہے، اور وہ اسے سنیں گے۔\n29۔ اور جب اس نے یہ الفاظ کہے، یہودی روانہ ہو گئے، اور آپس میں بڑی بحث ہوئی۔\n30۔ اور پولس نے اپنے کرائے کے گھر میں دو سال مکمل سال گزارے، اور جو کچھ بھی اس کے پاس آیا، اس نے قبول کیا،\n31۔ خدا کی بادشاہی کی تبلیغ کرنا، اور وہ باتیں سکھانا جو خداوند یسوع مسیح سے متعلق ہیں، پورے اعتماد کے ساتھ، کوئی اسے منع نہ کرے۔"];
